// StartController validates one region-bound reconciler. Run owns the periodic
// lifecycle; Tick is exposed for deterministic callers and tests.
func StartController(ctx context.Context, config Config, store Store, fencer authority.Fencer, fleet oci.Fleet, hosts HostView, desired DesiredWriter, resolveArtifact ArtifactResolver) (*Controller, error) {
	if ctx == nil || ctx.Err() != nil {
		return nil, errors.New("placement controller requires a live context")
	}
	if err := config.validate(); err != nil {
		return nil, err
	}
	if store == nil || fencer == nil || fleet == nil || hosts == nil || desired == nil || resolveArtifact == nil {
		return nil, errors.New("placement controller requires durable state, authority, OCI fleet, host view, desired writer and artifact admission")
	}
	if fleet.Region() != config.Region {
		return nil, errors.New("placement controller region differs from its pinned OCI fleet")
	}
	if config.TickInterval == 0 {
		config.TickInterval = defaultTickInterval
	}
	return &Controller{config: config, store: store, fencer: fencer, fleet: fleet, hosts: hosts, desired: desired, resolveArtifact: resolveArtifact}, nil
}

func (config Config) validate() error {
	if !validToken(config.Cell) || !knownRegion(config.Region) || !validToken(config.ManagedOwner) ||
		!validToken(config.Environment) || !validToken(config.MemberRole) || config.FleetGeneration == 0 ||
		!strings.HasPrefix(config.ImageID, "ocid1.image.") || len(config.ImageID) > 255 || strings.ContainsAny(config.ImageID, " \t\r\n") ||
		!positive(config.Resources) ||
		config.Resources.CPU > 4096 || config.Resources.MemoryBytes > 1<<50 || config.Resources.DiskBytes > 1<<50 {
		return errors.New("placement controller config has an invalid cell, region, owner, role, or resource profile")
	}
	if err := config.VolumeDeadlines.Validate(); err != nil {
		return err
	}
	if config.LostMemberGrace < 0 || config.LostMemberGrace > 7*24*time.Hour {
		return errors.New("placement lost member grace must be between zero and seven days")
	}
	if config.TickInterval < 0 || config.TickInterval != 0 && (config.TickInterval < minTickInterval || config.TickInterval > maxTickInterval) {
		return errors.New("placement tick interval must be zero or between 100ms and 5m")
	}
	if len(config.FaultDomains) < 2 || len(config.FaultDomains) > 3 || config.FaultDomains[0] == config.FaultDomains[1] {
		return errors.New("placement region requires at least two distinct OCI fault domains")
	}
	for _, domain := range config.FaultDomains {
		if len(domain) != len("FAULT-DOMAIN-1") || !strings.HasPrefix(domain, "FAULT-DOMAIN-") || domain[len(domain)-1] < '1' || domain[len(domain)-1] > '3' {
			return fmt.Errorf("invalid configured OCI fault domain %q", domain)
		}
	}
	return nil

func (controller *Controller) Tick(ctx context.Context) error {
	if controller == nil || ctx == nil {
		return errors.New("placement controller and context are required")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	snapshot := controller.fencer.Current()
	if !snapshot.CanMutate() {
		return nil
	}
	epoch := snapshot.Epoch
	intents, err := controller.store.ListIntents(ctx)
	if err != nil {
		return err
	}
	if len(intents) > maxIntentCount {
		return errors.New("placement intent list exceeds its safety bound")
	}
	instances, err := controller.fleet.Observe(oci.WithCachedVerification(ctx))
	if err != nil {
		return fmt.Errorf("observe region-bound OCI fleet: %w", err)
	}
	instanceByID := make(map[string]oci.Instance, len(instances))
	for _, instance := range instances {
		if instance.ID == "" || instance.Node == "" || instance.Region != controller.config.Region || instance.ETag == "" {
			return errors.New("OCI fleet returned an incomplete or cross-region instance")
		}
		if _, exists := instanceByID[instance.ID]; exists {
			return fmt.Errorf("OCI fleet returned duplicate instance %q", instance.ID)
		}
		instanceByID[instance.ID] = instance
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return fmt.Errorf("read current host registrations and reports: %w", err)
	}
	statusByNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		node := status.Registration.Node
		if node == "" {
			return errors.New("host view returned a registration without a node")
		}
		if _, exists := statusByNode[node]; exists {
			return fmt.Errorf("host view returned duplicate node %q", node)
		}
		statusByNode[node] = status
	}
	seenIntents := make(map[string]struct{}, len(intents))
	// A failing placement must not starve independent ones: its error is
	// reported with the pass while later placements still advance.
	var placementErrs []error
intents:
	for _, intent := range intents {
		if err := intent.Validate(); err != nil {
			return err
		}
		identity := intent.DatabaseID + "\x00" + intent.PartitionID
		if _, exists := seenIntents[identity]; exists {
			return fmt.Errorf("%w: duplicate database/partition intent", ErrInvalidIntent)
		}
		seenIntents[identity] = struct{}{}
		if _, err := controller.store.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			controller.hold(fmt.Sprintf("database %s/%s has a committed terminal teardown fence", intent.DatabaseID, intent.PartitionID))
			continue
		} else if !errors.Is(err, authority.ErrNotFound) {
			return fmt.Errorf("read terminal workload fence for %s/%s: %w", intent.DatabaseID, intent.PartitionID, err)
		}
		if intent.SchemaVersion != IntentSchemaVersion || intent.PayloadDigest() == "" {
			controller.hold(fmt.Sprintf("database %s/%s has no admitted managed placement profile; host reconciliation is held", intent.DatabaseID, intent.PartitionID))
			continue
		}
		if len(intent.ActiveRegions) != 1 {
			controller.hold(fmt.Sprintf("database %s/%s has %d regions; current TerraBase outbound sender supports exactly two members in one region", intent.DatabaseID, intent.PartitionID, len(intent.ActiveRegions)))
			continue
		}
		members, err := controller.store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return err
		}
		if len(members) > maxMemberStates {
			return fmt.Errorf("placement member state for %s/%s exceeds its bound", intent.DatabaseID, intent.PartitionID)
		}
		if !slices.Contains(intent.ActiveRegions, controller.config.Region) {
			if len(members) > 0 && controller.config.OnHold != nil {
				controller.config.OnHold(fmt.Sprintf("database %s/%s regional retirement is held; trusted replication, quorum, drain, writer-stop, and retained-volume evidence is required", intent.DatabaseID, intent.PartitionID))
			}
			continue
		}
		seats, err := controller.localSeats(intent)
		if err != nil {
			return err
		}
		rosterDigest, err := intent.CanonicalRosterDigest()
		if err != nil {
			return err
		}
		rowsBySeat := make(map[string]CanonicalRosterRow, len(seats))
		manifestsBySeat := make(map[string]RuntimeManifest, len(seats))
		manifestDigestsBySeat := make(map[string]string, len(seats))
		rosterHeld := false
		for _, seat := range seats {
			row, err := intent.RosterRowForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed roster row matching its configured seat; host reconciliation is held: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			rowsBySeat[seat.MemberID] = row
			manifest, err := intent.RuntimeManifestForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed runtime manifest: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			manifestDigest, err := manifest.Digest()
			if err != nil {
				return err
			}
			manifestsBySeat[seat.MemberID] = manifest
			manifestDigestsBySeat[seat.MemberID] = manifestDigest
		}
		if rosterHeld {
			continue
		}
		profile, err := intent.ManagedHostProfile(controller.config.Region)
		if err != nil {
			return err
		}
		profileDigest, err := profile.ProfileDigest()
		if err != nil {
			return err
		}
		memberByID := make(map[string]VersionedMemberState, len(members))
		for _, member := range members {
			if member.State.DatabaseID != intent.DatabaseID || member.State.PartitionID != intent.PartitionID {
				return fmt.Errorf("%w: member state escaped database/partition scope", ErrStoreCorrupt)
			}
			if _, exists := memberByID[member.State.MemberID]; exists {
				return fmt.Errorf("%w: duplicate member state %q", ErrStoreCorrupt, member.State.MemberID)
			}
			memberByID[member.State.MemberID] = member
		}
		held := false
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				continue
			}
			state := versioned.State
			if state.Region != seat.Region || state.Kind != seat.Kind || state.FailureDomain != seat.FailureDomain {
				return fmt.Errorf("%w: admitted placement seat conflicts with durable member identity", ErrStoreCorrupt)
			}
			if state.SchemaVersion != managedUpdateMemberStateSchemaVersion ||
				state.CanonicalRosterRow != rowsBySeat[seat.MemberID] ||
				state.RuntimeManifest != manifestsBySeat[seat.MemberID] ||
				state.RuntimeManifestDigest != manifestDigestsBySeat[seat.MemberID] ||
				state.CanonicalRosterDigest != rosterDigest ||
				state.AuthorityReference != intent.CanonicalRoster.Authority ||
				state.IntentPayloadDigest == "" || state.ManagedHostProfileDigest == "" ||
				state.IntentPayloadDigest != intent.PayloadDigest() || state.ManagedHostProfile != profile ||
				state.ManagedHostProfileDigest != profileDigest || state.IntentGeneration != intent.Generation {
				controller.hold(fmt.Sprintf("member %s has no matching immutable roster, authority reference, or placement profile; an explicit new attempt is required", seat.MemberID))
				held = true
				break
			}
			if state.Stage == StageRemoved {
				controller.hold(fmt.Sprintf("removed member %s requires an explicit reconciled new attempt", seat.MemberID))
				held = true
				break
			}
		}
		if held {
			continue
		}
		managedUpdateActed, err := controller.reconcileManagedUpdate(ctx, epoch, intent, seats, memberByID)
		if err != nil {
			placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
			continue
		}
		if managedUpdateActed {
			return errors.Join(placementErrs...)
		}
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				state := controller.initialState(intent, seat, rowsBySeat[seat.MemberID], rosterDigest,
					profile, profileDigest, manifestsBySeat[seat.MemberID], manifestDigestsBySeat[seat.MemberID], 1)
				if _, err := controller.persist(ctx, epoch, 0, state); err != nil {
					return errors.Join(append(placementErrs, err)...)
				}
				return errors.Join(placementErrs...)
			}
			acted, err := controller.replaceLostMember(ctx, epoch, intent, seat, versioned, seats, memberByID,
				instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
			acted, err = controller.advanceMember(ctx, epoch, intent, seat, versioned, instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
		}
	}
	return errors.Join(placementErrs...)
}

func (controller *Controller) advanceMember(
	ctx context.Context,
	epoch uint64,
	intent Intent,
	seat Seat,
	versioned VersionedMemberState,
	instances map[string]oci.Instance,
	statuses map[string]host.HostStatus,
) (bool, error) {
	state := versioned.State
	if state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatHeld {
		controller.hold(fmt.Sprintf("managed update %s is durably held: %s",
			state.ManagedRuntimeTarget.OperationID, state.ManagedRuntimeTarget.Outcome))
		return false, nil
	}
	switch state.Stage {
	case StagePreparedHost:
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
		if err != nil {
			return false, fmt.Errorf("ensure TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
			return false, err
		}
		state.Stage = StageAwaitingHost
		state.HostNode = instance.Node
		state.InstanceID = instance.ID
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "host")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingHost:
		instance, exists := instances[state.InstanceID]
		if !exists {
			// Retrying EnsureHost with the same durable create key recovers an
			// unknown launch outcome without adopting a tag-matched resource.
			if !controller.runtimeArtifactReady(ctx, state, seat) {
				return false, nil
			}
			if err := controller.guard(ctx, epoch); err != nil {
				return false, err
			}
			instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
			if err != nil {
				return false, fmt.Errorf("recover TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
			}
			if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
				return false, err
			}
			state.HostNode, state.InstanceID, state.InstanceETag = instance.Node, instance.ID, instance.ETag
			_, err = controller.persist(ctx, epoch, versioned.Revision, state)
			return true, err
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted {
			return false, nil
		}
		if state.VolumeID == "" {
			state.Stage = StagePreparedVolume
		} else {
			state.Stage = StagePreparedAttach
		}
		state.HostGeneration = status.Registration.Generation
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "admitted")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StagePreparedVolume:
		if _, exists := instances[state.InstanceID]; !exists {
			controller.hold(fmt.Sprintf("member %s OCI host is not currently observed; retained volume creation is withheld", seat.MemberID))
			return false, nil
		}
		var sizeGB int64
		if state.VolumeID == "" {
			var err error
			sizeGB, err = volumeSizeGB(controller.config.Resources.DiskBytes)
			if err != nil {
				return false, err
			}
			if !controller.runtimeArtifactReady(ctx, state, seat) {
				return false, nil
			}
		}
		instance, fresh, err := controller.freshVolumeHost(ctx, intent, seat, state)
		if err != nil {
			return false, err
		}
		if !fresh {
			return false, nil
		}
		// The member's own host image must qualify before its volume is
		// created or attached.
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if state.VolumeID != "" {
			state.Stage = StagePreparedAttach
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach")
			_, err := controller.persist(ctx, epoch, versioned.Revision, state)
			return true, err
		}
		// Admission may change during the live OCI reads.
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		member, err := seatMemberName(seat.Region, seat.MemberID)
		if err != nil {
			return false, err
		}
		// A member name always has a data name; the fleet checks it again.
		name, _ := naming.Data(member)
		volume, err := controller.fleet.CreateRetainedVolume(ctx, oci.VolumeCreateRequest{
			Name: name, DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
			MemberID:  seat.MemberID,
			CreateKey: volumeCreateKey(intent, seat), SizeGB: sizeGB,
		})
		if err != nil {
			return false, fmt.Errorf("create or recover retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		if volume.ID == "" || volume.CreateKey != volumeCreateKey(intent, seat) || volume.Region != controller.config.Region ||
			volume.Owner != controller.config.ManagedOwner || volume.Generation != controller.config.FleetGeneration {
			return false, errors.New("OCI fleet returned a retained volume with mismatched durable identity")
		}
		if volume.SizeGB < sizeGB {
			// The volume was created under an earlier, smaller resource profile.
			if _, fresh, err := controller.freshVolumeHost(ctx, intent, seat, state); err != nil {
				return false, err
			} else if !fresh {
				return false, nil
			}
			grown, err := controller.growVolume(ctx, epoch, intent, volume, sizeGB)
			if err != nil {
				return false, fmt.Errorf("retained member volume %s/%s is %d GiB, below the desired %d GiB: %w",
					intent.DatabaseID, seat.MemberID, volume.SizeGB, sizeGB, err)
			}
			if grown.ID != volume.ID || grown.SizeGB < sizeGB {
				return false, errors.New("OCI fleet returned a resized retained volume with mismatched durable identity")
			}
		}
		state.VolumeID = volume.ID
		state.Stage = StagePreparedAttach
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StagePreparedAttach:
		instance, exists := instances[state.InstanceID]
		if !exists {
			// An instance with an ATTACHING volume is withheld from
			// observation; a requested attach still runs against its
			// deadline.
			controller.holdStalledAttachRequest(seat.MemberID, state)
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			return false, nil
		}
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if state.PreviousInstanceID != "" {
			return controller.reattachRetainedVolume(ctx, epoch, intent, seat, versioned)
		}
		var attachment *oci.Attachment
		for index := range instance.Attachments {
			if instance.Attachments[index].VolumeID == state.VolumeID {
				if instance.Attachments[index].InstanceID != state.InstanceID {
					return false, oci.ErrRetainedVolumeInUse
				}
				attachment = &instance.Attachments[index]
				break
			}
		}
		if attachment == nil {
			if state.AttachRequestedAt.IsZero() {
				// Record when the attach starts, durably, so its deadline
				// survives restarts and settle-wait failures.
				state.AttachRequestedAt = controller.currentTime().UTC()
				revision, err := controller.persist(ctx, epoch, versioned.Revision, state)
				if err != nil {
					return false, err
				}
				versioned.Revision = revision
			}
			if err := controller.guard(ctx, epoch); err != nil {
				return false, err
			}
			attached, err := controller.fleet.AttachRetainedVolume(ctx, oci.VolumeAttachRequest{
				DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
				VolumeID: state.VolumeID, InstanceID: state.InstanceID,
				IdempotencyKey: memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-volume"),
			})
			if err != nil {
				controller.holdStalledAttachRequest(seat.MemberID, state)
				return false, fmt.Errorf("attach retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
			}
			attachment = &attached
		}
		state.AttachmentID = attachment.ID
		if attachment.State == "ATTACHED" {
			state.AttachRequestedAt = time.Time{}
			state.Stage = StageAwaitingRuntimeContract
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
		} else if attachment.State == "ATTACHING" {
			state.Stage = StageAwaitingAttach
			state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-wait")
		} else {
			controller.hold(fmt.Sprintf("member %s retained volume attachment is %s; desired state remains withheld", seat.MemberID, attachment.State))
			return false, nil
		}
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingAttach:
		instance, exists := instances[state.InstanceID]
		if !exists {
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			return false, nil
		}
		for _, attachment := range instance.Attachments {
			if attachment.ID != state.AttachmentID || attachment.VolumeID != state.VolumeID || attachment.InstanceID != state.InstanceID {
				continue
			}
			switch attachment.State {
			case "ATTACHED":
				if !controller.runtimeArtifactReady(ctx, state, seat) {
					return false, nil
				}
				if err := controller.verifyHostImage(ctx, instance); err != nil {
					return false, err
				}
				state.AttachRequestedAt = time.Time{}
				state.Stage = StageAwaitingRuntimeContract
				state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
				_, err := controller.persist(ctx, epoch, versioned.Revision, state)
				return true, err
			case "ATTACHING":
				controller.holdStuckAttachment(seat.MemberID, attachment.ID, state)
				return false, nil
			default:
				controller.hold(fmt.Sprintf("member %s retained volume attachment is %s; desired state remains withheld", seat.MemberID, attachment.State))
				return false, nil
			}
		}
		controller.hold(fmt.Sprintf("member %s retained volume attachment is not positively observed; desired state remains withheld", seat.MemberID))
		return false, nil
	case StagePreparedDesired:
		if acted, err := controller.holdTimedOutManagedCanary(ctx, epoch, intent, versioned); acted || err != nil {
			return acted, err
		}
		if !controller.preparedPinsMatch(intent, state, seat) {
			controller.hold(fmt.Sprintf("member %s prepared desired pins changed; launch is held", seat.MemberID))
			return false, nil
		}
		// The fresh observation validated the member's bound host; its image
		// must qualify before the desired effect.
		instance, fresh, err := controller.freshPreparedInputs(ctx, epoch, intent, seat, state)
		if err != nil {
			return false, err
		}
		if !fresh {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		desired, err := controller.memberDesired(epoch, intent, state, seat)
		if err != nil {
			return false, err
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		receipt, err := controller.desired.ApplyDesired(ctx, desired)
		if err != nil {
			return false, fmt.Errorf("apply prepared TerraBase desired for %s: %w", seat.MemberID, err)
		}
		if receipt.Generation != state.DesiredGeneration || receipt.Revision == 0 {
			return false, errors.New("host desired writer returned a mismatched receipt")
		}
		state.Stage = StageAwaitingHealthy
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "await-healthy")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingRuntimeContract:
		instance, exists := instances[state.InstanceID]
		if !exists {
			controller.hold(fmt.Sprintf("member %s OCI host is not currently observed; retained volume is kept", seat.MemberID))
			return false, nil
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted || status.Registration.Generation != state.HostGeneration {
			controller.hold(fmt.Sprintf("member %s is awaiting an exact managed OCI registration and current host session", seat.MemberID))
			return false, nil
		}
		attachment, attached := observedAttachment(instance, state)
		if !attached || !validObservedAttachment(attachment) {
			controller.hold(fmt.Sprintf("member %s retained volume is not observed ATTACHED; desired state remains withheld", seat.MemberID))
			return false, nil
		}
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.verifyHostImage(ctx, instance); err != nil {
			return false, err
		}
		if _, err := host.ManagedMountPath(state.RuntimeManifest.ManagedRuntimeRoot, controller.memberBinding(intent, state)); err != nil {
			controller.hold(fmt.Sprintf("member %s has no safe managed mount path: %v", seat.MemberID, err))
			return false, nil
		}
		state.AttachmentDevice, state.AttachmentETag = attachment.Device, attachment.ETag
		state.DesiredGeneration = state.IntentGeneration
		state.Stage = StagePreparedDesired
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "prepare-desired")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingHealthy:
		if acted, err := controller.holdTimedOutManagedCanary(ctx, epoch, intent, versioned); acted || err != nil {
			return acted, err
		}
		if instance, exists := instances[state.InstanceID]; exists {
			if err := controller.validateObservedInstance(instance, state, seat); err != nil {
				return false, err
			}
			if status, admitted := controller.admittedHost(intent, state, instance, statuses); admitted &&
				status.Registration.Generation == state.HostGeneration {
				if state.ManagedRuntimeTarget.OperationID != "" {
					current, err := controller.managedUpdatePrepareIsCurrent(ctx, state)
					if err != nil {
						return false, err
					}
					if !current {
						controller.hold(fmt.Sprintf("member %s managed canary authority is no longer current", seat.MemberID))
						return false, nil
					}
				}
				if controller.hasServingReport(intent, state, instance, status) {
					if state.ManagedRuntimeTarget.OperationID != "" {
						target := state.ManagedRuntimeTarget
						target.Phase = ManagedUpdateSeatCanaryServing
						target.Outcome = string(authority.ManagedUpdateCanaryServing)
						_, err := controller.commitManagedUpdateOutcome(ctx, epoch, state,
							authority.ManagedUpdateCanaryServing, target.Outcome,
							func(verifyCtx context.Context, update ManagedUpdateIntent,
								prepared authority.ManagedUpdateRecord,
							) error {
								return controller.verifyManagedCanaryServingAtAuthorityCommit(verifyCtx, epoch, update, prepared, versioned)
							})
						if err != nil {
							return false, err
						}
						state.ManagedRuntimeTarget = target
					}
					state.Stage = StageServing
					state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "serving")
					_, err := controller.persist(ctx, epoch, versioned.Revision, state)
					return true, err
				}
				if state.ManagedRuntimeTarget.OperationID != "" && hasCurrentFailedCanaryReport(status, state,
					controller.config.Environment, controller.config.MemberRole) {
					outcome := "candidate-reported-failure"
					target := state.ManagedRuntimeTarget
					target.Phase, target.Outcome = ManagedUpdateSeatHeld, outcome
					_, err := controller.commitManagedUpdateOutcome(ctx, epoch, state,
						authority.ManagedUpdateHeld, outcome,
						func(verifyCtx context.Context, update ManagedUpdateIntent,
							prepared authority.ManagedUpdateRecord,
						) error {
							return controller.verifyManagedCanaryFailureAtAuthorityCommit(verifyCtx, epoch, update, versioned,
								controller.config.Environment, controller.config.MemberRole)
						})
					if err != nil {
						return false, err
					}
					state.ManagedRuntimeTarget = target
					state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
						state.ManagedRuntimeTarget.OperationID, state.MemberID, "held")
					_, err = controller.persist(ctx, epoch, versioned.Revision, state)
					return true, err
				}
			}
		}
		controller.hold(fmt.Sprintf("member %s awaits a current mounted process and independent TerraBase serving proof", seat.MemberID))
		return false, nil
	case StageServing:
		if instance, exists := instances[state.InstanceID]; exists {
			if err := controller.validateObservedInstance(instance, state, seat); err != nil {
				return false, err
			}
			if status, admitted := controller.admittedHost(intent, state, instance, statuses); admitted &&
				status.Registration.Generation == state.HostGeneration &&
				controller.hasServingReport(intent, state, instance, status) {
				return false, nil
			}
		}
		if state.ManagedRuntimeTarget.OperationID != "" {
			controller.hold(fmt.Sprintf("managed canary member %s lost its current candidate serving proof; it remains held without peer promotion", seat.MemberID))
			return false, nil
		}
		state.Stage = StageAwaitingRuntimeContract
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		controller.hold(fmt.Sprintf("member %s lost current host, attachment, mounted process, or TerraBase serving proof; it is held without replacement", seat.MemberID))
		return true, err
	case StageRemoveCandidate, StageCordoned, StageDraining, StageDrained, StageStorageHandled, StageTerminated:
		controller.hold(fmt.Sprintf("member %s is in retirement stage %s; retirement actions require the integrated evidence-driven scale-in path", seat.MemberID, state.Stage))
		return false, nil
	case StageRemoved:
		return false, nil
	default:
		return false, fmt.Errorf("%w: unknown member stage %q", ErrStoreCorrupt, state.Stage)
	}
}

// verifyHostImage proves that the image a member's host boots qualifies now.
func (controller *Controller) verifyHostImage(ctx context.Context, instance oci.Instance) error {
	if err := controller.fleet.VerifyHostImage(ctx, instance.ImageID); err != nil {
		return fmt.Errorf("current managed OCI host image qualification: %w", err)
	}
	return nil
}

func (controller *Controller) localSeats(intent Intent) ([]Seat, error) {
	if !slices.Contains(intent.ActiveRegions, controller.config.Region) {
		return nil, nil
	}
	return RegionSeats(controller.config.Region, controller.config.FaultDomains, SeatsPerRegion)
}

func (controller *Controller) initialState(intent Intent, seat Seat, row CanonicalRosterRow, rosterDigest string, profile ManagedHostProfile, profileDigest string, manifest RuntimeManifest, manifestDigest string, attempt uint64) MemberState {
	return MemberState{
		SchemaVersion: managedUpdateMemberStateSchemaVersion, DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
		MemberID: seat.MemberID, Region: seat.Region, FailureDomain: seat.FailureDomain, Kind: seat.Kind,
		Stage: StagePreparedHost, CreateKey: hostCreateKey(intent, seat, attempt), HostAttempt: attempt,
		CanonicalRosterRow: row, CanonicalRosterDigest: rosterDigest, AuthorityReference: intent.CanonicalRoster.Authority,
		RuntimeManifest: manifest, RuntimeManifestDigest: manifestDigest,
		IntentPayloadDigest: intent.PayloadDigest(), ManagedHostProfile: profile, ManagedHostProfileDigest: profileDigest,
		IntentGeneration: intent.Generation, OperationID: memberOperationID(intent, seat.MemberID, attempt, "prepare"),
		UpdatedAt: time.Now().UTC(),
	}
}

func pinnedEnsureRequest(state MemberState) oci.EnsureRequest {
	privateIP, _, _ := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	// The fleet rejects an empty name, so an unnamed seat fails closed there.
	name, _ := seatMemberName(state.Region, state.MemberID)
	return oci.EnsureRequest{
		Name: name, CreateKey: state.CreateKey, PrivateIP: privateIP, FaultDomain: state.FailureDomain,
		Shape: state.ManagedHostProfile.Compute.Shape, WholeOCPUs: state.ManagedHostProfile.Compute.WholeOCPUs,
		MemoryInGBs:            state.ManagedHostProfile.Compute.MemoryInGBs,
		PlacementProfileDigest: state.ManagedHostProfileDigest, PlacementGeneration: state.IntentGeneration,
		BootPins: oci.HostBootPins{
			DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
			HostAttempt: state.HostAttempt, IntentPayloadDigest: state.IntentPayloadDigest,
			CanonicalRosterDigest: state.CanonicalRosterDigest, RuntimeManifestDigest: state.RuntimeManifestDigest,
		},
	}
}

func (controller *Controller) validateEnsuredInstance(instance oci.Instance, state MemberState, seat Seat) error {
	privateIP, _, err := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	if err != nil || privateIP == "" || instance.PrivateIP != privateIP {
		return errors.New("OCI EnsureHost returned a different prepared private IP")
	}
	if instance.ID == "" || instance.Node == "" || instance.ETag == "" || instance.CreateKey != state.CreateKey ||
		state.InstanceID != "" && instance.ID != state.InstanceID || state.HostNode != "" && instance.Node != state.HostNode ||
		instance.Region != controller.config.Region || instance.FaultDomain != seat.FailureDomain ||
		!controller.instanceMatchesPinnedProfile(instance, state) {
		return errors.New("OCI EnsureHost returned an instance with mismatched durable placement identity")
	}
	return nil
}

func (controller *Controller) validateObservedInstance(instance oci.Instance, state MemberState, seat Seat) error {
	privateIP, _, err := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	if err != nil || privateIP == "" || instance.PrivateIP != privateIP {
		return errors.New("observed OCI instance differs from the prepared private IP")
	}
	if instance.ID != state.InstanceID || instance.Node != state.HostNode || instance.CreateKey != state.CreateKey ||
		instance.Region != controller.config.Region || instance.FaultDomain != seat.FailureDomain || instance.ETag == "" ||
		state.InstanceETag == "" || !controller.instanceMatchesPinnedProfile(instance, state) {
		return errors.New("observed OCI instance differs from the durable TerraBase member binding")
	}
	return nil
}

func (controller *Controller) instanceMatchesPinnedProfile(instance oci.Instance, state MemberState) bool {
	compute := state.ManagedHostProfile.Compute
	return instance.Owner == controller.config.ManagedOwner && instance.Generation == controller.config.FleetGeneration &&
		controller.imageAllowed(instance.ImageID) && controller.instanceMatchesPinnedBootDescriptor(instance, state) &&
		instance.Shape == compute.Shape && instance.WholeOCPUs == compute.WholeOCPUs &&
		instance.MemoryInGBs == compute.MemoryInGBs && instance.PlacementProfileDigest == state.ManagedHostProfileDigest &&
		instance.PlacementGeneration == state.IntentGeneration
}

// imageAllowed reports whether a member host may run imageID: the pinned
// image or one the cell's allow-list qualifies.
func (controller *Controller) imageAllowed(imageID string) bool {
	allowed := controller.config.AllowedImages
	return imageID == controller.config.ImageID || allowed != nil && slices.Contains(allowed(), imageID)
}

// instanceMatchesPinnedBootDescriptor rebuilds the descriptor the host was
// launched with, from its seat binding and its own (allowed) image.
func (controller *Controller) instanceMatchesPinnedBootDescriptor(instance oci.Instance, state MemberState) bool {
	descriptor := hostboot.Descriptor{
		SchemaVersion: hostboot.SchemaVersion, Cell: controller.config.Cell, Region: string(controller.config.Region),
		Node: instance.Node, Owner: controller.config.ManagedOwner, CreateKey: state.CreateKey,
		ImageID: instance.ImageID, FleetGeneration: controller.config.FleetGeneration,
		DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
		HostAttempt: state.HostAttempt, IntentGeneration: state.IntentGeneration,
		IntentPayloadDigest: state.IntentPayloadDigest, CanonicalRosterDigest: state.CanonicalRosterDigest,
		ManagedHostProfileDigest: state.ManagedHostProfileDigest, RuntimeManifestDigest: state.RuntimeManifestDigest,
	}
	digest, err := descriptor.Digest()
	return err == nil && digest == instance.BootDescriptorSHA256
}

func (controller *Controller) admittedHost(intent Intent, state MemberState, instance oci.Instance, statuses map[string]host.HostStatus) (host.HostStatus, bool) {
	status, exists := statuses[instance.Node]
	if !exists {
		return host.HostStatus{}, false
	}
	registration := status.Registration
	binding := registration.ManagedOCI
	if !status.Verified || !time.Now().Before(status.SessionExpiresAt) || binding == nil ||
		registration.Cell != controller.config.Cell || registration.Node != instance.Node ||
		registration.Environment != controller.config.Environment || registration.FailureDomain != instance.FaultDomain ||
		!slices.Contains(registration.Roles, controller.config.MemberRole) ||
		registration.Capacity.CPU < controller.config.Resources.CPU ||
		registration.Capacity.MemoryBytes < controller.config.Resources.MemoryBytes ||
		registration.Capacity.DiskBytes < controller.config.Resources.DiskBytes ||
		binding.Region != string(controller.config.Region) || binding.InstanceID != instance.ID ||
		binding.Owner != controller.config.ManagedOwner || binding.FleetGeneration != controller.config.FleetGeneration ||
		binding.CreateKey != instance.CreateKey {
		return host.HostStatus{}, false
	}
	row := state.CanonicalRosterRow
	roster := intent.CanonicalRoster
	pins := host.ManagedRegistrationPins{
		Placement: host.ManagedPlacementBinding{
			DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
			IntentGeneration: state.IntentGeneration, IntentPayloadDigest: state.IntentPayloadDigest,
			CanonicalRosterDigest: state.CanonicalRosterDigest, ManagedHostProfileDigest: state.ManagedHostProfileDigest,
		},
		Member: host.ManagedMemberBinding{
			Scope: host.MemberScope{
				ClusterID: roster.ClusterID, TenantID: roster.TenantID, DatabaseID: roster.DatabaseID,
				ShardID: roster.ShardID, MemberID: row.MemberID, Incarnation: row.Incarnation,
			},
			HostAttempt: state.HostAttempt,
		},
		OCI: host.ManagedOCIBinding{
			Region: string(instance.Region), InstanceID: instance.ID, Owner: instance.Owner,
			FleetGeneration: instance.Generation, CreateKey: instance.CreateKey,
		},
		FailureDomain:          row.FailureDomain,
		AllocatableMemoryBytes: state.ManagedHostProfile.AllocatableMemoryBytes,
		SystemReserveBytes:     state.ManagedHostProfile.SystemReserveBytes,
	}
	if err := host.ValidateManagedRegistrationPins(registration, pins); err != nil {
		return host.HostStatus{}, false
	}
	return status, true
}

func (controller *Controller) hasServingReport(intent Intent, state MemberState, instance oci.Instance, status host.HostStatus) bool {
	manifest := state.EffectiveRuntimeManifest()
	attachment, attached := observedAttachment(instance, state)
	if !attached || !validObservedAttachment(attachment) ||
		attachment.Device != state.AttachmentDevice || attachment.ETag != state.AttachmentETag {
		return false
	}
	var survivor memberstatus.Survivor
	for _, row := range intent.CanonicalRoster.Rows {
		if row.MemberID == manifest.ReplicationPeerMemberID && row.MemberID != state.CanonicalRosterRow.MemberID {
			survivor = memberstatus.Survivor{MemberID: row.MemberID, Incarnation: row.Incarnation}
			break
		}
	}
	if survivor.MemberID == "" {
		return false
	}
	mountPath, err := host.ManagedMountPath(manifest.ManagedRuntimeRoot, controller.memberBinding(intent, state))
	if err != nil {
		return false
	}
	now := time.Now()
	for _, report := range status.Reports {
		managed := report.Managed
		if report.Cell != controller.config.Cell || report.Node != status.Registration.Node ||
			report.Environment != controller.config.Environment || report.Role != controller.config.MemberRole ||
			report.Generation != state.DesiredGeneration || report.Digest != manifest.ArtifactDigest ||
			report.State != "running" || report.ObservedAt.IsZero() || report.ObservedAt.After(now.Add(2*time.Second)) ||
			now.Sub(report.ObservedAt) >= host.ReportMaxAge || managed == nil || managed.ServingProof == nil ||
			managed.Member != controller.memberBinding(intent, state) ||
			managed.Authority != (host.MemberAuthority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			}) || managed.OCI != (host.ManagedOCIBinding{
			Region: string(state.Region), InstanceID: state.InstanceID, Owner: controller.config.ManagedOwner,
			FleetGeneration: controller.config.FleetGeneration, CreateKey: state.CreateKey,
		}) || managed.VolumeID != state.VolumeID || managed.AttachmentID != state.AttachmentID ||
			managed.AttachmentETag != attachment.ETag || managed.FileSystemUUID != manifest.FileSystemUUID ||
			managed.FileSystemType != manifest.FileSystemType || managed.MountDevice != attachment.Device ||
			managed.MountPath != mountPath || managed.MountID == 0 || managed.ProcessPID < 2 ||
			managed.ProcessStart == "" || !strings.HasPrefix(managed.ProcessCgroup, "/") ||
			!managed.StorageRecovered || !managed.ListenerReady {
			continue
		}
		proof := managed.ServingProof
		if memberstatus.VerifyReportedServing(*proof, memberstatus.Identity{
			Process: memberstatus.Process{PID: managed.ProcessPID, StartNonce: managed.ProcessBootID},
			Scope: memberstatus.Scope{
				ClusterID: intent.CanonicalRoster.ClusterID, TenantID: intent.CanonicalRoster.TenantID,
				DatabaseID: intent.CanonicalRoster.DatabaseID, ShardID: intent.CanonicalRoster.ShardID,
				MemberID: state.CanonicalRosterRow.MemberID, Incarnation: state.CanonicalRosterRow.Incarnation,
			},
			Authority: memberstatus.Authority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			},
		}, survivor) == nil {
			return true
		}
	}
	return false
}

// beginWorkloadEffect holds the terminal-aware workload gate of intent's
// partition at epoch until the returned release runs.
func (controller *Controller) beginWorkloadEffect(ctx context.Context, epoch uint64, intent Intent) (func(), error) {
	barrier, ok := controller.fencer.(interface {
		BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
	})
	if !ok {
		return nil, errors.New("placement authority lacks terminal workload fence")
	}
	return barrier.BeginActiveWorkloadEffect(ctx, epoch, authority.WorkloadScope{
		DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
	})
}

func (controller *Controller) persist(ctx context.Context, epoch, revision uint64, state MemberState) (uint64, error) {
	release, err := controller.beginWorkloadEffect(ctx, epoch, Intent{DatabaseID: state.DatabaseID, PartitionID: state.PartitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	state.WriterEpoch = epoch
	state.UpdatedAt = time.Now().UTC()
	return controller.store.CompareAndSwap(ctx, revision, state)
}

func (controller *Controller) guard(ctx context.Context, epoch uint64) error {
	if epoch == 0 || !controller.fencer.Current().CanMutate() || controller.fencer.Current().Epoch != epoch {
		return authority.ErrFenced
	}
	return controller.fencer.Guard(ctx, epoch)
}

func (controller *Controller) freshVolumeHost(ctx context.Context, intent Intent, seat Seat, state MemberState) (oci.Instance, bool, error) {
	var instances []oci.Instance
	var err error
	if observer, ok := controller.fleet.(oci.SelectiveObserver); ok {
		instances, err = observer.ObserveSelected(ctx, func(id, node string) bool {
			return id == state.InstanceID || node == state.HostNode
		})
	} else {
		instances, err = controller.fleet.Observe(ctx)
	}
	if err != nil {
		return oci.Instance{}, false, fmt.Errorf("freshly observe retained volume host %s: %w", seat.MemberID, err)
	}
	var current oci.Instance
	found := false
	for _, instance := range instances {
		if instance.ID != state.InstanceID && instance.Node != state.HostNode {
			continue
		}
		if found {
			return oci.Instance{}, false, errors.New("fresh OCI observation contains an ambiguous retained volume host identity")
		}
		current, found = instance, true
	}
	if !found {
		controller.hold(fmt.Sprintf("member %s OCI host is not freshly observed; retained volume preparation is withheld", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	if err := controller.validateObservedInstance(current, state, seat); err != nil {
		return oci.Instance{}, false, err
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return oci.Instance{}, false, fmt.Errorf("read current retained volume host registration %s: %w", seat.MemberID, err)
	}
	var registration host.HostStatus
	found = false
	for _, status := range statuses {
		if status.Registration.Node != state.HostNode {
			continue
		}
		if found {
			return oci.Instance{}, false, errors.New("host view returned duplicate retained volume host registrations")
		}
		registration, found = status, true
	}
	status, admitted := controller.admittedHost(intent, state, current, map[string]host.HostStatus{state.HostNode: registration})
	if !found || !admitted || status.Registration.Generation != state.HostGeneration {
		controller.hold(fmt.Sprintf("member %s has no current exact host registration; retained volume preparation is withheld", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	return current, true, nil
}

// growVolume grows an owned retained volume through the fleet's journaled
// resize seam.
func (controller *Controller) growVolume(ctx context.Context, epoch uint64, intent Intent, volume oci.RetainedVolume, sizeGB int64) (oci.RetainedVolume, error) {
	resizer, ok := controller.fleet.(oci.VolumeResizer)
	if !ok {
		return volume, oci.ErrVolumeResizeUnsupported
	}
	if err := controller.guard(ctx, epoch); err != nil {
		return volume, err
	}
	grown, err := resizer.ResizeRetainedVolume(ctx, oci.VolumeResizeRequest{
		DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, VolumeID: volume.ID, SizeGB: sizeGB,
	})
	if err == nil {
		recordVolumeResize(ctx, controller.config.Cell, epoch, intent, volume, grown)
	}
	return grown, err
}

func (controller *Controller) hold(reason string) {
	if controller.config.OnHold != nil {
		controller.config.OnHold(reason)
	}
}

func hostCreateKey(intent Intent, seat Seat, attempt uint64) string {
	return digestToken("th", intent.DatabaseID, intent.PartitionID, string(seat.Region), seat.MemberID, fmt.Sprint(attempt))
}

func volumeCreateKey(intent Intent, seat Seat) string {
	return digestToken("tv", intent.DatabaseID, intent.PartitionID, string(seat.Region), seat.MemberID)
}

// TerminalTargetsForRegion derives the only workload create keys that a
// terminal plan may name. A durable member pins any later host attempt; if a
// member has not been prepared, only the first attempt can exist.
func TerminalTargetsForRegion(intent Intent, region oci.Region, faultDomains []string,
	members []VersionedMemberState,
) ([]authority.TerminalTarget, error) {
	if len(intent.ActiveRegions) != 1 || intent.ActiveRegions[0] != region {
		return nil, fmt.Errorf("%w: terminal plan is limited to one admitted managed region", ErrInvalidIntent)
	}
	seats, err := DesiredSeats(intent, map[oci.Region][]string{region: faultDomains})
	if err != nil {
		return nil, err
	}
	if len(seats) != 2 || len(members) > len(seats) {
		return nil, fmt.Errorf("%w: terminal plan requires two exact local seats", ErrInvalidIntent)
	}
	bySeat := make(map[string]MemberState, len(members))
	for _, member := range members {
		state := member.State
		if member.Revision == 0 || state.Validate() != nil || state.DatabaseID != intent.DatabaseID ||
			state.PartitionID != intent.PartitionID || state.Region != region ||
			state.IntentGeneration != intent.Generation || state.IntentPayloadDigest != intent.PayloadDigest() {
			return nil, fmt.Errorf("%w: terminal member state differs from admitted placement", ErrStoreCorrupt)
		}
		if _, exists := bySeat[state.MemberID]; exists {
			return nil, fmt.Errorf("%w: duplicate terminal member state", ErrStoreCorrupt)
		}
		bySeat[state.MemberID] = state
	}
	targets := make([]authority.TerminalTarget, 0, len(seats))
	for _, seat := range seats {
		row, err := intent.RosterRowForSeat(seat)
		if err != nil {
			return nil, err
		}
		attempt := uint64(1)
		if state, exists := bySeat[seat.MemberID]; exists {
			attempt = state.HostAttempt
			if state.Kind != seat.Kind || state.FailureDomain != seat.FailureDomain ||
				state.CreateKey != hostCreateKey(intent, seat, attempt) {
				return nil, fmt.Errorf("%w: terminal host key differs from durable member", ErrStoreCorrupt)
			}
			delete(bySeat, seat.MemberID)
		}
		targets = append(targets, authority.TerminalTarget{
			SeatID: seat.MemberID, MemberID: row.MemberID,
			HostCreateKey: hostCreateKey(intent, seat, attempt), DataCreateKey: volumeCreateKey(intent, seat),
		})
	}
	if len(bySeat) != 0 {
		return nil, fmt.Errorf("%w: terminal member lies outside admitted seats", ErrStoreCorrupt)
	}
	return targets, nil
}

func memberOperationID(intent Intent, memberID string, attempt uint64, action string) string {
	return digestToken("p", intent.DatabaseID, intent.PartitionID, memberID, fmt.Sprint(intent.Generation), fmt.Sprint(attempt), action)
}

func digestToken(prefix string, values ...string) string {
	return entityid.Derive(prefix, values...)
}

func volumeSizeGB(bytes int64) (int64, error) {
	if bytes <= 0 || bytes > 32768*bytesPerGiB {
		return 0, errors.New("TerraBase member volume request is outside OCI size limits")
	}
	gigabytes := bytes / bytesPerGiB
	if bytes%bytesPerGiB != 0 {
		gigabytes++
	}
	gigabytes = max(gigabytes, 50)
	if gigabytes > 32768 {
		return 0, errors.New("TerraBase member volume request exceeds OCI's maximum size")
	}
	return gigabytes, nil
}

func observedAttachment(instance oci.Instance, state MemberState) (oci.Attachment, bool) {
	if state.VolumeID == "" || state.AttachmentID == "" {
		return oci.Attachment{}, false
	}
	for _, attachment := range instance.Attachments {
		if attachment.ID == state.AttachmentID && attachment.VolumeID == state.VolumeID &&
			attachment.InstanceID == state.InstanceID && attachment.State == "ATTACHED" {
			return attachment, true
		}
	}
	return oci.Attachment{}, false
}

func validObservedAttachment(attachment oci.Attachment) bool {
	return attachment.ETag != "" && strings.HasPrefix(attachment.Device, "/dev/") &&
		filepath.Clean(attachment.Device) == attachment.Device && len(attachment.Device) <= 255 &&
		!strings.ContainsAny(attachment.Device, " \t\r\n\x00") &&
		!attachment.IsReadOnly && !attachment.IsShareable && attachment.IsPvEncryptionInTransitEnabled
}

func (controller *Controller) memberBinding(intent Intent, state MemberState) host.ManagedMemberBinding {
	roster, row := intent.CanonicalRoster, state.CanonicalRosterRow
	return host.ManagedMemberBinding{
		Scope: host.MemberScope{
			ClusterID: roster.ClusterID, TenantID: roster.TenantID, DatabaseID: roster.DatabaseID,
			ShardID: roster.ShardID, MemberID: row.MemberID, Incarnation: row.Incarnation,
		},
		HostAttempt: state.HostAttempt,
	}
}

func (controller *Controller) admittedRuntimeArtifact(ctx context.Context, state MemberState) (AdmittedArtifact, error) {
	manifest := state.EffectiveRuntimeManifest()
	artifact, err := controller.resolveArtifact(ctx, manifest.ArtifactDigest, controller.config.MemberRole, controller.config.Environment)
	if err != nil {
		return AdmittedArtifact{}, err
	}
	if artifact.Digest != manifest.ArtifactDigest || artifact.SourceDigest != manifest.SourceDigest {
		return AdmittedArtifact{}, errors.New("admitted runtime artifact differs from signed source and byte pins")
	}
	if target := state.ManagedRuntimeTarget; target.OperationID != "" &&
		artifact.ManifestDigest != target.ManifestDigest {
		return AdmittedArtifact{}, errors.New("admitted managed update manifest differs from its durable target")
	}
	return artifact, nil
}

func (controller *Controller) runtimeArtifactReady(ctx context.Context, state MemberState, seat Seat) bool {
	if _, err := controller.admittedRuntimeArtifact(ctx, state); err != nil {
		controller.hold(fmt.Sprintf("member %s runtime artifact is not currently admitted: %v", seat.MemberID, err))
		return false
	}
	return true
}

func (controller *Controller) memberDesired(epoch uint64, intent Intent, state MemberState, seat Seat) (host.Desired, error) {
	manifest := state.EffectiveRuntimeManifest()
	binding := controller.memberBinding(intent, state)
	mountPath, err := host.ManagedMountPath(manifest.ManagedRuntimeRoot, binding)
	if err != nil {
		return host.Desired{}, err
	}
	return host.Desired{
		Cell: controller.config.Cell, Node: state.HostNode, Environment: controller.config.Environment,
		Role: controller.config.MemberRole, Digest: manifest.ArtifactDigest,
		Generation: state.DesiredGeneration, AuthorityEpoch: epoch,
		ManagedMember: &host.ManagedMemberLaunch{
			OCI: host.ManagedOCIBinding{
				Region: string(seat.Region), InstanceID: state.InstanceID, Owner: controller.config.ManagedOwner,
				FleetGeneration: controller.config.FleetGeneration, CreateKey: state.CreateKey,
			},
			Member: binding,
			Authority: host.MemberAuthority{
				Epoch: state.AuthorityReference.Epoch, ConfigurationID: state.AuthorityReference.ConfigurationID,
				CertificateSHA256: state.AuthorityReference.CertificateSHA256,
				TLSLeafSHA256:     state.CanonicalRosterRow.TLSLeafSHA256,
			},
			SourceDigest: manifest.SourceDigest, VolumeID: state.VolumeID,
			AttachmentID: state.AttachmentID, AttachmentETag: state.AttachmentETag,
			ProcessMemoryBytes:   state.ManagedHostProfile.ProcessMemoryBytes,
			MemoryHeadroomBytes:  state.ManagedHostProfile.MemoryHeadroomBytes,
			CgroupMemoryMaxBytes: state.ManagedHostProfile.CgroupMemoryMaxBytes,
			SystemReserveBytes:   state.ManagedHostProfile.SystemReserveBytes,
			Runtime: &host.ManagedRuntimePins{
				DevicePath: state.AttachmentDevice, MountPath: mountPath,
				FileSystemUUID: manifest.FileSystemUUID, FileSystemType: manifest.FileSystemType,
				TrustedKeySHA256:                    manifest.TrustedKeySHA256,
				ServerCertificateSHA256:             manifest.ServerCertificateSHA256,
				ServerPrivateKeySHA256:              manifest.ServerPrivateKeySHA256,
				ClientCARootsSHA256:                 manifest.ClientCARootsSHA256,
				ClientManagedMaterialManifestSHA256: manifest.ClientManagedMaterialManifestSHA256,
				SQLSchemaBundleSHA256:               manifest.SQLSchemaBundleSHA256,
				LiveS3ConfigSHA256:                  manifest.LiveS3ConfigSHA256,
				LiveS3TargetSHA256:                  manifest.LiveS3TargetSHA256,
				LiveS3Credential:                    manifest.LiveS3Credential,
				BackupManifestSHA256:                manifest.BackupManifestSHA256,
				BackupS3ConfigSHA256:                manifest.BackupS3ConfigSHA256,
				BackupS3TargetSHA256:                manifest.BackupS3TargetSHA256,
				BackupS3CredentialSHA256:            manifest.BackupS3CredentialSHA256,
				BackupDataKeySHA256:                 manifest.BackupDataKeySHA256,
				BackupOwner:                         manifest.BackupOwner,
				BackupS3Credential:                  manifest.BackupS3Credential,
				BackupDataKey:                       manifest.BackupDataKey,
				ReplicationListenAddress:            manifest.ReplicationListenAddress,
				ReplicationPeerMemberID:             manifest.ReplicationPeerMemberID,
				ReplicationPeerAddress:              manifest.ReplicationPeerAddress,
				ReplicationServerCASHA256:           manifest.ReplicationServerCASHA256,
			},
		},
	}, nil
}

func (controller *Controller) preparedPinsMatch(intent Intent, state MemberState, seat Seat) bool {
	manifest, err := intent.RuntimeManifestForSeat(seat)
	if err != nil || manifest != state.RuntimeManifest || state.Validate() != nil {
		return false
	}
	digest, err := manifest.Digest()
	return err == nil && digest == state.RuntimeManifestDigest
}

// freshPreparedInputs re-reads every input of a prepared desired effect and
// returns the member's freshly observed and validated host.
func (controller *Controller) freshPreparedInputs(ctx context.Context, epoch uint64, intent Intent, seat Seat, state MemberState) (oci.Instance, bool, error) {
	if state.ManagedRuntimeTarget.OperationID != "" {
		current, err := controller.managedUpdatePrepareIsCurrent(ctx, state)
		if err != nil {
			return oci.Instance{}, false, err
		}
		if !current {
			controller.hold(fmt.Sprintf("member %s managed update authorization is no longer prepared", seat.MemberID))
			return oci.Instance{}, false, nil
		}
	}
	if _, err := controller.admittedRuntimeArtifact(ctx, state); err != nil {
		controller.hold(fmt.Sprintf("member %s runtime artifact admission changed: %v", seat.MemberID, err))
		return oci.Instance{}, false, nil
	}
	if err := controller.guard(ctx, epoch); err != nil {
		return oci.Instance{}, false, err
	}
	currentIntents, err := controller.store.ListIntents(ctx)
	if err != nil {
		return oci.Instance{}, false, err
	}
	foundIntent := false
	for _, current := range currentIntents {
		if current.DatabaseID == state.DatabaseID && current.PartitionID == state.PartitionID {
			if foundIntent || current.PayloadDigest() != intent.PayloadDigest() || current.Generation != intent.Generation {
				controller.hold(fmt.Sprintf("member %s placement intent changed before desired effect", seat.MemberID))
				return oci.Instance{}, false, nil
			}
			foundIntent = true
		}
	}
	if !foundIntent {
		controller.hold(fmt.Sprintf("member %s placement intent disappeared before desired effect", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	instances, err := controller.fleet.Observe(ctx)
	if err != nil {
		return oci.Instance{}, false, err
	}
	var currentInstance oci.Instance
	instanceCount := 0
	for _, instance := range instances {
		if instance.ID == state.InstanceID {
			currentInstance = instance
			instanceCount++
		}
	}
	if instanceCount != 1 || controller.validateObservedInstance(currentInstance, state, seat) != nil {
		controller.hold(fmt.Sprintf("member %s owned OCI host changed before desired effect", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	attachment, attached := observedAttachment(currentInstance, state)
	if !attached || !validObservedAttachment(attachment) ||
		attachment.Device != state.AttachmentDevice || attachment.ETag != state.AttachmentETag {
		controller.hold(fmt.Sprintf("member %s OCI attachment device or ETag changed before desired effect", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return oci.Instance{}, false, err
	}
	var currentStatus host.HostStatus
	statusCount := 0
	for _, status := range statuses {
		if status.Registration.Node == state.HostNode {
			currentStatus = status
			statusCount++
		}
	}
	if statusCount != 1 {
		controller.hold(fmt.Sprintf("member %s exact host registration disappeared before desired effect", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	status, admitted := controller.admittedHost(intent, state, currentInstance, map[string]host.HostStatus{state.HostNode: currentStatus})
	if !admitted || status.Registration.Generation != state.HostGeneration {
		controller.hold(fmt.Sprintf("member %s host session or registration changed before desired effect", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	currentDesired, err := controller.hosts.ListDesired(ctx, controller.config.MemberRole)
	if err != nil {
		return oci.Instance{}, false, err
	}
	want, err := controller.memberDesired(epoch, intent, state, seat)
	if err != nil {
		return oci.Instance{}, false, err
	}
	seenDesired := false
	previousDesired := false
	for _, existing := range currentDesired {
		if existing.Node != state.HostNode || existing.Role != controller.config.MemberRole {
			continue
		}
		if seenDesired {
			controller.hold(fmt.Sprintf("member %s host view returned duplicate desired targets", seat.MemberID))
			return oci.Instance{}, false, nil
		}
		seenDesired = true
		want.AuthorityEpoch, existing.AuthorityEpoch = 0, 0
		if reflect.DeepEqual(existing, want) {
			continue
		}
		target := state.ManagedRuntimeTarget
		if target.OperationID != "" {
			previous, err := controller.memberDesired(epoch, intent, state.PredecessorState(), seat)
			if err != nil {
				return oci.Instance{}, false, err
			}
			previous.AuthorityEpoch = 0
			if reflect.DeepEqual(existing, previous) {
				previousDesired = true
				continue
			}
		}
		if !previousDesired {
			controller.hold(fmt.Sprintf("member %s host desired target differs from prepared pins", seat.MemberID))
			return oci.Instance{}, false, nil
		}
	}
	if state.ManagedRuntimeTarget.OperationID != "" && !seenDesired {
		controller.hold(fmt.Sprintf("member %s managed canary lost its recorded predecessor desired", seat.MemberID))
		return oci.Instance{}, false, nil
	}
	return currentInstance, true, nil
}

	Store
	members map[string]VersionedMemberState
	fail    bool
}

func (store *journalTestStore) ListMembers(context.Context, string, string) ([]VersionedMemberState, error) {
	var out []VersionedMemberState
	for _, member := range store.members {
		out = append(out, member)
	}
	return out, nil
}

func (store *journalTestStore) CompareAndSwap(_ context.Context, expected uint64, state MemberState) (uint64, error) {
	if store.fail {
		return 0, ErrStoreConflict
	}
	store.members[state.MemberID] = VersionedMemberState{State: state, Revision: expected + 1}
	return expected + 1, nil
}

package placement

import (
	"cmp"
	"context"
	"fmt"
	"slices"
	"sync"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"

	"github.com/TerraScale/ts-orchestrator/internal/decisionlog"
	"github.com/TerraScale/ts-orchestrator/internal/oci"
)

// maxJournaledSeats bounds the remembered seat states. A regional cell has
// far fewer seats; exceeding it only forgets "from" stages.
const maxJournaledSeats = 4096

// ManagedUpdateCorrelation is the decisionlog correlation key under which
// the managed update admission records its decision, so the seat phase
// decisions chain under it. Operation conflicts are enforced per database
// partition, so two partitions may admit the same operation ID: the key is
// scoped to the partition.
func ManagedUpdateCorrelation(databaseID, partitionID, operationID string) string {
	return "managed_update:" + databaseID + "/" + partitionID + ":" + operationID
}

// ManagedUpdateAdmissionID is the decision ID of an operation's admission in
// one cell and database partition. It is derived from that scope and the
// operation, so a replayed Prepare journals the same decision (the journal
// keeps one copy per ID) and a controller that resumes the update after a
// leader change links its canary phases to the admission without the
// admitting process's in-memory correlation. The "mu" prefix keeps it from
// being read as a time-ordered ID; Journal.Chain searches the archive's
// retention for such IDs.
func ManagedUpdateAdmissionID(cell, databaseID, partitionID, operationID string) string {
	return entityid.Derive("managed-update-admission", cell, databaseID, partitionID, operationID)
}

// marksPerSeat bounds the revisions remembered per seat.
const marksPerSeat = 4

// JournaledStore wraps the reconciler's store and journals every seat stage
// and managed update phase transition the reconciler commits. It remembers
// the stage it read or wrote per seat and revision; a compare-and-swap's
// predecessor is the state at its expected revision, so a concurrent read
// (the managed-update admission lists members while the reconciler runs)
// can neither hide a transition nor stand in for an older one. Recording is
// best effort and never affects the compare-and-swap result.
func JournaledStore(store Store, cell string) Store {
	return &journaledStore{Store: store, cell: cell, seats: map[string]map[uint64]seatMark{},
		phases: map[string]seatPhases{}}
}

type journaledStore struct {
	Store
	cell  string
	mu    sync.Mutex
	seats map[string]map[uint64]seatMark
	// phases holds, per seat, the managed update phases already journaled
	// for the seat's current operation, so a forgotten predecessor never
	// journals the same phase twice. Only the current operation is kept per
	// seat, so the map is bounded by the seats, not by every operation the
	// controller ever ran.
	phases map[string]seatPhases
}

type seatPhases struct {
	operation string
	seen      map[ManagedUpdateSeatPhase]struct{}
}

type seatMark struct {
	stage     MemberStage
	operation string
	phase     ManagedUpdateSeatPhase
}

func seatKey(state MemberState) string {
	return memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID)
}

func markOf(state MemberState) seatMark {
	return seatMark{stage: state.Stage, operation: state.ManagedRuntimeTarget.OperationID,
		phase: state.ManagedRuntimeTarget.Phase}
}

// remember records the seat's state at revision.
func (store *journaledStore) remember(state MemberState, revision uint64) {
	store.mu.Lock()
	defer store.mu.Unlock()
	key := seatKey(state)
	marks := store.seats[key]
	if marks == nil {
		if len(store.seats) >= maxJournaledSeats {
			clear(store.seats)
			clear(store.phases)
		}
		marks = map[uint64]seatMark{}
		store.seats[key] = marks
	}
	marks[revision] = markOf(state)
	for len(marks) > marksPerSeat {
		oldest := revision
		for other := range marks {
			oldest = min(oldest, other)
		}
		delete(marks, oldest)
	}
}

// at returns the seat's state at revision, if it was read or written.
func (store *journaledStore) at(state MemberState, revision uint64) (seatMark, bool) {
	store.mu.Lock()
	defer store.mu.Unlock()
	mark, known := store.seats[seatKey(state)][revision]
	return mark, known
}

// firstPhase reports whether the phase is journaled for the first time for
// this operation and seat.
func (store *journaledStore) firstPhase(state MemberState) bool {
	key := seatKey(state)
	target := state.ManagedRuntimeTarget
	store.mu.Lock()
	defer store.mu.Unlock()
	entry := store.phases[key]
	if entry.operation != target.OperationID || entry.seen == nil {
		if _, known := store.phases[key]; !known && len(store.phases) >= maxJournaledSeats {
			clear(store.phases)
		}
		entry = seatPhases{operation: target.OperationID, seen: map[ManagedUpdateSeatPhase]struct{}{}}
	}
	if _, seen := entry.seen[target.Phase]; seen {
		return false
	}
	entry.seen[target.Phase] = struct{}{}
	store.phases[key] = entry
	return true
}

func (store *journaledStore) ReadMember(ctx context.Context, databaseID, partitionID, memberID string) (VersionedMemberState, error) {
	member, err := store.Store.ReadMember(ctx, databaseID, partitionID, memberID)
	if err == nil {
		store.remember(member.State, member.Revision)
	}
	return member, err
}

func (store *journaledStore) ListMembers(ctx context.Context, databaseID, partitionID string) ([]VersionedMemberState, error) {
	members, err := store.Store.ListMembers(ctx, databaseID, partitionID)
	if err == nil {
		for _, member := range members {
			store.remember(member.State, member.Revision)
		}
	}
	return members, err
}

func (store *journaledStore) CompareAndSwap(ctx context.Context, expected uint64, state MemberState) (uint64, error) {
	revision, err := store.Store.CompareAndSwap(ctx, expected, state)
	if err != nil {
		return revision, err
	}
	previous, known := store.at(state, expected)
	if expected == 0 {
		known, previous = true, seatMark{}
	}
	store.remember(state, revision)
	store.journal(ctx, previous, known, state)
	return revision, nil
}

func (store *journaledStore) journal(ctx context.Context, previous seatMark, known bool, state MemberState) {
	current := markOf(state)
	// Seat IDs repeat across databases and partitions; the journal subject
	// is the fully qualified seat.
	subject := decisionlog.Subject{Kind: "seat", ID: seatKey(state),
		Name: fmt.Sprintf("%s/%s %s", state.DatabaseID, state.PartitionID, state.MemberID)}
	signals := []decisionlog.Signal{
		{Name: "intent_generation", Value: float64(state.IntentGeneration)},
		{Name: "desired_generation", Value: float64(state.DesiredGeneration)},
		{Name: "host_attempt", Value: float64(state.HostAttempt)},
	}
	attrs := map[string]string{"database_id": state.DatabaseID, "partition_id": state.PartitionID,
		"failure_domain": state.FailureDomain}
	if state.HostNode != "" {
		attrs["host_node"] = state.HostNode
	}
	if state.VolumeID != "" {
		attrs["volume_id"] = state.VolumeID
	}
	if !known || previous.stage != current.stage {
		kind, status, summary := stageDecision(state)
		var reason string
		switch {
		case known && previous.stage == "":
			reason = fmt.Sprintf("The reconciler admitted the seat at %s.", current.stage)
		case known:
			reason = fmt.Sprintf("The reconciler committed %s after %s.", current.stage, previous.stage)
		default:
			reason = fmt.Sprintf("The reconciler committed %s.", current.stage)
		}
		stageSignals := slices.Concat(signals, []decisionlog.Signal{{Name: "stage", Text: string(current.stage)}})
		decisionlog.Record(ctx, decisionlog.Decision{Region: store.cell, Actor: decisionlog.Actor{Slice: "placement"},
			Kind: kind, Subject: subject, Summary: summary, Reason: reason, Rule: "placement stage machine",
			Signals: stageSignals, Status: status, Epoch: state.WriterEpoch, Attrs: attrs,
			Outcome: string(current.stage)})
	}
	if current.operation == "" || known && previous.operation == current.operation && previous.phase == current.phase {
		return
	}
	// An unknown predecessor is not evidence of a phase change: journal a
	// phase only the first time it is seen for this operation and seat.
	if !store.firstPhase(state) {
		return
	}
	target := state.ManagedRuntimeTarget
	correlation := ManagedUpdateCorrelation(state.DatabaseID, state.PartitionID, target.OperationID)
	updateSubject := decisionlog.Subject{Kind: "operation", ID: target.OperationID,
		Name: "managed update of " + subject.Name}
	updateAttrs := map[string]string{"artifact_digest": target.ArtifactDigest,
		"previous_artifact_digest": target.PreviousArtifactDigest, "canary_seat": target.CanarySeatID,
		"database_id": state.DatabaseID, "partition_id": state.PartitionID}
	decision := decisionlog.Decision{Region: store.cell, Actor: decisionlog.Actor{Slice: "placement"},
		Subject: updateSubject, Epoch: state.WriterEpoch, Attrs: updateAttrs, Rule: "managed TerraBase canary update",
		ParentID: cmp.Or(decisionlog.Correlated(correlation),
			ManagedUpdateAdmissionID(store.cell, state.DatabaseID, state.PartitionID, target.OperationID)),
		Signals: slices.Concat(signals, []decisionlog.Signal{
			{Name: "authority_sequence", Value: float64(target.AuthoritySequence)},
			{Name: "phase", Text: string(target.Phase)}})}
	switch target.Phase {
	case ManagedUpdateSeatPrepared:
		decision.Kind, decision.Status = decisionlog.KindUpgradeStarted, decisionlog.StatusInProgress
		decision.Summary = "Managed update started on canary seat " + state.MemberID
		decision.Reason = "A signed managed update was admitted and its canary target was durably prepared."
		decision.Alternatives = []decisionlog.Alternative{{Option: "update every seat at once",
			Reason: "the canary must prove serving before any peer changes"}}
	case ManagedUpdateSeatCanaryServing:
		decision.Kind, decision.Status = decisionlog.KindCanaryPromoted, decisionlog.StatusSucceeded
		decision.Summary = "Canary seat " + state.MemberID + " is serving the new runtime"
		decision.Reason = "The canary produced current, independent TerraBase serving proof before its deadline."
		decision.Outcome = target.Outcome
	case ManagedUpdateSeatHeld:
		decision.Kind, decision.Status = decisionlog.KindHeld, decisionlog.StatusFailed
		decision.Summary = "Managed update held on canary seat " + state.MemberID
		decision.Reason = "The canary did not prove serving (" + target.Outcome + "); the update is durably held " +
			"and no peer is promoted."
		decision.Outcome = target.Outcome
		decision.Alternatives = []decisionlog.Alternative{{Option: "promote peers",
			Reason: "the canary failed its serving gate"}}
	default:
		return
	}
	decisionlog.Record(ctx, decision)
}

func stageDecision(state MemberState) (decisionlog.Kind, decisionlog.Status, string) {
	seat := state.MemberID
	switch state.Stage {
	case StageAwaitingHost:
		return decisionlog.KindHostLaunched, decisionlog.StatusInProgress, "Host launch requested for seat " + seat
	case StageServing:
		return decisionlog.KindStageChanged, decisionlog.StatusSucceeded, "Seat " + seat + " is serving"
	case StageTerminated:
		return decisionlog.KindHostReclaimed, decisionlog.StatusSucceeded, "Host of seat " + seat + " terminated"
	case StageRemoved:
		return decisionlog.KindStageChanged, decisionlog.StatusSucceeded, "Seat " + seat + " removed"
	case StageAwaitingAttach, StagePreparedAttach:
		return decisionlog.KindStageChanged, decisionlog.StatusInProgress, "Volume attachment started for seat " + seat
	default:
		return decisionlog.KindStageChanged, decisionlog.StatusInProgress,
			fmt.Sprintf("Seat %s moved to %s", seat, state.Stage)
	}
}

// recordVolumeResize journals a grow-only retained volume resize once per
// volume and target size; the fleet's resize is journaled and idempotent on
// the same pair.
func recordVolumeResize(ctx context.Context, cell string, epoch uint64, intent Intent, before, after oci.RetainedVolume) {
	if after.SizeGB <= before.SizeGB {
		return
	}
	key := fmt.Sprintf("volume_resize:%s:%d", after.ID, after.SizeGB)
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  cell,
		Actor:   decisionlog.Actor{Slice: "storage"},
		Kind:    decisionlog.KindVolumeResized,
		Subject: decisionlog.Subject{Kind: "volume", ID: after.ID, Name: intent.DatabaseID + "/" + intent.PartitionID},
		Summary: fmt.Sprintf("Grew volume %s from %d to %d GB", after.ID, before.SizeGB, after.SizeGB),
		Reason:  "The member's resource profile needs a larger retained volume than it was created with.",
		Rule:    "placement.auto_grow_volumes",
		Signals: []decisionlog.Signal{{Name: "size_gb", Value: float64(before.SizeGB), Unit: "GB", Comparison: ">=",
			Threshold: decisionlog.Threshold(float64(after.SizeGB)), Passed: decisionlog.Passed(false)}},
		Status: decisionlog.StatusSucceeded,
		Epoch:  epoch,
	})
	decisionlog.Correlate(key, id)
}

package decisionlog

import (
	"context"
	"log/slog"
	"sync/atomic"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/observability"
)

// Recorder accepts decisions. Implementations must not block on I/O and
// must not fail the caller: Record returns the decision's ID even when the
// record is dropped.
type Recorder interface {
	Record(ctx context.Context, decision Decision) string
}

type recorderHolder struct{ recorder Recorder }

var defaultRecorder atomic.Pointer[recorderHolder]

// SetDefault installs the process-wide recorder used by Record and returns a
// function that restores the previous one. A nil recorder restores the
// structured-log fallback.
func SetDefault(recorder Recorder) (restore func()) {
	var holder *recorderHolder
	if recorder != nil {
		holder = &recorderHolder{recorder: recorder}
	}
	previous := defaultRecorder.Swap(holder)
	return func() { defaultRecorder.CompareAndSwap(holder, previous) }
}

// Default returns the installed recorder, or nil when records go to the log.
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

// LogRecorder writes decisions to the default structured logger. It is the
// fallback before a Journal is installed, and the recorder of processes
// without a regional stream (one-shot CLI commands, hosts).
type LogRecorder struct {
	Logger *slog.Logger
}

// Record logs the decision and returns its ID.
func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

package decisionlog

import "sync"

// maxCorrelations bounds the process-wide correlation table.
const maxCorrelations = 4096

// correlations maps a caller-chosen key (for example "release:sha256:..." or
// "managed_update:<operation>") to the ID of the decision that started that
// chain in this process, so a later decision by another slice can name it as
// its parent without both slices sharing state.
var correlations = struct {
	sync.Mutex
	ids   map[string]string
	order []string
}{ids: map[string]string{}}

// Correlate remembers id as the decision for key. The table is bounded;
// the oldest keys are forgotten first.
func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

// Correlated returns the decision ID remembered for key, or "".
func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}

func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

// Attach sets the durable sink and archive. Decisions recorded before a sink
// is attached stay queued (up to the queue bound) and are published once it
// is.
func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and
// the log line are kept.
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) enqueue(decision Decision) {
	select {
	case journal.queue <- decision:
		queueDepth.Add(1)
	default:
		journal.dropped.Add(1)
		droppedQueueFull.Inc()
	}
}

// markDurable records that an indexed decision is stored in the stream.
func (journal *Journal) markDurable(id string) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if _, indexed := journal.ids[id]; indexed {
		journal.ids[id] = true
	}
}

func (journal *Journal) Ingest(decision Decision) bool {
	fresh, _ := journal.ingest(decision, true)
	return fresh
}

// ingest indexes decision. durable marks it as stored in the stream. It
// reports whether the decision was new and whether it is known durable.
func (journal *Journal) ingest(decision Decision, durable bool) (bool, bool) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if known, seen := journal.ids[decision.ID]; seen {
		if durable && !known {
			journal.ids[decision.ID] = true
		}
		return false, known || durable
	}
	ingestedTotal.Inc()
	capacity := len(journal.ring)
	if journal.size == capacity {
		evicted := journal.ring[journal.start]
		delete(journal.ids, evicted.ID)
		if evicted.Time.After(journal.coveredFrom) {
			journal.coveredFrom = evicted.Time
		}
		journal.ring[journal.start] = decision
		journal.start = (journal.start + 1) % capacity
	} else {
		journal.ring[(journal.start+journal.size)%capacity] = decision
		journal.size++
	}
	journal.ids[decision.ID] = durable
	for subscriber := range journal.subscribers {
		select {
		case subscriber.decisions <- decision:
		default:
		}
	}
	return true, durable
}

// MarkCoveredFrom records that decisions older than at may exist in the
// archive but not in memory, for example after a bounded warm start.
func (journal *Journal) MarkCoveredFrom(at time.Time) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if at.After(journal.coveredFrom) {
		journal.coveredFrom = at
	}
}

// snapshot returns the indexed decisions, unordered, and the time from which
// the index is complete.
func (journal *Journal) snapshot() ([]Decision, time.Time) {
	journal.mu.RLock()
	defer journal.mu.RUnlock()
	decisions := make([]Decision, 0, journal.size)
	for offset := range journal.size {
		decisions = append(decisions, journal.ring[(journal.start+offset)%len(journal.ring)])
	}
	return decisions, journal.coveredFrom
}

// Query returns matching decisions newest first. A range older than the
// in-memory window is read from the archive when one is attached, and
// reported Partial otherwise.
func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil

func (journal *Journal) Chain(ctx context.Context, id string) (Chain, error) {
	// While the tail replays, later steps of an indexed chain (a completion
	// or a rollback) may still be pending, so every answer is partial.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	chain, ok := BuildChain(decisions, id)
	needArchive := !ok || (!coveredFrom.IsZero() && !chain.Root.Time.After(coveredFrom)) ||
		(ok && chain.Root.ParentID != "")
	if !needArchive {
		chain.Partial = replaying
		return chain, nil
	}
	_, archive := journal.currentStorage()
	if archive == nil {
		if ok {
			// Part of the chain lies before memory and nothing can read it.
			chain.Partial = true
			return chain, nil
		}
		if replaying {
			return Chain{}, ErrUnavailable
		}
		return Chain{}, ErrNotFound
	}
	since, valid := IDTime(id)
	if ok {
		since = chain.Root.Time
		valid = true
	}
	retentionFloor := journal.config.Now().Add(-DefaultRetention)
	if !valid {
		// A caller-chosen ID (for example a managed update admission)
		// encodes no time: search the archive's whole retention.
		since = retentionFloor.Add(24 * time.Hour)
	}
	seen := make(map[string]struct{}, len(decisions))
	for _, decision := range decisions {
		seen[decision.ID] = struct{}{}
	}
	// A parent is recorded before its child; look back a little for roots
	// that the in-memory window no longer holds, then further back to the
	// time a missing parent's ID encodes, within retention.
	since = since.Add(-24 * time.Hour)
	partial := false
	for range 4 {
		complete, err := archive.Scan(ctx, since, maxArchiveScan, func(decision Decision) bool {
			if _, dup := seen[decision.ID]; !dup {
				seen[decision.ID] = struct{}{}
				decisions = append(decisions, decision)
			}
			return true
		})
		if err != nil || !complete {
			partial = true
			break
		}
		chain, ok = BuildChain(decisions, id)
		if !ok || chain.Root.ParentID == "" {
			break
		}
		parentTime, known := IDTime(chain.Root.ParentID)
		if !known {
			// The missing parent has a caller-chosen ID: widen to the
			// retention once.
			if !since.After(retentionFloor) {
				break
			}
			since = retentionFloor
			continue
		}
		if !parentTime.Before(since) || parentTime.Before(retentionFloor) {
			break
		}
		since = parentTime.Add(-time.Minute)
	}
	chain, ok = BuildChain(decisions, id)
	switch {
	case !ok && (partial || replaying):
		// The archive could not be read: not proof of absence.
		return Chain{}, ErrUnavailable
	case !ok:
		return Chain{}, ErrNotFound
	}
	chain.Partial = partial || replaying
	return chain, nil

func IDTime(id string) (time.Time, bool) {
	parsed, err := entityid.Parse(id)
	if err != nil || parsed.Time() == 0 {
		return time.Time{}, false
	}
	return time.UnixMilli(int64(parsed.Time())).UTC(), true
}

func BuildChain(decisions []Decision, id string) (Chain, bool) {
	byID := make(map[string]Decision, len(decisions))
	children := map[string][]string{}
	for _, decision := range decisions {
		byID[decision.ID] = decision
		if decision.ParentID != "" {
			children[decision.ParentID] = append(children[decision.ParentID], decision.ID)
		}
	}
	current, ok := byID[id]
	if !ok {
		return Chain{}, false
	}
	seen := map[string]bool{current.ID: true}
	for current.ParentID != "" {
		parent, found := byID[current.ParentID]
		if !found || seen[parent.ID] {
			break
		}
		seen[parent.ID] = true
		current = parent
	}
	chain := Chain{Root: current}
	visited := map[string]bool{}
	queue := []string{current.ID}
	// The walk is bounded by the input; only the returned list is capped,
	// after Latest is known.
	for len(queue) > 0 {
		next := queue[0]
		queue = queue[1:]
		if visited[next] {
			continue
		}
		visited[next] = true
		chain.Decisions = append(chain.Decisions, byID[next])
		queue = append(queue, children[next]...)
	}
	slices.SortStableFunc(chain.Decisions, func(left, right Decision) int {
		if order := left.Time.Compare(right.Time); order != 0 {
			return order
		}
		return cmp.Compare(left.ID, right.ID)
	})
	chain.Latest = chain.Decisions[len(chain.Decisions)-1]
	if len(chain.Decisions) > MaxQueryLimit {
		chain.Truncated = true
		kept := make([]Decision, 0, MaxQueryLimit)
		newest := chain.Decisions[len(chain.Decisions)-(MaxQueryLimit-2):]
		for _, decision := range chain.Decisions[:len(chain.Decisions)-len(newest)] {
			if decision.ID == chain.Root.ID || decision.ID == id {
				kept = append(kept, decision)
			}
		}
		chain.Decisions = append(kept, newest...)
	}
	return chain, true
}

func NewID() string { return newIDAt(time.Now()) }

func newIDAt(at time.Time) string { return entityid.NewAt(at) }

// Normalize fills defaults and enforces bounds. It never fails: a record that
// is too large loses detail rather than being dropped.
func (decision Decision) Normalize(now time.Time) Decision {
	decision.Version = Version
	if decision.Time.IsZero() {
		decision.Time = now
	}
	decision.Time = decision.Time.UTC()
	if !entityid.Valid(decision.ID) {
		decision.ID = newIDAt(decision.Time)
	}
	if decision.Status == "" {
		decision.Status = StatusSucceeded
	}
	decision.Region = strings.ToLower(clip(decision.Region, 64))
	decision.Kind = Kind(clip(string(decision.Kind), 64))
	decision.Actor.Slice = clip(decision.Actor.Slice, 64)
	decision.Actor.Member = clip(decision.Actor.Member, maxIdentityBytes)
	decision.Subject.Kind = clip(decision.Subject.Kind, 64)
	decision.Subject.ID = clip(decision.Subject.ID, maxIdentityBytes)
	decision.Subject.Name = clip(decision.Subject.Name, maxIdentityBytes)
	decision.Summary = clip(decision.Summary, maxSummaryBytes)
	decision.Reason = clip(decision.Reason, maxSummaryBytes)
	decision.Rule = clip(decision.Rule, maxTextBytes)
	decision.Outcome = clip(decision.Outcome, maxTextBytes)
	decision.ParentID = clip(decision.ParentID, 64)
	if len(decision.Signals) > maxSignals {
		decision.Signals = decision.Signals[:maxSignals]
	}
	decision.Signals = slices.Clone(decision.Signals)
	for index := range decision.Signals {
		signal := &decision.Signals[index]
		signal.Name = clip(signal.Name, 128)
		signal.Text = clip(signal.Text, maxTextBytes)
		signal.Unit = clip(signal.Unit, 32)
		signal.Comparison = clip(signal.Comparison, 8)
	}
	if len(decision.Alternatives) > maxAlternatives {
		decision.Alternatives = decision.Alternatives[:maxAlternatives]
	}
	decision.Alternatives = slices.Clone(decision.Alternatives)
	for index := range decision.Alternatives {
		decision.Alternatives[index].Option = clip(decision.Alternatives[index].Option, maxTextBytes)
		decision.Alternatives[index].Reason = clip(decision.Alternatives[index].Reason, maxTextBytes)
	}
	if len(decision.Related) > maxRelated {
		decision.Related = decision.Related[:maxRelated]
	}
	decision.Related = slices.Clone(decision.Related)
	for index := range decision.Related {
		decision.Related[index] = clip(decision.Related[index], 64)
	}
	if len(decision.Attrs) > 0 {
		attrs := make(map[string]string, min(len(decision.Attrs), maxAttrs))
		for _, key := range slices.Sorted(maps.Keys(decision.Attrs)) {
			if len(attrs) == maxAttrs {
				break
			}
			attrs[clip(key, 64)] = clip(decision.Attrs[key], maxTextBytes)
		}
		decision.Attrs = attrs
	}
	return fit(decision)
}

// fit sheds optional evidence until the encoded record is within
// MaxRecordBytes, so the durable copy is never refused for its size: the
// per-field bounds alone allow more than that once JSON escaping is
// counted. Attributes go first, then alternatives, related IDs and signals
// (newest listed last, dropped first), then the free text is shortened.
func fit(decision Decision) Decision {
	size := func() int {
		data, err := json.Marshal(decision)
		if err != nil {
			return 0
		}
		return len(data)
	}
	for size() > MaxRecordBytes {
		switch {
		case len(decision.Attrs) > 0:
			keys := slices.Sorted(maps.Keys(decision.Attrs))
			delete(decision.Attrs, keys[len(keys)-1])
		case len(decision.Alternatives) > 0:
			decision.Alternatives = decision.Alternatives[:len(decision.Alternatives)-1]
		case len(decision.Related) > 0:
			decision.Related = decision.Related[:len(decision.Related)-1]
		case len(decision.Signals) > 0:
			decision.Signals = decision.Signals[:len(decision.Signals)-1]
		case len(decision.Outcome) > 0:
			decision.Outcome = ""
		case len(decision.Reason) > maxTextBytes/4:
			decision.Reason = clip(decision.Reason, len(decision.Reason)/2)
		case len(decision.Summary) > maxTextBytes/4:
			decision.Summary = clip(decision.Summary, len(decision.Summary)/2)
		default:
			return decision
		}
	}
	return decision
}

// Root reports whether the decision starts a chain.
func (decision Decision) Root() bool { return decision.ParentID == "" }

func clip(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	cut := limit
	for cut > 0 && !utf8Start(value[cut]) {
		cut--
	}
	return value[:cut]
}

func utf8Start(b byte) bool { return b&0xC0 != 0x80 }

// Threshold returns a pointer for Signal.Threshold.
func Threshold(value float64) *float64 { return &value }

// Passed returns a pointer for Signal.Passed.
func Passed(value bool) *bool { return &value }

func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

