func rollingManagedUpdate(t *testing.T, fixture managedUpdateSeatOutcomeFixture, controller *Controller,
	placementSequence, epoch uint64, operation, canarySeat string, old, candidate AdmittedArtifact,
) ManagedUpdateIntent {
	t.Helper()
	base := validManagedUpdateIntent(t)
	states := []MemberState{fixture.store.members[fixture.canary.State.MemberID].State,
		fixture.store.members[fixture.peer.State.MemberID].State}
	slices.SortFunc(states, func(left, right MemberState) int { return strings.Compare(left.MemberID, right.MemberID) })
	update := ManagedUpdateIntent{SchemaVersion: ManagedUpdateSchemaVersion, Cell: controller.config.Cell,
		DatabaseID: fixture.intent.DatabaseID, PartitionID: fixture.intent.PartitionID,
		PlacementGeneration: fixture.intent.Generation, PlacementPayloadDigest: fixture.intent.PayloadDigest(),
		PlacementSequence: placementSequence, AuthorityEpoch: epoch, OperationID: operation,
		Role: controller.config.MemberRole, Environment: controller.config.Environment,
		OldArtifactDigest: old.Digest, CandidateArtifactDigest: candidate.Digest,
		CandidateManifestDigest: candidate.ManifestDigest, CandidateSourceDigest: candidate.SourceDigest,
		CanarySeatID: canarySeat,
		DurabilityProfile: ManagedUpdateDurabilityProfile{SchemaVersion: ManagedUpdateSchemaVersion,
			Region: states[0].Region, SQLSchemaBundleSHA256: states[0].RuntimeManifest.SQLSchemaBundleSHA256,
			LiveS3ConfigSHA256: states[0].RuntimeManifest.LiveS3ConfigSHA256,
			LiveS3TargetSHA256: states[0].RuntimeManifest.LiveS3TargetSHA256,
			LiveS3Credential:   states[0].RuntimeManifest.LiveS3Credential}}
	for _, state := range states {
		update.Seats = append(update.Seats, managedUpdateSeatFromState(state))
		update.DurabilityProfile.Volumes = append(update.DurabilityProfile.Volumes, ManagedUpdateVolumeProfile{
			SeatID: state.MemberID, VolumeID: state.VolumeID, FileSystemUUID: state.RuntimeManifest.FileSystemUUID,
			FileSystemType: state.RuntimeManifest.FileSystemType})
		if state.MemberID == canarySeat {
			update.CanaryDesiredGeneration = state.DesiredGeneration + 1
		}
	}
	profileDigest, err := update.DurabilityProfile.Digest()
	if err != nil {
		t.Fatal(err)
	}
	statement, err := decodeManagedCompatibility(base.CompatibilityEvidence)
	if err != nil {
		t.Fatal(err)
	}
	statement.Cell, statement.OperationID = update.Cell, update.OperationID
	statement.OldArtifactDigest, statement.CandidateArtifactDigest = update.OldArtifactDigest, update.CandidateArtifactDigest
	statement.CandidateManifestDigest, statement.DurabilityProfileSHA256 = update.CandidateManifestDigest, profileDigest
	update.CompatibilityEvidence, _ = signedManagedCompatibility(t, update, statement)
	if err := update.Validate(); err != nil {
		t.Fatalf("rolling update %s: %v", operation, err)
	}
	return update
}

func SignEnvelope(
	payload []byte,
	scope EnvelopeScope,
	issuedAt time.Time,
	expiresAt time.Time,
	privateKey ed25519.PrivateKey,
) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: expected an Ed25519 private key", ErrInvalidEnvelope)
	}
	normalized, err := normalizeScope(scope)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validProtocolTime(issuedAt) || !validProtocolTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: issuedAt and expiresAt must form a valid UTC interval", ErrInvalidEnvelope)
	}
	compactPayload, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: EnvelopeSchemaVersion,
		Region:        normalized.Region,
		Kind:          normalized.Kind,
		Actor:         normalized.Actor,
		Generation:    normalized.Generation,
		Epoch:         normalized.Epoch,
		OperationID:   normalized.OperationID,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		KeyID:         keyID,
		Payload:       compactPayload,
	}
	material, err := signedMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// VerifyEnvelope verifies signature, exact semantic scope, expiry, and fencing
// metadata. Replay prevention for OperationID belongs to the durable consumer.
func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func (controller *Controller) PrepareManagedUpdate(ctx context.Context,
	record authority.ManagedUpdateRecord,
) (uint64, error) {
	if controller == nil || ctx == nil || ctx.Err() != nil {
		return 0, errors.New("managed update requires a live placement controller")
	}
	if err := record.Validate(); err != nil || record.Phase != authority.ManagedUpdatePrepared {
		return 0, errors.New("managed update admission requires a valid signed Prepare record")
	}
	reader, ok := controller.fencer.(managedUpdateAuthority)
	if !ok {
		return 0, errors.New("placement authority lacks managed update and exact placement history")
	}
	entries, err := reader.ReadManagedUpdateOperation(ctx, record.DatabaseID, record.PartitionID, record.OperationID)
	if err == nil {
		for _, entry := range entries {
			if entry.SubjectKey != record.DatabaseID+"."+record.PartitionID+"."+record.OperationID+"."+string(record.Phase) {
				continue
			}
			payload, marshalErr := json.Marshal(record, json.Deterministic(true))
			if marshalErr != nil {
				return 0, marshalErr
			}
			if bytes.Equal(entry.Payload, payload) {
				return entry.Sequence, nil
			}
			return 0, authority.ErrOperationConflict
		}
	} else if !errors.Is(err, authority.ErrNotFound) {
		return 0, err
	}
	intent, err := managedUpdateIntentForRecord(record, controller.config.Cell)
	if err != nil {
		return 0, err
	}
	epoch := intent.AuthorityEpoch
	if err := controller.verifyManagedUpdateBaseline(ctx, intent, record, epoch); err != nil {
		return 0, err
	}
	// A new operation follows the partition's latest terminal outcome; the
	// authority rejects it while an earlier operation is still prepared.
	var previous uint64
	if latest, err := reader.ReadManagedUpdate(ctx, record.DatabaseID, record.PartitionID); err == nil {
		previous = latest.Sequence
	} else if !errors.Is(err, authority.ErrNotFound) {
		return 0, err
	}
	return reader.CommitManagedUpdate(ctx, epoch, record, previous, func(verifyCtx context.Context) error {
		return controller.verifyManagedUpdateBaselineAtAuthorityCommit(verifyCtx, intent, record, epoch)
	})
}

func managedUpdateIntentForRecord(record authority.ManagedUpdateRecord, cell string) (ManagedUpdateIntent, error) {
	if record.Phase != authority.ManagedUpdatePrepared {
		return ManagedUpdateIntent{}, errors.New("managed update record is not a Prepare phase")
	}
	key := record.DatabaseID + "." + record.PartitionID + "." + record.OperationID + "." + string(record.Phase)
	payload, err := json.Marshal(record, json.Deterministic(true))
	if err != nil {
		return ManagedUpdateIntent{}, err
	}
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(record.SignedRequest, &envelope, protocol.MaxPayloadBytes+4096); err != nil {
		return ManagedUpdateIntent{}, err
	}
	entry := authority.LogEntry{Kind: authority.MutationManagedUpdate, SubjectKey: key,
		OperationID: record.OperationID, Epoch: envelope.Epoch, Payload: payload}
	_, intent, _, err := decodeManagedUpdateRequest(entry, cell)
	return intent, err
}

func (controller *Controller) verifyManagedUpdateBaseline(ctx context.Context,
	update ManagedUpdateIntent, record authority.ManagedUpdateRecord, epoch uint64,
) error {
	return controller.verifyManagedUpdateBaselineChecked(ctx, update, record, epoch, true)
}

func (controller *Controller) verifyManagedUpdateBaselineAtAuthorityCommit(ctx context.Context,
	update ManagedUpdateIntent, record authority.ManagedUpdateRecord, epoch uint64,
) error {
	// CommitManagedUpdate owns the final lease and sequence fence while this
	// verifier runs, so it must not reenter Runtime.Guard.
	return controller.verifyManagedUpdateBaselineChecked(ctx, update, record, epoch, false)
}

func (controller *Controller) verifyManagedUpdateBaselineChecked(ctx context.Context,
	update ManagedUpdateIntent, record authority.ManagedUpdateRecord, epoch uint64, guardAuthority bool,
) error {
	if guardAuthority {
		if err := controller.guard(ctx, epoch); err != nil {
			return err
		}
	}
	if update.Validate() != nil || update.Cell != controller.config.Cell || update.Role != controller.config.MemberRole ||
		update.Environment != controller.config.Environment || record.Cell != update.Cell ||
		record.DatabaseID != update.DatabaseID || record.PartitionID != update.PartitionID ||
		record.OperationID != update.OperationID || record.PlacementGeneration != update.PlacementGeneration ||
		record.PlacementPayloadDigest != update.PlacementPayloadDigest || record.PlacementSequence != update.PlacementSequence ||
		record.CanarySeatID != update.CanarySeatID || record.CanaryDesiredGeneration != update.CanaryDesiredGeneration ||
		record.OldArtifactDigest != update.OldArtifactDigest || record.CandidateArtifactDigest != update.CandidateArtifactDigest ||
		record.CandidateManifestDigest != update.CandidateManifestDigest || record.CandidateSourceDigest != update.CandidateSourceDigest {
		return errors.New("managed update request and authority record differ from placement policy")
	}
	profileDigest, err := update.DurabilityProfile.Digest()
	if err != nil || record.DurabilityProfileSHA256 != profileDigest {
		return errors.New("managed update authority record has a different durability profile digest")
	}
	if _, err := controller.store.ReadTerminalIntent(ctx, update.DatabaseID, update.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	reader, ok := controller.fencer.(managedUpdateAuthority)
	if !ok {
		return errors.New("managed update verifier lacks exact authority history")
	}
	placementEntry, err := reader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	intent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Kind != authority.MutationPlacementIntent ||
		placementEntry.SubjectKey != update.DatabaseID+"."+update.PartitionID ||
		placementEntry.Sequence != update.PlacementSequence || placementEntry.OperationID != intent.OperationID() ||
		intent.Generation != update.PlacementGeneration || intent.PayloadDigest() != update.PlacementPayloadDigest ||
		intent.DatabaseID != update.DatabaseID || intent.PartitionID != update.PartitionID ||
		intent.SchemaVersion != IntentSchemaVersion || len(intent.ActiveRegions) != 1 ||
		intent.ActiveRegions[0] != controller.config.Region {
		return errors.New("managed update does not match the exact immutable placement record")
	}
	candidate, err := controller.resolveArtifact(ctx, update.CandidateArtifactDigest, update.Role, update.Environment)
	if err != nil || candidate.Digest != update.CandidateArtifactDigest ||
		candidate.ManifestDigest != update.CandidateManifestDigest || candidate.SourceDigest != update.CandidateSourceDigest {
		return errors.New("managed update candidate bytes, manifest, or source admission changed")
	}
	if err := controller.refuseKnownBad(ctx, update.CandidateArtifactDigest); err != nil {
		return err
	}
	seats, err := controller.localSeats(intent)
	if err != nil {
		return err
	}
	members, err := controller.store.ListMembers(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	if len(seats) != 2 || len(members) != len(seats) || len(update.Seats) != len(seats) {
		return errors.New("managed update requires exactly two durable local placement seats")
	}
	memberByID := make(map[string]VersionedMemberState, len(members))
	for _, member := range members {
		state := member.State
		if member.Revision == 0 || state.Validate() != nil || state.DatabaseID != update.DatabaseID ||
			state.PartitionID != update.PartitionID || state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatPrepared {
			return errors.New("managed update found invalid seat state or an unfinished update")
		}
		if _, exists := memberByID[state.MemberID]; exists {
			return errors.New("managed update found duplicate placement member state")
		}
		memberByID[state.MemberID] = member
	}
	instances, err := controller.fleet.Observe(ctx)
	if err != nil {
		return fmt.Errorf("observe current managed OCI hosts: %w", err)
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return fmt.Errorf("read current host registrations and sessions: %w", err)
	}
	statusByNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		if _, exists := statusByNode[status.Registration.Node]; exists {
			return errors.New("managed update found duplicate host registrations")
		}
		statusByNode[status.Registration.Node] = status
	}
	desiredRows, err := controller.hosts.ListDesired(ctx, controller.config.MemberRole)
	if err != nil {
		return err
	}
	desiredByNode := make(map[string]host.Desired, len(desiredRows))
	for _, desired := range desiredRows {
		if _, exists := desiredByNode[desired.Node]; exists {
			return errors.New("managed update found duplicate desired state for a host")
		}
		desiredByNode[desired.Node] = desired
	}
	seatPins := make(map[string]ManagedUpdateSeat, len(update.Seats))
	for _, seat := range update.Seats {
		seatPins[seat.SeatID] = seat
	}
	seenSeats := make(map[string]struct{}, len(seats))
	for _, seat := range seats {
		versioned, exists := memberByID[seat.MemberID]
		if !exists {
			return fmt.Errorf("managed update seat %s has no durable member state", seat.MemberID)
		}
		state := versioned.State
		provided, exists := seatPins[seat.MemberID]
		canary := seat.MemberID == update.CanarySeatID
		rollback := canary && managedUpdateRollsBackHeld(update, state)
		effective := state.EffectiveRuntimeManifest().ArtifactDigest
		if !exists || !managedUpdateSeatMatches(provided, state) ||
			state.Stage != StageServing && !rollback ||
			state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatHeld && !rollback ||
			state.SchemaVersion != managedUpdateMemberStateSchemaVersion ||
			provided.OCIOwner != controller.config.ManagedOwner ||
			provided.OCIFleetGeneration != controller.config.FleetGeneration ||
			canary && effective != update.OldArtifactDigest ||
			effective != update.OldArtifactDigest && effective != update.CandidateArtifactDigest ||
			state.DesiredGeneration != provided.DesiredGeneration {
			return fmt.Errorf("managed update seat %s no longer matches its signed serving predecessor", seat.MemberID)
		}
		if err := managedUpdateDurabilityMatches(update.DurabilityProfile, state); err != nil {
			return err
		}
		instanceCount := 0
		var instance oci.Instance
		for _, observed := range instances {
			if observed.ID != state.InstanceID && observed.Node != state.HostNode {
				continue
			}
			instance = observed
			instanceCount++
		}
		if instanceCount != 1 || controller.validateObservedInstance(instance, state, seat) != nil {
			return fmt.Errorf("managed update seat %s lacks its exact current OCI host", seat.MemberID)
		}
		attachment, attached := observedAttachment(instance, state)
		if !attached || !validObservedAttachment(attachment) || attachment.Device != state.AttachmentDevice ||
			attachment.ETag != state.AttachmentETag || attachment.ID != provided.AttachmentID {
			return fmt.Errorf("managed update seat %s lacks its exact attached retained volume", seat.MemberID)
		}
		status, admitted := controller.admittedHost(intent, state, instance, statusByNode)
		if !admitted || status.Registration.Generation != state.HostGeneration ||
			!rollback && !controller.hasServingReport(intent, state, instance, status) {
			return fmt.Errorf("managed update seat %s lacks a fresh current-session serving proof", seat.MemberID)
		}
		want, err := controller.memberDesired(epoch, intent, state, seat)
		if err != nil {
			return err
		}
		current, exists := desiredByNode[state.HostNode]
		if !exists || !sameManagedDesired(current, want) || current.Generation != state.DesiredGeneration ||
			current.Digest != effective {
			return fmt.Errorf("managed update seat %s desired state differs from its exact predecessor", seat.MemberID)
		}
		seenSeats[seat.MemberID] = struct{}{}
	}
	if len(seenSeats) != len(seats) || len(seatPins) != len(seats) || seatPins[update.CanarySeatID].DesiredGeneration+1 != update.CanaryDesiredGeneration {
		return errors.New("managed update signed seat set does not match the two continuing members")
	}
	return nil
}

// ManagedUpdateSeatFor returns the signed predecessor pins an update must
// carry for one durable seat: what the seat runs now and where.
func ManagedUpdateSeatFor(state MemberState, owner string, fleetGeneration uint64) ManagedUpdateSeat {
	return ManagedUpdateSeat{
		SeatID: state.MemberID, Region: state.Region, MemberID: state.CanonicalRosterRow.MemberID,
		Incarnation: state.CanonicalRosterRow.Incarnation, TLSLeafSHA256: state.CanonicalRosterRow.TLSLeafSHA256,
		RuntimeManifestDigest: state.RuntimeManifestDigest, HostNode: state.HostNode,
		HostGeneration: state.HostGeneration, HostAttempt: state.HostAttempt,
		OCIInstanceID: state.InstanceID, OCIOwner: owner, OCIFleetGeneration: fleetGeneration,
		CreateKey: state.CreateKey, VolumeID: state.VolumeID, AttachmentID: state.AttachmentID,
		AttachmentETag: state.AttachmentETag, AttachmentDevice: state.AttachmentDevice,
		DesiredGeneration: state.DesiredGeneration, ArtifactDigest: state.EffectiveRuntimeManifest().ArtifactDigest,
	}
}

// managedUpdateRollsBackHeld reports whether update returns a seat whose
// candidate was held back to the exact artifact and source it replaced. A
// held rollback is excluded: its predecessor is the candidate that failed
// first, and returning to it would re-deploy a known-bad release.
func managedUpdateRollsBackHeld(update ManagedUpdateIntent, state MemberState) bool {
	target := state.ManagedRuntimeTarget
	predecessor := state.PredecessorState().RuntimeManifest
	return target.Phase == ManagedUpdateSeatHeld && !target.RollbackOfHeld && update.CanarySeatID == state.MemberID &&
		update.OldArtifactDigest == target.ArtifactDigest &&
		update.CandidateArtifactDigest == predecessor.ArtifactDigest &&
		update.CandidateSourceDigest == predecessor.SourceDigest &&
		(state.Stage == StagePreparedDesired || state.Stage == StageAwaitingHealthy)
}

// refuseKnownBad enforces the cell's durable known-bad list in admission, so
// a candidate a rollout rolled back is refused here even when the caller's
// own list does not name it. A read failure refuses the update: admission
// fails closed.
func (controller *Controller) refuseKnownBad(ctx context.Context, digest string) error {
	if controller.config.KnownBad == nil {
		return nil
	}
	bad, err := controller.config.KnownBad.IsKnownBad(ctx, digest)
	if err != nil {
		return fmt.Errorf("read the cell known-bad release list: %w", err)
	}
	if bad {
		return fmt.Errorf("%w: %s", ErrKnownBadCandidate, digest)
	}
	return nil
}

func managedUpdateSeatMatches(seat ManagedUpdateSeat, state MemberState) bool {
	return seat.SeatID == state.MemberID && seat.Region == state.Region &&
		seat.MemberID == state.CanonicalRosterRow.MemberID && seat.Incarnation == state.CanonicalRosterRow.Incarnation &&
		seat.TLSLeafSHA256 == state.CanonicalRosterRow.TLSLeafSHA256 &&
		seat.RuntimeManifestDigest == state.RuntimeManifestDigest && seat.HostNode == state.HostNode &&
		seat.HostGeneration == state.HostGeneration && seat.HostAttempt == state.HostAttempt &&
		seat.OCIInstanceID == state.InstanceID && seat.CreateKey == state.CreateKey &&
		seat.VolumeID == state.VolumeID && seat.AttachmentID == state.AttachmentID &&
		seat.AttachmentETag == state.AttachmentETag && seat.AttachmentDevice == state.AttachmentDevice &&
		seat.DesiredGeneration == state.DesiredGeneration &&
		seat.ArtifactDigest == state.EffectiveRuntimeManifest().ArtifactDigest
}

func managedUpdateDurabilityMatches(profile ManagedUpdateDurabilityProfile, state MemberState) error {
	if profile.Region != state.Region || profile.SQLSchemaBundleSHA256 != state.RuntimeManifest.SQLSchemaBundleSHA256 ||
		profile.LiveS3ConfigSHA256 != state.RuntimeManifest.LiveS3ConfigSHA256 ||
		profile.LiveS3TargetSHA256 != state.RuntimeManifest.LiveS3TargetSHA256 ||
		profile.LiveS3Credential != state.RuntimeManifest.LiveS3Credential {
		return errors.New("managed update durability profile differs from immutable runtime data pins")
	}
	for _, volume := range profile.Volumes {
		if volume.SeatID == state.MemberID && volume.VolumeID == state.VolumeID &&
			volume.FileSystemUUID == state.RuntimeManifest.FileSystemUUID &&
			volume.FileSystemType == state.RuntimeManifest.FileSystemType {
			return nil
		}
	}
	return fmt.Errorf("managed update durability profile omits retained volume for seat %s", state.MemberID)
}

func (controller *Controller) managedUpdatePrepareIsCurrent(ctx context.Context, state MemberState) (bool, error) {
	target := state.ManagedRuntimeTarget
	reader, ok := controller.fencer.(authority.ManagedUpdateReader)
	if !ok {
		return false, errors.New("placement authority lacks managed update history")
	}
	entries, err := reader.ReadManagedUpdateOperation(ctx, state.DatabaseID, state.PartitionID, target.OperationID)
	if err != nil {
		if errors.Is(err, authority.ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	if len(entries) == 0 {
		return false, nil
	}
	var preparedEntry authority.LogEntry
	for _, entry := range entries {
		if managedUpdatePhaseFromSubject(entry.SubjectKey) == authority.ManagedUpdatePrepared {
			preparedEntry = entry
			break
		}
	}
	if preparedEntry.Kind != authority.MutationManagedUpdate || preparedEntry.Sequence != target.AuthoritySequence ||
		preparedEntry.OperationID != target.OperationID {
		return false, nil
	}
	record, intent, envelope, err := decodeManagedUpdateRequest(preparedEntry, controller.config.Cell)
	if err != nil {
		return false, err
	}
	if record.PlacementGeneration != target.PlacementGeneration ||
		record.PlacementPayloadDigest != target.PlacementPayloadDigest ||
		record.CanarySeatID != target.CanarySeatID ||
		record.CanaryDesiredGeneration != target.DesiredGeneration ||
		record.CandidateArtifactDigest != target.ArtifactDigest ||
		record.CandidateManifestDigest != target.ManifestDigest ||
		record.CandidateSourceDigest != target.SourceDigest ||
		record.SignedRequestSHA256 != target.RequestSHA256 ||
		intent.DatabaseID != state.DatabaseID || intent.PartitionID != state.PartitionID ||
		intent.CanarySeatID != state.MemberID || envelope.Epoch != preparedEntry.Epoch {
		return false, nil
	}
	latest, err := reader.ReadManagedUpdate(ctx, state.DatabaseID, state.PartitionID)
	if err != nil {
		return false, err
	}
	if latest.Kind != authority.MutationManagedUpdate {
		return false, nil
	}
	if latest.OperationID != preparedEntry.OperationID || latest.Sequence != preparedEntry.Sequence {
		// The operation is no longer the latest prepared request, so it stays
		// current only through its own retained canary-serving outcome. Once a
		// later operation follows, the seat must already record that outcome.
		served := false
		for _, entry := range entries {
			if managedUpdatePhaseFromSubject(entry.SubjectKey) != authority.ManagedUpdateCanaryServing {
				continue
			}
			terminal, err := decodeManagedUpdatePhaseRecord(entry, record, authority.ManagedUpdateCanaryServing)
			served = err == nil && terminal.Phase == authority.ManagedUpdateCanaryServing
		}
		if !served || target.Phase != ManagedUpdateSeatPrepared && target.Phase != ManagedUpdateSeatCanaryServing ||
			latest.OperationID != preparedEntry.OperationID && target.Phase != ManagedUpdateSeatCanaryServing {
			return false, nil
		}
	}
	placementReader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return false, errors.New("placement authority lacks exact placement history")
	}
	placementEntry, err := placementReader.ReadPlacementIntent(ctx, state.DatabaseID, state.PartitionID)
	if err != nil {
		return false, err
	}
	if placementEntry.Sequence != record.PlacementSequence {
		return false, nil
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil {
		return false, err
	}
	return currentIntent.Generation == record.PlacementGeneration &&
		currentIntent.PayloadDigest() == record.PlacementPayloadDigest &&
		currentIntent.Generation == intent.PlacementGeneration &&
		currentIntent.PayloadDigest() == intent.PlacementPayloadDigest, nil
}

func (controller *Controller) reconcileManagedUpdate(ctx context.Context, epoch uint64,
	intent Intent, seats []Seat, memberByID map[string]VersionedMemberState,
) (bool, error) {
	reader, ok := controller.fencer.(authority.ManagedUpdateReader)
	if !ok {
		return false, errors.New("placement authority lacks managed update history")
	}
	latest, err := reader.ReadManagedUpdate(ctx, intent.DatabaseID, intent.PartitionID)
	if errors.Is(err, authority.ErrNotFound) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if latest.Kind != authority.MutationManagedUpdate || latest.Sequence == 0 || latest.OperationID == "" {
		return false, errors.New("managed update authority history is malformed")
	}
	var record authority.ManagedUpdateRecord
	if err := json.Unmarshal(latest.Payload, &record, json.RejectUnknownMembers(true)); err != nil ||
		record.Validate() != nil || record.OperationID != latest.OperationID ||
		record.DatabaseID != intent.DatabaseID || record.PartitionID != intent.PartitionID ||
		managedUpdatePhaseFromSubject(latest.SubjectKey) != record.Phase {
		return false, errors.New("managed update authority phase is corrupt")
	}
	if record.Phase == authority.ManagedUpdateHeld || record.Phase == authority.ManagedUpdateCanaryServing {
		return controller.reconcileManagedUpdateTerminal(ctx, epoch, intent, latest, record, memberByID)
	}
	if record.Phase != authority.ManagedUpdatePrepared {
		return false, errors.New("managed update authority phase is unsupported")
	}
	_, update, _, err := decodeManagedUpdateRequest(latest, controller.config.Cell)
	if err != nil || update.DatabaseID != intent.DatabaseID || update.PartitionID != intent.PartitionID ||
		update.PlacementGeneration != intent.Generation || update.PlacementPayloadDigest != intent.PayloadDigest() {
		return false, errors.New("prepared managed update no longer matches the active placement")
	}
	canary, exists := memberByID[record.CanarySeatID]
	if !exists {
		controller.hold(fmt.Sprintf("managed update %s has no durable canary seat", record.OperationID))
		return false, nil
	}
	state := canary.State
	current := state.ManagedRuntimeTarget
	if current.OperationID == record.OperationID {
		if current.AuthoritySequence != latest.Sequence || current.RequestSHA256 != record.SignedRequestSHA256 ||
			current.ArtifactDigest != record.CandidateArtifactDigest {
			controller.hold(fmt.Sprintf("member %s has a different durable managed canary target", state.MemberID))
		}
		return false, nil
	}
	if current.Phase == ManagedUpdateSeatPrepared {
		controller.hold(fmt.Sprintf("member %s has an unfinished managed canary target", state.MemberID))
		return false, nil
	}
	if err := controller.verifyManagedUpdateBaseline(ctx, update, record, epoch); err != nil {
		controller.hold(fmt.Sprintf("managed update %s baseline changed before its canary write: %v", record.OperationID, err))
		return false, nil
	}
	rollsBackHeld := managedUpdateRollsBackHeld(update, state)
	if state.Stage != StageServing && !rollsBackHeld || state.DesiredGeneration == 0 ||
		state.DesiredGeneration == ^uint64(0) || record.CanaryDesiredGeneration != state.DesiredGeneration+1 {
		controller.hold(fmt.Sprintf("member %s is not at the exact signed canary predecessor", state.MemberID))
		return false, nil
	}
	previousSource := ""
	if current.OperationID != "" {
		previousSource = current.SourceDigest
	}
	state.SchemaVersion = managedUpdateMemberStateSchemaVersion
	state.ManagedRuntimeTarget = ManagedRuntimeTarget{
		OperationID: record.OperationID, AuthoritySequence: latest.Sequence,
		RequestSHA256: record.SignedRequestSHA256, PreparedAt: controller.currentTime().UTC(),
		PlacementGeneration:    record.PlacementGeneration,
		PlacementPayloadDigest: record.PlacementPayloadDigest, CanarySeatID: record.CanarySeatID,
		PreviousDesiredGeneration: state.DesiredGeneration,
		PreviousArtifactDigest:    state.EffectiveRuntimeManifest().ArtifactDigest, PreviousSourceDigest: previousSource,
		DesiredGeneration: record.CanaryDesiredGeneration, ArtifactDigest: record.CandidateArtifactDigest,
		ManifestDigest: record.CandidateManifestDigest, SourceDigest: record.CandidateSourceDigest,
		Phase: ManagedUpdateSeatPrepared, RollbackOfHeld: rollsBackHeld,
	}
	state.DesiredGeneration = record.CanaryDesiredGeneration
	state.Stage = StagePreparedDesired
	state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID, record.OperationID, state.MemberID, "prepared")
	if _, err := controller.persist(ctx, epoch, canary.Revision, state); err != nil {
		return false, err
	}
	return true, nil
}

func (controller *Controller) reconcileManagedUpdateTerminal(ctx context.Context, epoch uint64,
	active Intent, latest authority.LogEntry, terminal authority.ManagedUpdateRecord,
	memberByID map[string]VersionedMemberState,
) (bool, error) {
	reader, ok := controller.fencer.(authority.ManagedUpdateReader)
	if !ok {
		return false, errors.New("placement authority lacks exact managed update history")
	}
	history, err := reader.ReadManagedUpdateOperation(ctx, terminal.DatabaseID, terminal.PartitionID,
		terminal.OperationID)
	if err != nil {
		return false, err
	}
	if len(history) != 2 || history[1].Sequence != latest.Sequence ||
		managedUpdatePhaseFromSubject(history[0].SubjectKey) != authority.ManagedUpdatePrepared ||
		managedUpdatePhaseFromSubject(history[1].SubjectKey) != terminal.Phase {
		controller.hold(fmt.Sprintf("managed update %s terminal history cannot be reconciled safely", terminal.OperationID))
		return true, nil
	}
	prepared, update, _, err := decodeManagedUpdateRequest(history[0], controller.config.Cell)
	if err != nil {
		return false, err
	}
	verifiedTerminal, err := decodeManagedUpdatePhaseRecord(latest, prepared, terminal.Phase)
	if err != nil || verifiedTerminal.Outcome != terminal.Outcome ||
		terminal.Phase == authority.ManagedUpdateCanaryServing && terminal.Outcome != string(authority.ManagedUpdateCanaryServing) ||
		terminal.Phase == authority.ManagedUpdateHeld && terminal.Outcome != "candidate-reported-failure" &&
			terminal.Outcome != "candidate-proof-timeout" ||
		update.DatabaseID != active.DatabaseID || update.PartitionID != active.PartitionID ||
		update.PlacementGeneration != active.Generation || update.PlacementPayloadDigest != active.PayloadDigest() {
		controller.hold(fmt.Sprintf("managed update %s terminal record differs from its exact signed Prepare", terminal.OperationID))
		return true, nil
	}
	placementReader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return false, errors.New("placement authority lacks immutable placement history")
	}
	placementEntry, err := placementReader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return false, err
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Sequence != update.PlacementSequence ||
		currentIntent.Generation != update.PlacementGeneration ||
		currentIntent.PayloadDigest() != update.PlacementPayloadDigest ||
		currentIntent.DatabaseID != active.DatabaseID || currentIntent.PartitionID != active.PartitionID {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome is not for the current immutable placement", terminal.OperationID))
		return true, nil
	}
	canary, exists := memberByID[update.CanarySeatID]
	if !exists || !managedUpdateSeatTargetMatches(update, history[0].Sequence, prepared, canary.State) {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome has no exact prepared canary seat", terminal.OperationID))
		return true, nil
	}
	return controller.persistManagedUpdateSeatOutcome(ctx, epoch, currentIntent, update, history[0].Sequence,
		prepared, terminal, canary)
}

func (controller *Controller) persistManagedUpdateSeatOutcome(ctx context.Context, epoch uint64,
	active Intent, update ManagedUpdateIntent, preparedSequence uint64,
	prepared, terminal authority.ManagedUpdateRecord,
	canary VersionedMemberState,
) (bool, error) {
	if terminal.Phase != authority.ManagedUpdateHeld && terminal.Phase != authority.ManagedUpdateCanaryServing {
		return false, errors.New("managed update seat outcome is not terminal")
	}
	state := canary.State
	if !managedUpdateSeatTargetMatches(update, preparedSequence, prepared, state) {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome has no exact prepared canary seat", terminal.OperationID))
		return true, nil
	}
	wantPhase := ManagedUpdateSeatHeld
	if terminal.Phase == authority.ManagedUpdateCanaryServing {
		wantPhase = ManagedUpdateSeatCanaryServing
	}
	target := state.ManagedRuntimeTarget
	if target.Phase == wantPhase && target.Outcome == terminal.Outcome {
		if terminal.Phase == authority.ManagedUpdateHeld &&
			(state.Stage == StagePreparedDesired || state.Stage == StageAwaitingHealthy) {
			controller.hold(fmt.Sprintf("managed update %s is durably held: %s", terminal.OperationID, terminal.Outcome))
			return true, nil
		}
		if terminal.Phase == authority.ManagedUpdateCanaryServing && state.Stage == StageServing {
			return false, nil
		}
		controller.hold(fmt.Sprintf("managed update %s terminal seat stage is inconsistent", terminal.OperationID))
		return true, nil
	}
	if target.Phase != ManagedUpdateSeatPrepared || target.Outcome != "" ||
		terminal.Phase == authority.ManagedUpdateCanaryServing && state.Stage != StageAwaitingHealthy ||
		terminal.Phase == authority.ManagedUpdateHeld && state.Stage != StagePreparedDesired &&
			state.Stage != StageAwaitingHealthy {
		controller.hold(fmt.Sprintf("managed update %s terminal outcome cannot replace the current canary seat phase", terminal.OperationID))
		return true, nil
	}
	target.Phase = wantPhase
	target.Outcome = terminal.Outcome
	state.ManagedRuntimeTarget = target
	if terminal.Phase == authority.ManagedUpdateCanaryServing {
		state.Stage = StageServing
		state.OperationID = memberOperationID(active, state.MemberID, state.HostAttempt, "serving")
	} else {
		state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
			terminal.OperationID, state.MemberID, "held")
	}
	if _, err := controller.persist(ctx, epoch, canary.Revision, state); err != nil {
		return false, err
	}
	if terminal.Phase == authority.ManagedUpdateHeld {
		controller.hold(fmt.Sprintf("managed update %s is durably held: %s", terminal.OperationID, terminal.Outcome))
	}
	return true, nil
}

func managedUpdateSeatTargetMatches(update ManagedUpdateIntent, preparedSequence uint64,
	prepared authority.ManagedUpdateRecord, state MemberState,
) bool {
	target := state.ManagedRuntimeTarget
	if state.SchemaVersion != managedUpdateMemberStateSchemaVersion || target.OperationID != prepared.OperationID ||
		target.AuthoritySequence != preparedSequence || target.RequestSHA256 != prepared.SignedRequestSHA256 ||
		target.PreparedAt.IsZero() || target.PreparedAt.Location() != time.UTC ||
		target.PlacementGeneration != update.PlacementGeneration ||
		target.PlacementPayloadDigest != update.PlacementPayloadDigest ||
		target.CanarySeatID != update.CanarySeatID ||
		target.PreviousArtifactDigest != update.OldArtifactDigest ||
		target.DesiredGeneration != update.CanaryDesiredGeneration ||
		target.ArtifactDigest != update.CandidateArtifactDigest ||
		target.ManifestDigest != update.CandidateManifestDigest || target.SourceDigest != update.CandidateSourceDigest {
		return false
	}
	seatIndex := slices.IndexFunc(update.Seats, func(seat ManagedUpdateSeat) bool {
		return seat.SeatID == update.CanarySeatID
	})
	if seatIndex < 0 {
		return false
	}
	if update.Seats[seatIndex].DesiredGeneration != target.PreviousDesiredGeneration {
		return false
	}
	return managedUpdateSeatMatches(update.Seats[seatIndex], state.PredecessorState())
}

func decodeManagedUpdatePhaseRecord(entry authority.LogEntry, prepared authority.ManagedUpdateRecord,
	want authority.ManagedUpdatePhase,
) (authority.ManagedUpdateRecord, error) {
	var record authority.ManagedUpdateRecord
	if entry.Kind != authority.MutationManagedUpdate || entry.OperationID != prepared.OperationID ||
		managedUpdatePhaseFromSubject(entry.SubjectKey) != want {
		return record, errors.New("managed update terminal phase has a mismatched authority identity")
	}
	if err := json.Unmarshal(entry.Payload, &record, json.RejectUnknownMembers(true)); err != nil {
		return record, err
	}
	canonical, err := json.Marshal(record, json.Deterministic(true))
	if err != nil || !bytes.Equal(canonical, entry.Payload) || record.Validate() != nil ||
		record.Phase != want || !prepared.SameIdentity(record) {
		return record, errors.New("managed update terminal phase differs from its signed Prepare identity")
	}
	return record, nil
}

func (controller *Controller) commitManagedUpdateOutcome(ctx context.Context, epoch uint64,
	state MemberState, phase authority.ManagedUpdatePhase, outcome string,
	verify func(context.Context, ManagedUpdateIntent, authority.ManagedUpdateRecord) error,
) (uint64, error) {
	if err := controller.guard(ctx, epoch); err != nil {
		return 0, err
	}
	reader, ok := controller.fencer.(authority.ManagedUpdateStore)
	if !ok {
		return 0, errors.New("placement authority cannot commit a managed update outcome")
	}
	entries, err := reader.ReadManagedUpdateOperation(ctx, state.DatabaseID, state.PartitionID,
		state.ManagedRuntimeTarget.OperationID)
	if err != nil {
		return 0, err
	}
	var preparedEntry authority.LogEntry
	for _, entry := range entries {
		if managedUpdatePhaseFromSubject(entry.SubjectKey) == authority.ManagedUpdatePrepared {
			preparedEntry = entry
			break
		}
	}
	if preparedEntry.Sequence != state.ManagedRuntimeTarget.AuthoritySequence {
		return 0, authority.ErrInvalidTransition
	}
	prepared, update, _, err := decodeManagedUpdateRequest(preparedEntry, controller.config.Cell)
	if err != nil || prepared.OperationID != state.ManagedRuntimeTarget.OperationID ||
		prepared.SignedRequestSHA256 != state.ManagedRuntimeTarget.RequestSHA256 ||
		update.CanarySeatID != state.MemberID ||
		state.ManagedRuntimeTarget.AuthoritySequence != preparedEntry.Sequence {
		return 0, authority.ErrInvalidTransition
	}
	record := prepared
	record.Phase = phase
	record.Outcome = outcome
	return reader.CommitManagedUpdate(ctx, epoch, record, preparedEntry.Sequence,
		func(verifyCtx context.Context) error {
			if _, err := controller.store.ReadTerminalIntent(verifyCtx, state.DatabaseID, state.PartitionID); err == nil {
				return authority.ErrFenced
			} else if !errors.Is(err, authority.ErrNotFound) {
				return err
			}
			if verify == nil {
				return nil
			}
			return verify(verifyCtx, update, prepared)
		})
}

func managedUpdateCanaryTiming(target ManagedRuntimeTarget, now time.Time) (timedOut, clockValid bool) {
	if target.PreparedAt.IsZero() || target.PreparedAt.Location() != time.UTC {
		return false, false
	}
	now = now.UTC()
	if now.Before(target.PreparedAt) {
		return false, false
	}
	deadline := target.PreparedAt.Add(managedUpdateCanaryProofTimeout)
	if !deadline.After(target.PreparedAt) {
		return false, false
	}
	return !now.Before(deadline), true
}

func (controller *Controller) holdTimedOutManagedCanary(ctx context.Context, epoch uint64,
	intent Intent, versioned VersionedMemberState,
) (bool, error) {
	state := versioned.State
	target := state.ManagedRuntimeTarget
	if target.OperationID == "" {
		return false, nil
	}
	if target.Phase != ManagedUpdateSeatPrepared {
		controller.hold(fmt.Sprintf("managed update %s has an unreconciled canary phase", target.OperationID))
		return true, nil
	}
	if target.PlacementGeneration != intent.Generation || target.PlacementPayloadDigest != intent.PayloadDigest() {
		controller.hold(fmt.Sprintf("managed update %s no longer matches its immutable placement", target.OperationID))
		return true, nil
	}
	timedOut, clockValid := managedUpdateCanaryTiming(target, controller.currentTime())
	if !clockValid {
		controller.hold(fmt.Sprintf("managed update %s has a future or invalid canary preparation clock", target.OperationID))
		return true, nil
	}
	if !timedOut {
		return false, nil
	}
	const outcome = "candidate-proof-timeout"
	if _, err := controller.commitManagedUpdateOutcome(ctx, epoch, state, authority.ManagedUpdateHeld, outcome,
		func(verifyCtx context.Context, update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord) error {
			return controller.verifyManagedCanaryTimeoutAtAuthorityCommit(verifyCtx, epoch, update, prepared, versioned)
		}); err != nil {
		return false, err
	}
	target.Phase = ManagedUpdateSeatHeld
	target.Outcome = outcome
	state.ManagedRuntimeTarget = target
	state.OperationID = digestToken("u", state.DatabaseID, state.PartitionID,
		target.OperationID, state.MemberID, "held")
	if _, err := controller.persist(ctx, epoch, versioned.Revision, state); err != nil {
		return false, err
	}
	controller.hold(fmt.Sprintf("managed update %s is durably held after its canary proof deadline", target.OperationID))
	return true, nil
}

func (controller *Controller) verifyManagedCanaryServing(ctx context.Context, epoch uint64,
	update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord, expected VersionedMemberState,
) error {
	return controller.verifyManagedCanaryServingChecked(ctx, epoch, update, prepared, expected, true)
}

func (controller *Controller) verifyManagedCanaryServingAtAuthorityCommit(ctx context.Context, epoch uint64,
	update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord, expected VersionedMemberState,
) error {
	// The authority callback holds the lease and final sequence fence; Runtime.Guard
	// would reacquire its mutex while this callback is running.
	return controller.verifyManagedCanaryServingChecked(ctx, epoch, update, prepared, expected, false)
}

func (controller *Controller) verifyManagedCanaryServingChecked(ctx context.Context, epoch uint64,
	update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord, expected VersionedMemberState,
	guardAuthority bool,
) error {
	if guardAuthority {
		if err := controller.guard(ctx, epoch); err != nil {
			return err
		}
	}
	if _, err := controller.store.ReadTerminalIntent(ctx, update.DatabaseID, update.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	if timedOut, clockValid := managedUpdateCanaryTiming(expected.State.ManagedRuntimeTarget, controller.currentTime()); !clockValid || timedOut {
		return errors.New("managed canary serving proof is outside its durable deadline")
	}
	reader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return errors.New("managed canary proof verifier lacks placement history")
	}
	placementEntry, err := reader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Sequence != update.PlacementSequence ||
		currentIntent.Generation != update.PlacementGeneration ||
		currentIntent.PayloadDigest() != update.PlacementPayloadDigest {
		return errors.New("managed canary proof is not for the current immutable placement")
	}
	seats, err := controller.localSeats(currentIntent)
	if err != nil {
		return err
	}
	members, err := controller.store.ListMembers(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	if len(seats) != 2 || len(members) != 2 || len(update.Seats) != 2 {
		return errors.New("managed canary proof requires both retained members")
	}
	memberByID := make(map[string]VersionedMemberState, len(members))
	for _, member := range members {
		if _, exists := memberByID[member.State.MemberID]; exists {
			return errors.New("managed canary proof found duplicate member state")
		}
		memberByID[member.State.MemberID] = member
	}
	canary, exists := memberByID[update.CanarySeatID]
	if !exists || canary.Revision != expected.Revision || !reflect.DeepEqual(canary.State, expected.State) {
		return errors.New("managed canary state changed before the serving outcome commit")
	}
	target := canary.State.ManagedRuntimeTarget
	if canary.State.Stage != StageAwaitingHealthy || target.Phase != ManagedUpdateSeatPrepared ||
		target.OperationID != prepared.OperationID || target.AuthoritySequence == 0 ||
		target.RequestSHA256 != prepared.SignedRequestSHA256 ||
		target.PlacementGeneration != update.PlacementGeneration ||
		target.PlacementPayloadDigest != update.PlacementPayloadDigest ||
		target.CanarySeatID != update.CanarySeatID ||
		target.ArtifactDigest != update.CandidateArtifactDigest ||
		target.ManifestDigest != update.CandidateManifestDigest || target.SourceDigest != update.CandidateSourceDigest ||
		canary.State.EffectiveRuntimeManifest().ArtifactDigest != update.CandidateArtifactDigest ||
		canary.State.DesiredGeneration != update.CanaryDesiredGeneration {
		return errors.New("managed canary does not have its exact prepared candidate target")
	}
	instances, err := controller.fleet.Observe(ctx)
	if err != nil {
		return err
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return err
	}
	statusByNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		if _, exists := statusByNode[status.Registration.Node]; exists {
			return errors.New("managed canary proof found duplicate host status")
		}
		statusByNode[status.Registration.Node] = status
	}
	desiredRows, err := controller.hosts.ListDesired(ctx, controller.config.MemberRole)
	if err != nil {
		return err
	}
	desiredByNode := make(map[string]host.Desired, len(desiredRows))
	for _, desired := range desiredRows {
		if _, exists := desiredByNode[desired.Node]; exists {
			return errors.New("managed canary proof found duplicate host desired state")
		}
		desiredByNode[desired.Node] = desired
	}
	stateBySeat := make(map[string]MemberState, len(members))
	pinBySeat := make(map[string]ManagedUpdateSeat, len(update.Seats))
	for _, seat := range update.Seats {
		versioned, exists := memberByID[seat.SeatID]
		if !exists {
			return errors.New("managed canary proof lost a signed member seat")
		}
		state := versioned.State
		if seat.SeatID == update.CanarySeatID {
			if !managedUpdateSeatMatches(seat, state.PredecessorState()) ||
				state.ManagedRuntimeTarget.Phase != ManagedUpdateSeatPrepared {
				return errors.New("canary member identity differs from its exact signed predecessor")
			}
		} else if !managedUpdatePeerUnchanged(seat, state, update) {
			return errors.New("peer member changed from its exact serving predecessor during canary")
		}
		stateBySeat[seat.SeatID], pinBySeat[seat.SeatID] = state, seat
	}
	for _, seat := range seats {
		state, exists := stateBySeat[seat.MemberID]
		if !exists {
			return errors.New("managed canary proof lacks a current placement seat")
		}
		instanceCount := 0
		var instance oci.Instance
		for _, observed := range instances {
			if observed.ID != state.InstanceID && observed.Node != state.HostNode {
				continue
			}
			instance = observed
			instanceCount++
		}
		if instanceCount != 1 || controller.validateObservedInstance(instance, state, seat) != nil {
			return errors.New("managed canary proof lacks an exact current OCI host")
		}
		attachment, attached := observedAttachment(instance, state)
		if !attached || !validObservedAttachment(attachment) || attachment.Device != state.AttachmentDevice ||
			attachment.ETag != state.AttachmentETag {
			return errors.New("managed canary proof lacks its exact attached retained volume")
		}
		status, admitted := controller.admittedHost(currentIntent, state, instance, statusByNode)
		if !admitted || status.Registration.Generation != state.HostGeneration ||
			!controller.hasServingReport(currentIntent, state, instance, status) {
			return errors.New("managed canary proof is not fresh for both exact host sessions")
		}
		if seat.MemberID == update.CanarySeatID {
			artifact, err := controller.admittedRuntimeArtifact(ctx, state)
			if err != nil || artifact.Digest != update.CandidateArtifactDigest ||
				artifact.ManifestDigest != update.CandidateManifestDigest || artifact.SourceDigest != update.CandidateSourceDigest {
				return errors.New("managed canary serving report does not match admitted candidate bytes")
			}
		} else if !managedUpdatePeerUnchanged(pinBySeat[seat.MemberID], state, update) {
			return errors.New("managed canary peer no longer runs its signed artifact")
		}
		want, err := controller.memberDesired(epoch, currentIntent, state, seat)
		if err != nil {
			return err
		}
		current, exists := desiredByNode[state.HostNode]
		if !exists || !sameManagedDesired(current, want) {
			return errors.New("managed canary host desired differs from its exact durable target")
		}
	}
	currentCanary, err := controller.store.ReadMember(ctx, update.DatabaseID, update.PartitionID,
		update.CanarySeatID)
	if err != nil || currentCanary.Revision != canary.Revision ||
		!reflect.DeepEqual(currentCanary.State, canary.State) {
		return errors.New("managed canary seat changed during the final serving verification")
	}
	if timedOut, clockValid := managedUpdateCanaryTiming(currentCanary.State.ManagedRuntimeTarget, controller.currentTime()); !clockValid || timedOut {
		return errors.New("managed canary serving proof expired before the final authority commit")
	}
	return nil
}

func managedUpdatePeerUnchanged(seat ManagedUpdateSeat, state MemberState, update ManagedUpdateIntent) bool {
	effective := state.EffectiveRuntimeManifest().ArtifactDigest
	return managedUpdateSeatMatches(seat, state) && state.Stage == StageServing &&
		(state.ManagedRuntimeTarget.OperationID == "" || state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatCanaryServing) &&
		(effective == update.OldArtifactDigest || effective == update.CandidateArtifactDigest)
}

func hasCurrentFailedCanaryReport(status host.HostStatus, state MemberState, environment, role string) bool {
	now := time.Now()
	if !status.Verified || !now.Before(status.SessionExpiresAt) {
		return false
	}
	for _, report := range status.Reports {
		if strings.EqualFold(report.Cell, string(state.Region)) && report.Node == state.HostNode &&
			report.Environment == environment && report.Role == role &&
			report.Generation == state.DesiredGeneration &&
			report.Digest == state.ManagedRuntimeTarget.ArtifactDigest &&
			report.State == "failed" && report.Error != "" && !report.ObservedAt.IsZero() &&
			!report.ObservedAt.After(now.Add(2*time.Second)) && now.Sub(report.ObservedAt) < host.ReportMaxAge {
			return true
		}
	}
	return false
}

func (controller *Controller) verifyManagedCanaryTimeoutAtAuthorityCommit(ctx context.Context, epoch uint64,
	update ManagedUpdateIntent, prepared authority.ManagedUpdateRecord, expected VersionedMemberState,
) error {
	// CommitManagedUpdate holds the final authority fence throughout this check.
	if _, err := controller.store.ReadTerminalIntent(ctx, update.DatabaseID, update.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	placementReader, ok := controller.fencer.(managedUpdatePlacementReader)
	if !ok {
		return errors.New("managed canary timeout verifier lacks placement history")
	}
	placementEntry, err := placementReader.ReadPlacementIntent(ctx, update.DatabaseID, update.PartitionID)
	if err != nil {
		return err
	}
	currentIntent, err := DecodeCommittedIntent(placementEntry.Payload)
	if err != nil || placementEntry.Sequence != update.PlacementSequence ||
		currentIntent.Generation != update.PlacementGeneration ||
		currentIntent.PayloadDigest() != update.PlacementPayloadDigest {
		return errors.New("managed canary timeout is not for the current immutable placement")
	}
	current, err := controller.store.ReadMember(ctx, update.DatabaseID, update.PartitionID,
		expected.State.MemberID)
	if err != nil || current.Revision != expected.Revision || !reflect.DeepEqual(current.State, expected.State) ||
		current.State.Stage != StagePreparedDesired && current.State.Stage != StageAwaitingHealthy ||
		current.State.ManagedRuntimeTarget.Phase != ManagedUpdateSeatPrepared ||
		!managedUpdateSeatTargetMatches(update, expected.State.ManagedRuntimeTarget.AuthoritySequence,
			prepared, current.State) {
		return errors.New("managed canary seat changed before its timeout outcome commit")
	}
	timedOut, clockValid := managedUpdateCanaryTiming(current.State.ManagedRuntimeTarget, controller.currentTime())
	if !clockValid || !timedOut {
		return errors.New("managed canary timeout has not reached its durable deadline")
	}
	return nil
}

func sameManagedDesired(left, right host.Desired) bool {
	left.AuthorityEpoch, right.AuthorityEpoch = 0, 0
	return reflect.DeepEqual(left, right)
}

func decodeManagedUpdateRequest(
	entry authority.LogEntry,
	cell string,
) (authority.ManagedUpdateRecord, ManagedUpdateIntent, protocol.Envelope, error) {
	var record authority.ManagedUpdateRecord
	if err := json.Unmarshal(entry.Payload, &record, json.RejectUnknownMembers(true)); err != nil {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, err
	}
	wantSubject := strings.Join([]string{record.DatabaseID, record.PartitionID,
		record.OperationID, string(record.Phase)}, ".")
	if record.Validate() != nil || record.Cell != cell || wantSubject != entry.SubjectKey ||
		record.OperationID != entry.OperationID || record.Phase != authority.ManagedUpdatePrepared {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, errors.New("managed update Prepare record is malformed")
	}
	canonicalRecord, err := json.Marshal(record, json.Deterministic(true))
	if err != nil || !bytes.Equal(canonicalRecord, entry.Payload) {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, errors.New("managed update Prepare record is not canonical")
	}
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(record.SignedRequest, &envelope, protocol.MaxPayloadBytes+4096); err != nil {
		return record, ManagedUpdateIntent{}, protocol.Envelope{}, err
	}
	var intent ManagedUpdateIntent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, protocol.MaxPayloadBytes); err != nil {
		return record, intent, envelope, err
	}
	canonical, err := protocol.EncodeJSON(intent)
	if err != nil || !bytes.Equal(canonical, envelope.Payload) || intent.Validate() != nil ||
		envelope.Kind != ManagedUpdateEnvelopeKind || !managedUpdateEnvelopeRegionMatches(envelope, cell) ||
		envelope.OperationID != record.OperationID || envelope.Generation != intent.CanaryDesiredGeneration ||
		envelope.Epoch != intent.AuthorityEpoch || entry.Epoch != envelope.Epoch ||
		intent.Cell != record.Cell || intent.DatabaseID != record.DatabaseID ||
		intent.PartitionID != record.PartitionID || intent.OperationID != record.OperationID ||
		intent.PlacementGeneration != record.PlacementGeneration ||
		intent.PlacementPayloadDigest != record.PlacementPayloadDigest ||
		intent.PlacementSequence != record.PlacementSequence || intent.CanarySeatID != record.CanarySeatID ||
		intent.CanaryDesiredGeneration != record.CanaryDesiredGeneration ||
		intent.OldArtifactDigest != record.OldArtifactDigest ||
		intent.CandidateArtifactDigest != record.CandidateArtifactDigest ||
		intent.CandidateManifestDigest != record.CandidateManifestDigest ||
		intent.CandidateSourceDigest != record.CandidateSourceDigest {
		return record, intent, envelope, errors.New("managed update signed request differs from its immutable authority record")
	}
	return record, intent, envelope, nil
}

func managedUpdateEnvelopeRegionMatches(envelope protocol.Envelope, cell string) bool {
	canonicalCell, err := protocol.CanonicalRegion(cell)
	return err == nil && envelope.Region == canonicalCell
}

func managedUpdatePhaseFromSubject(subjectKey string) authority.ManagedUpdatePhase {
	_, phase, ok := strings.CutLast(subjectKey, ".")
	if !ok {
		return ""
	}
	return authority.ManagedUpdatePhase(phase)
}

func (intent ManagedUpdateIntent) Validate() error {
	if intent.SchemaVersion != ManagedUpdateSchemaVersion || !validToken(intent.Cell) ||
		!validDatabaseKeyID(intent.DatabaseID) || !entityid.Valid(intent.PartitionID) ||
		intent.PlacementGeneration == 0 || !validLowerSHA256Digest(intent.PlacementPayloadDigest) ||
		intent.PlacementSequence == 0 || intent.AuthorityEpoch == 0 || !entityid.Valid(intent.OperationID) ||
		intent.Role != "terrabase" || !validToken(intent.Environment) ||
		!validLowerSHA256Digest(intent.OldArtifactDigest) ||
		!validLowerSHA256Digest(intent.CandidateArtifactDigest) ||
		intent.CandidateArtifactDigest == intent.OldArtifactDigest ||
		!validLowerSHA256Digest(intent.CandidateManifestDigest) ||
		!validLowerSHA256Digest(intent.CandidateSourceDigest) ||
		!entityid.Valid(intent.CanarySeatID) || intent.CanaryDesiredGeneration == 0 ||
		len(intent.Seats) != 2 {
		return errors.New("invalid managed TerraBase update intent")
	}
	if err := intent.DurabilityProfile.Validate(); err != nil {
		return fmt.Errorf("invalid managed update durability profile: %w", err)
	}
	profileDigest, err := intent.DurabilityProfile.Digest()
	if err != nil {
		return fmt.Errorf("digest managed update durability profile: %w", err)
	}
	if !strings.EqualFold(string(intent.DurabilityProfile.Region), intent.Cell) {
		return errors.New("managed update durability profile cell differs from the signed cell")
	}
	if !slices.IsSortedFunc(intent.Seats, func(left, right ManagedUpdateSeat) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) || !slices.IsSortedFunc(intent.DurabilityProfile.Volumes, func(left, right ManagedUpdateVolumeProfile) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) {
		return errors.New("managed update seats and durability volumes must be sorted by seat ID")
	}
	canaryFound := false
	seatIDs := make([]string, len(intent.Seats))
	for index, seat := range intent.Seats {
		if err := seat.validate(intent); err != nil {
			return fmt.Errorf("invalid managed update seat %q: %w", seat.SeatID, err)
		}
		if index > 0 && (intent.Seats[index-1].SeatID == seat.SeatID || intent.Seats[index-1].MemberID == seat.MemberID) {
			return errors.New("managed update seats must identify distinct members")
		}
		if index > 0 && (intent.Seats[index-1].HostNode == seat.HostNode ||
			intent.Seats[index-1].OCIInstanceID == seat.OCIInstanceID ||
			intent.Seats[index-1].VolumeID == seat.VolumeID ||
			intent.Seats[index-1].AttachmentID == seat.AttachmentID) {
			return errors.New("managed update seats must retain distinct hosts and volumes")
		}
		seatIDs[index] = seat.SeatID
		if seat.SeatID == intent.CanarySeatID {
			canaryFound = true
			if seat.DesiredGeneration == ^uint64(0) || intent.CanaryDesiredGeneration != seat.DesiredGeneration+1 {
				return errors.New("managed update canary generation must follow its exact predecessor")
			}
		}
	}
	if !canaryFound || len(intent.DurabilityProfile.Volumes) != len(intent.Seats) {
		return errors.New("managed update canary or durability seat set is incomplete")
	}
	for index, volume := range intent.DurabilityProfile.Volumes {
		if volume.SeatID != seatIDs[index] || volume.VolumeID != intent.Seats[index].VolumeID {
			return errors.New("managed update durability profile differs from the pinned seat volumes")
		}
	}
	var evidence ManagedCompatibilityEvidence
	if err := protocol.DecodeStrict(intent.CompatibilityEvidence.Payload, &evidence, protocol.MaxPayloadBytes); err != nil {
		return fmt.Errorf("decode signed managed compatibility evidence: %w", err)
	}
	canonical, err := protocol.EncodeJSON(evidence)
	if err != nil || !bytes.Equal(canonical, intent.CompatibilityEvidence.Payload) {
		return errors.New("signed managed compatibility evidence is not canonical")
	}
	canonicalCell, err := protocol.CanonicalRegion(intent.Cell)
	if err != nil || intent.CompatibilityEvidence.Region != canonicalCell || intent.CompatibilityEvidence.Kind != ManagedCompatibilityEnvelopeKind ||
		intent.CompatibilityEvidence.OperationID != intent.OperationID ||
		intent.CompatibilityEvidence.Generation != intent.CanaryDesiredGeneration ||
		intent.CompatibilityEvidence.Epoch == 0 || intent.CompatibilityEvidence.Actor == "" ||
		intent.CompatibilityEvidence.KeyID == "" || intent.CompatibilityEvidence.Signature == "" ||
		evidence.SchemaVersion != ManagedCompatibilitySchemaVersion || evidence.Cell != intent.Cell ||
		evidence.OperationID != intent.OperationID || evidence.OldArtifactDigest != intent.OldArtifactDigest ||
		evidence.CandidateArtifactDigest != intent.CandidateArtifactDigest ||
		evidence.CandidateManifestDigest != intent.CandidateManifestDigest ||
		evidence.DurabilityProfileSHA256 != profileDigest ||
		!evidence.MixedVersionReplicationSupported || !evidence.ClientDataCompatibilitySupported ||
		!evidence.PersistentFormatReadSupported || !evidence.PersistentFormatWriteSupported {
		return errors.New("signed managed compatibility evidence does not affirm the exact update and durability profile")
	}
	for _, seat := range intent.Seats {
		if seat.SeatID == intent.CanarySeatID && seat.ArtifactDigest != intent.OldArtifactDigest ||
			seat.ArtifactDigest != intent.OldArtifactDigest && seat.ArtifactDigest != intent.CandidateArtifactDigest {
			return errors.New("managed update canary must run the prior artifact and its peer the prior or candidate artifact")
		}
	}
	return nil
}

func (seat ManagedUpdateSeat) validate(intent ManagedUpdateIntent) error {
	if !entityid.Valid(seat.SeatID) || !knownRegion(seat.Region) || !strings.EqualFold(string(seat.Region), intent.Cell) ||
		!entityid.Valid(seat.MemberID) || !lowerHex(seat.Incarnation, 32) || allZeroHex(seat.Incarnation) ||
		!validLowerSHA256Digest(seat.TLSLeafSHA256) || !validLowerSHA256Digest(seat.RuntimeManifestDigest) ||
		!validToken(seat.HostNode) || seat.HostGeneration == 0 || seat.HostAttempt == 0 ||
		!validOCID(seat.OCIInstanceID, "instance") || !validToken(seat.OCIOwner) || seat.OCIFleetGeneration == 0 ||
		!entityid.Valid(seat.CreateKey) || !validOCID(seat.VolumeID, "volume") ||
		!validOCID(seat.AttachmentID, "volumeattachment") || seat.AttachmentETag == "" ||
		strings.ContainsAny(seat.AttachmentETag, "\r\n\x00") || !validManagedDevicePath(seat.AttachmentDevice) ||
		seat.DesiredGeneration == 0 || !validLowerSHA256Digest(seat.ArtifactDigest) {
		return errors.New("incomplete managed seat predecessor identity")
	}
	return nil
}

// Validate checks the persistent-format profile before it is signed into a
// managed update. Exact correspondence to the active placement is checked by
// the regional admission handler.
func (profile ManagedUpdateDurabilityProfile) Validate() error {
	if profile.SchemaVersion != ManagedUpdateSchemaVersion || !knownRegion(profile.Region) ||
		len(profile.Volumes) != 2 ||
		(profile.SQLSchemaBundleSHA256 != "" && !validLowerSHA256Digest(profile.SQLSchemaBundleSHA256)) ||
		!validLowerSHA256Digest(profile.LiveS3ConfigSHA256) ||
		!validLowerSHA256Digest(profile.LiveS3TargetSHA256) || profile.LiveS3Credential.Validate() != nil {
		return errors.New("incomplete managed durability profile")
	}
	if !slices.IsSortedFunc(profile.Volumes, func(left, right ManagedUpdateVolumeProfile) int {
		return strings.Compare(left.SeatID, right.SeatID)
	}) {
		return errors.New("managed durability volumes must be sorted by seat ID")
	}
	for index, volume := range profile.Volumes {
		if !entityid.Valid(volume.SeatID) || (index > 0 && profile.Volumes[index-1].SeatID == volume.SeatID) ||
			!validOCID(volume.VolumeID, "volume") || !validFilesystemUUID(volume.FileSystemUUID) ||
			volume.FileSystemType != "ext4" && volume.FileSystemType != "xfs" {
			return errors.New("invalid managed durability volume profile")
		}
	}
	if profile.LiveS3Credential.Validate() != nil {
		return errors.New("managed durability profile requires an exact ObjectDurable credential version")
	}
	return nil
}

// Digest returns the lower-case SHA-256 of the canonical selected profile.
func (profile ManagedUpdateDurabilityProfile) Digest() (string, error) {
	if err := profile.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(profile)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

// Digest returns the canonical SHA-256 used as the authority operation
// fingerprint and in receipts. Compatibility evidence signatures are part of
// the request bytes and therefore part of this digest.
func (intent ManagedUpdateIntent) Digest() (string, error) {
	if err := intent.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(intent)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

func validOCID(value, kind string) bool {
	prefix := "ocid1." + kind + "."
	return len(value) > len(prefix) && len(value) <= 255 && strings.HasPrefix(value, prefix) &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

func validManagedDevicePath(value string) bool {
	return len(value) <= 255 && filepath.IsAbs(value) && filepath.Clean(value) == value &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

func placementTestBrokerConfig(t *testing.T, instance string) natscell.Config {
	t.Helper()
	now := time.Now().UTC()
	directory := t.TempDir()
	path := func(name string) string { return filepath.Join(directory, name) }
	write := func(name string, data []byte) string {
		t.Helper()
		if err := os.WriteFile(path(name), data, 0o600); err != nil {
			t.Fatal(err)
		}
		return path(name)
	}
	newKey := func(create func() (nkeys.KeyPair, error)) (nkeys.KeyPair, string) {
		t.Helper()
		key, err := create()
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(key.Wipe)
		public, err := key.PublicKey()
		if err != nil {
			t.Fatal(err)
		}
		return key, public
	}
	operatorKey, operatorID := newKey(nkeys.CreateOperator)
	systemKey, systemID := newKey(nkeys.CreateAccount)
	cellKey, cellID := newKey(nkeys.CreateAccount)
	encode := func(name string, claim interface {
		Encode(nkeys.KeyPair) (string, error)
	}, signer nkeys.KeyPair) string {
		t.Helper()
		raw, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, []byte(raw))
	}
	operator := jwt.NewOperatorClaims(operatorID)
	operator.SystemAccount = systemID
	operator.Expires = now.Add(time.Hour).Unix()
	system := jwt.NewAccountClaims(systemID)
	system.Expires = operator.Expires
	cell := jwt.NewAccountClaims(cellID)
	cell.Expires = operator.Expires
	cell.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: jwt.NoLimit, DiskStorage: jwt.NoLimit,
		Streams: jwt.NoLimit, Consumer: jwt.NoLimit}
	credentials := func(name string, account nkeys.KeyPair, controller bool) string {
		t.Helper()
		user, public := newKey(nkeys.CreateUser)
		claim := jwt.NewUserClaims(public)
		claim.Expires = operator.Expires
		claim.Sub.Allow = jwt.StringList{protocol.InboxGrant("gru", public)}
		if controller {
			claim.Pub.Allow = natscell.ControllerPublishes("gru")
			claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
			claim.Sub.Allow.Add(protocol.Broker("gru", "ticket", ">"), protocol.Broker("gru", "fence", instance))
			claim.Sub.Allow.Add(natscell.ControllerSubscriptions("gru")...)
			claim.Sub.Allow.Add(protocol.ObservabilityGrant("gru"))
			claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
		} else {
			claim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}
		}
		raw, err := claim.Encode(account)
		if err != nil {
			t.Fatal(err)
		}
		seed, err := user.Seed()
		if err != nil {
			t.Fatal(err)
		}
		defer clear(seed)
		data, err := jwt.FormatUserConfig(raw, seed)
		if err != nil {
			t.Fatal(err)
		}
		defer clear(data)
		return write(name, data)
	}
	observerKey, observerID := newKey(nkeys.CreateUser)
	observer := jwt.NewUserClaims(observerID)
	observer.Expires = operator.Expires
	observer.Pub.Deny = jwt.StringList{">"}
	for _, prefix := range []string{"$JS.API", "$JS.gru.API"} {
		observer.Sub.Allow.Add(prefix+".STREAM.MSG.GET.KV_"+stateBucketName, prefix+".DIRECT.GET.>")
	}
	observerJWT, err := observer.Encode(cellKey)
	if err != nil {
		t.Fatal(err)
	}
	observerSeed, err := observerKey.Seed()
	if err != nil {
		t.Fatal(err)
	}
	defer clear(observerSeed)
	observerCredentials, err := jwt.FormatUserConfig(observerJWT, observerSeed)
	if err != nil {
		t.Fatal(err)
	}
	defer clear(observerCredentials)
	write("observer.creds", observerCredentials)
	caPublic, caKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	defer clear(caKey)
	ca := &x509.Certificate{SerialNumber: big.NewInt(1), NotBefore: now.Add(-time.Minute), NotAfter: now.Add(time.Hour),
		IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign}
	caDER, err := x509.CreateCertificate(rand.Reader, ca, ca, caPublic, caKey)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leafKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	defer clear(leafKey)
	leaf := &x509.Certificate{SerialNumber: big.NewInt(2), NotBefore: now.Add(-time.Minute), NotAfter: now.Add(time.Hour),
		IPAddresses: []net.IP{net.IPv4(127, 0, 0, 1)}, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}
	leafDER, err := x509.CreateCertificate(rand.Reader, leaf, ca, leafPublic, caKey)
	if err != nil {
		t.Fatal(err)
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(leafKey)
	if err != nil {
		t.Fatal(err)
	}
	defer clear(keyDER)
	tls := natscell.TLSFiles{
		CAFile:   write("ca.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})),
		CertFile: write("broker-cert.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: leafDER})),
		KeyFile:  write("broker-key.pem", pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER})),
	}
	public, ticketKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	clear(ticketKey)
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	config := natscell.Config{Cell: "gru", Instance: instance, Replicas: 1, TLS: tls, CredentialsFile: credentials("controller.creds", cellKey, true),
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: port, StoreDir: path("nats"), TLS: tls, RouteTLS: tls,
			OperatorJWTFile: encode("operator.jwt", operator, operatorKey), SystemJWTFile: encode("system.jwt", system, operatorKey),
			CellJWTFile: encode("cell.jwt", cell, operatorKey), SystemCredentialsFile: credentials("system.creds", systemKey, false),
			TicketPublicKeyFile: write("ticket.pub", []byte(base64.StdEncoding.EncodeToString(public))), BrokerIDs: []string{instance}}}
	if err := natscell.ValidateProductionCredentials(config); err != nil {
		t.Fatal(err)
	}
	return config
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func serverOptions(cfg Config) (*server.Options, error) {
	return serverOptionsForStart(cfg, false)
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

package natscell

import (
	"crypto/x509"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/nats-io/jwt/v2"
)

// ValidateProductionCredentials checks the configured production broker
// credentials without opening a listener, connecting to NATS, or changing
// local state. It must run as the account that will start the broker: the
// private-file readers enforce ownership by the current process user.
func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func validateCurrentTLSFiles(files TLSFiles, role string) error {
	config, err := loadTLS(files, false)
	if err != nil {
		return err
	}
	if len(config.Certificates) != 1 || len(config.Certificates[0].Certificate) == 0 {
		return errors.New("TLS certificate chain is missing")
	}
	leaf, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
	if err != nil {
		return fmt.Errorf("parse TLS leaf certificate: %w", err)
	}
	return verifyTLSLeaf(leaf, config.Certificates[0].Certificate[1:], config.RootCAs, role)
}

// verifyTLSLeaf checks that a leaf is current and chains to roots for each
// usage its role needs: client, listener or route (both ends).
func verifyTLSLeaf(leaf *x509.Certificate, chain [][]byte, roots *x509.CertPool, role string) error {
	intermediates := x509.NewCertPool()
	for _, der := range chain {
		certificate, err := x509.ParseCertificate(der)
		if err != nil {
			return fmt.Errorf("parse TLS intermediate certificate: %w", err)
		}
		intermediates.AddCert(certificate)
	}
	var usages []x509.ExtKeyUsage
	switch role {
	case "client":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
	case "listener":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}
	case "route":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}
	default:
		return fmt.Errorf("unsupported TLS certificate role %q", role)
	}
	for _, usage := range usages {
		if _, err := leaf.Verify(x509.VerifyOptions{
			Roots: roots, Intermediates: intermediates, CurrentTime: time.Now(),
			KeyUsages: []x509.ExtKeyUsage{usage},
		}); err != nil {
			return fmt.Errorf("verify current TLS certificate chain: %w", err)
		}
	}
	return nil
}

func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

func (r *Runtime) reconcileWithRetry(ctx context.Context) error {
	var lastErr error
	for range 8 {
		err := r.reconcile(ctx)
		if !errors.Is(err, ErrConflict) {
			return err
		}
		lastErr = err
	}
	if lastErr != nil {
		return lastErr
	}
	return ErrConflict
}

func (r *Runtime) reconcile(ctx context.Context) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	info, err := r.stream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return stageFailure("stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		return stageFailure("stream_config", err)
	}
	entryCtx, entryCancel := context.WithTimeout(ctx, authorityAPITimeout)
	entry, err := r.stream.GetLastMsgForSubject(entryCtx, r.leaseSub)
	entryCancel()
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return r.acquire(ctx, info.State.LastSeq, 0, 1)
	}
	if err != nil {
		return stageFailure("lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("lease_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil || lease.Scope != r.config.Scope || lease.Epoch == 0 {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-corrupt"})
		return nil
	}
	if lease.DeploymentID != r.config.DeploymentID {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return nil
	}
	expiresAt := entry.Time.Add(time.Duration(lease.LeaseDuration))
	now := time.Now()
	current := r.Current()
	if lease.IdentityResetSHA256 != "" {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: now, Reason: "identity-reset-pending"})
		return nil
	}
	if !lease.Released && now.Before(expiresAt) {
		if lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID {
			r.publishSnapshot(Snapshot{
				Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Ready: true,
				Epoch: lease.Epoch, Revision: entry.Sequence, ExpiresAt: expiresAt,
				ObservedAt: now, Reason: "follower",
			})
			return nil
		}
		if current.Epoch != lease.Epoch || !current.Leader {
			return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
		}
		return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
	}
	if lease.CandidateID == r.config.CandidateID && lease.OwnerID == r.ownerID && current.Leader && current.Epoch == lease.Epoch {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: now, Reason: "lease-expired"})
	}
	return r.acquire(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch+1)
}

func (r *Runtime) acquire(ctx context.Context, lastSequence, leaseSequence, epoch uint64) error {
	return r.appendLease(ctx, lastSequence, leaseSequence, epoch, false)
}

func (r *Runtime) appendLease(ctx context.Context, lastSequence, leaseSequence, epoch uint64, released bool) error {
	if epoch == 0 {
		return ErrFenced
	}
	if !released && r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	lease := leaseRecord{
		Version: 1, Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID,
		Epoch: epoch, LeaseDuration: int64(r.config.LeaseDuration), TransitionID: entityid.New(), Released: released,
	}
	data, err := jsonMarshal(lease)
	if err != nil {
		return stageFailure("lease_encode", err)
	}
	msg := controlMessage(r.leaseSub, "lease", lease.TransitionID, data)
	publishCtx, publishCancel := context.WithTimeout(ctx, authorityAPITimeout)
	ack, err := r.publisher.PublishMsg(publishCtx, msg,
		jetstream.WithExpectLastSequence(lastSequence),
		jetstream.WithExpectLastSequenceForSubject(leaseSequence, r.leaseSub),
	)
	publishCancel()
	if err != nil {
		if isSequenceConflict(err) {
			return stageFailure("lease_publish", ErrConflict)
		}
		return stageFailure("lease_publish", r.resolveLeaseAppend(ctx, lease, err))
	}
	confirmCtx, confirmCancel := context.WithTimeout(ctx, authorityAPITimeout)
	stored, err := r.stream.GetLastMsgForSubject(confirmCtx, r.leaseSub)
	confirmCancel()
	if err != nil {
		return stageFailure("lease_confirm_get", r.resolveLeaseAppend(ctx, lease, err))
	}
	if stored.Sequence != ack.Sequence {
		return stageFailure("lease_confirm_sequence", ErrConflict)
	}
	confirmed, err := decodeLease(stored.Data)
	if err != nil || confirmed.Scope != r.config.Scope || confirmed.DeploymentID != r.config.DeploymentID || confirmed.CandidateID != r.config.CandidateID || confirmed.OwnerID != r.ownerID || confirmed.Epoch != epoch || confirmed.TransitionID != lease.TransitionID || confirmed.Released != released {
		return stageFailure("lease_confirm_record", ErrFenced)
	}
	if released {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Epoch: epoch, Revision: ack.Sequence, ObservedAt: time.Now(), Reason: "released"})
		return nil
	}
	now := time.Now()
	expiresAt := stored.Time.Add(time.Duration(confirmed.LeaseDuration))
	if !now.Before(expiresAt) {
		return stageFailure("lease_confirm_expiry", ErrFenced)
	}
	r.publishSnapshot(Snapshot{
		Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Leader: true, Ready: true,
		Epoch: epoch, Revision: ack.Sequence, ExpiresAt: expiresAt, ObservedAt: now, Reason: "leader",
	})
	return nil
}

func (r *Runtime) checkClock() error {
	if r != nil && r.config.ClockCheck != nil {
		return r.config.ClockCheck()
	}
	return nil
}

func (r *Runtime) Guard(ctx context.Context, expectedEpoch uint64) error {
	if r == nil {
		return ErrNotLeader
	}
	if guard, ok := ctx.Value(verificationGuardKey{}).(*verificationGuard); ok {
		return r.guardVerification(ctx, expectedEpoch, guard)
	}
	if r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	r.mu.Lock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		wasLocalLeader := current.Leader && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID
		r.mu.Unlock()
		r.logSnapshotTransition()
		if wasLocalLeader {
			r.recordFailure(stageFailure("guard_precondition", ErrNotLeader))
		}
		return ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		r.mu.Unlock()
		return ErrFenced
	}
	var lastErr error
	for range 8 {
		err := r.guardLocked(ctx, expectedEpoch)
		if !errors.Is(err, ErrConflict) {
			r.mu.Unlock()
			r.logSnapshotTransition()
			if err != nil {
				r.recordFailure(err)
			}
			return err
		}
		lastErr = err
	}
	if lastErr == nil {
		lastErr = stageFailure("guard_retry", ErrConflict)
	}
	r.mu.Unlock()
	r.logSnapshotTransition()
	r.recordFailure(lastErr)
	return lastErr
}

func (r *Runtime) guardLocked(ctx context.Context, expectedEpoch uint64) error {
	info, err := r.stream.Info(ctx)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-unavailable"})
		return stageFailure("guard_stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-incompatible"})
		return stageFailure("guard_stream_config", err)
	}
	entry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-unreadable"})
		return stageFailure("guard_lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("guard_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-corrupt"})
		return stageFailure("guard_lease_decode", ErrLeaseCorrupt)
	}
	if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released || !time.Now().Before(entry.Time.Add(time.Duration(lease.LeaseDuration))) {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return stageFailure("guard_lease_check", ErrFenced)
	}
	return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, expectedEpoch, false)
}

// Close stops renewal and, when possible, appends a release barrier. If NATS
// is unavailable the durable lease simply expires and the next candidate
// advances the epoch.
func (r *Runtime) Close() error {
	if r == nil {
		return nil
	}
	var closeErr error
	r.once.Do(func() {
		r.cancel()
		<-r.done
		current := r.Current()
		if current.CanMutate() && current.Scope == r.config.Scope && current.DeploymentID == r.config.DeploymentID && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID {
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			r.mu.Lock()
			defer r.mu.Unlock()
			info, err := r.stream.Info(ctx)
			if err == nil && verifyControlStreamConfig(info.Config, r.config.Replicas) == nil {
				entry, getErr := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
				if getErr == nil {
					lease, decodeErr := decodeLease(entry.Data)
					if decodeErr == nil && lease.Scope == r.config.Scope && lease.DeploymentID == r.config.DeploymentID && lease.CandidateID == r.config.CandidateID && lease.OwnerID == r.ownerID && lease.Epoch == current.Epoch && !lease.Released {
						closeErr = r.appendLease(ctx, info.State.LastSeq, entry.Sequence, current.Epoch, true)
					}
				}
			}
		}
	})
	r.logSnapshotTransition()
	return closeErr
}

func openControlStream(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.Stream, error) {
	config := jetstream.StreamConfig{
		Name:              ControlStreamName,
		Description:       "Fenced regional authority, operation, and host mutation log",
		Subjects:          []string{controlStreamSubject},
		Retention:         jetstream.LimitsPolicy,
		MaxConsumers:      -1,
		MaxMsgs:           -1,
		MaxBytes:          -1,
		MaxMsgsPerSubject: -1,
		Storage:           jetstream.FileStorage,
		Replicas:          replicas,
		DenyDelete:        true,
		DenyPurge:         true,
		// Lease reads must go through the stream leader; direct reads can be stale on followers.
		AllowDirect: false,
		Metadata:    map[string]string{"terrascale-contract": "authority-log-v1"},
	}
	// JetStream only applies its default API timeout when the caller has no
	// deadline. A long startup deadline must not let one lost reply consume the
	// entire attempt.
	createCtx, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	stream, err := js.CreateStream(createCtx, config)
	cancel()
	created := err == nil
	if err != nil {
		if !errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) && !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create authority stream: %w", err)
		}
		lookupCtx, lookupCancel := context.WithTimeout(ctx, authorityAPITimeout)
		stream, err = js.Stream(lookupCtx, ControlStreamName)
		lookupCancel()
		if err != nil {
			return nil, fmt.Errorf("lookup existing authority stream: %w", err)
		}
	}
	var info *jetstream.StreamInfo
	if created {
		info, err = inspectCreatedControlStream(ctx, stream, createdStreamInfoConvergenceWindow)
	} else {
		infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
		info, err = stream.Info(infoCtx)
		infoCancel()
	}
	if err != nil {
		return nil, fmt.Errorf("inspect authority stream: %w", err)
	}
	if info == nil {
		return nil, errors.New("authority stream info is missing")
	}
	if err := verifyControlStreamConfig(info.Config, replicas); err != nil {
		return nil, err
	}
	return stream, nil
}

// A new R3 stream may be visible to CreateStream before its metadata leader
// serves Info. Retry only the exact stream-not-found API response at this one
// post-create boundary, within both the caller deadline and a short local cap.
func inspectCreatedControlStream(ctx context.Context, stream jetstream.Stream,
	convergenceWindow time.Duration,
) (*jetstream.StreamInfo, error) {
	windowCtx, cancel := context.WithTimeout(ctx, convergenceWindow)
	defer cancel()
	for {
		infoCtx, infoCancel := context.WithTimeout(windowCtx, authorityAPITimeout)
		info, err := stream.Info(infoCtx)
		infoCancel()
		if err == nil {
			return info, nil
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		apiErr, ok := errors.AsType[*jetstream.APIError](err)
		if !ok || apiErr.Code != 404 || apiErr.ErrorCode != jetstream.JSErrCodeStreamNotFound {
			return nil, err
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-windowCtx.Done():
			return nil, err
		case <-time.After(createdStreamInfoRetryDelay):
		}
	}
}

func verifyControlStreamConfig(actual jetstream.StreamConfig, replicas int) error {
	if (replicas != 1 && replicas != 3 && replicas != 5) || actual.Name != ControlStreamName ||
		actual.Replicas != replicas || actual.Retention != jetstream.LimitsPolicy ||
		actual.Storage != jetstream.FileStorage || actual.MaxConsumers != -1 ||
		actual.MaxMsgs != -1 || actual.MaxBytes != -1 ||
		actual.MaxMsgsPerSubject != -1 || actual.MaxAge != 0 || actual.Discard != jetstream.DiscardOld ||
		actual.MaxMsgSize > 0 || actual.DiscardNewPerSubject || actual.AllowRollup ||
		actual.AllowDirect || actual.MirrorDirect || actual.NoAck || actual.Sealed ||
		!actual.DenyDelete || !actual.DenyPurge || len(actual.Subjects) != 1 ||
		actual.Subjects[0] != controlStreamSubject || actual.Mirror != nil || len(actual.Sources) != 0 ||
		actual.SubjectTransform != nil || actual.RePublish != nil || actual.AllowMsgTTL ||
		actual.SubjectDeleteMarkerTTL != 0 || actual.AllowMsgSchedules ||
		actual.Metadata["terrascale-contract"] != "authority-log-v1" {
		return errors.New("existing control log has incompatible consistency, durability, or subject configuration")
	}
	return nil
}

func (r *Runtime) CommitHostMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	if kind == MutationUsageObservation {
		return 0, errors.New("usage observations require verified host authority")
	}
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	return r.commitMutation(ctx, expectedEpoch, kind, subjectKey, operationID, expectedSubjectSequence, payload)
}

func (r *Runtime) CommitHostMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	if verify == nil {
		return 0, errors.New("verified host mutation requires a verifier")
	}
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, verify)
}

func (r *Runtime) commitMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, nil)
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

// ReadHostMutation reads the current committed host record.
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (r *Runtime) CommitPlacementIntent(
	ctx context.Context,
	expectedEpoch uint64,
	databaseID string,
	partitionID string,
	operationID string,
	expectedSequence uint64,
	payload []byte,
) (uint64, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if err := validateMutation(MutationPlacementIntent, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	release, err := r.beginWorkloadGate(ctx, WorkloadScope{DatabaseID: databaseID, PartitionID: partitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	if err := r.requireNoTerminalIntent(ctx, databaseID, partitionID); err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, expectedEpoch, MutationPlacementIntent,
		subjectKey, operationID, expectedSequence, payload, func(check context.Context) error {
			return r.requireNoActiveBackup(check, databaseID, partitionID)
		})
}

func (r *Runtime) workloadGate(scope WorkloadScope) *sync.RWMutex {
	r.terminalMu.Lock()
	defer r.terminalMu.Unlock()
	if r.terminalGates == nil {
		r.terminalGates = make(map[WorkloadScope]*sync.RWMutex)
	}
	gate := r.terminalGates[scope]
	if gate == nil {
		gate = new(sync.RWMutex)
		r.terminalGates[scope] = gate
	}
	return gate
}

func (r *Runtime) beginWorkloadGate(ctx context.Context, scope WorkloadScope) (func(), error) {
	if r == nil || ctx == nil || ctx.Err() != nil {
		return nil, ErrFenced
	}
	if _, err := placementIntentSubjectKey(scope.DatabaseID, scope.PartitionID); err != nil {
		return nil, err
	}
	gate := r.workloadGate(scope)
	gate.RLock()
	if err := ctx.Err(); err != nil {
		gate.RUnlock()
		return nil, err
	}
	return sync.OnceFunc(gate.RUnlock), nil
}

func (r *Runtime) requireNoTerminalIntent(ctx context.Context, databaseID, partitionID string) error {
	_, err := r.ReadTerminalIntent(ctx, databaseID, partitionID)
	if errors.Is(err, ErrNotFound) {
		return nil
	}
	if err == nil {
		return ErrFenced
	}
	return err
}

func (r *Runtime) BeginActiveWorkloadEffect(ctx context.Context, epoch uint64, scope WorkloadScope) (func(), error) {
	if ctx != nil {
		if state, ok := ctx.Value(workloadEffectContextKey{}).(*workloadEffectContext); ok {
			state.mu.Lock()
			if held := state.active[scope]; held != nil {
				if held.runtime != r || held.epoch != epoch {
					state.mu.Unlock()
					return nil, ErrFenced
				}
				held.refs++
				state.mu.Unlock()
				release := sync.OnceFunc(func() { state.release(scope) })
				if err := r.Guard(ctx, epoch); err != nil {
					release()
					return nil, err
				}
				return release, nil
			}
			gate := r.workloadGate(scope)
			gate.RLock()
			if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			if err := r.Guard(ctx, epoch); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			state.active[scope] = &heldWorkloadEffect{runtime: r, epoch: epoch, gate: gate, refs: 1}
			state.mu.Unlock()
			return sync.OnceFunc(func() { state.release(scope) }), nil
		}
	}
	release, err := r.beginWorkloadGate(ctx, scope)
	if err != nil {
		return nil, err
	}
	if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
		release()
		return nil, err
	}
	if err := r.Guard(ctx, epoch); err != nil {
		release()
		return nil, err
	}
	return release, nil
}

func (r *Runtime) ReadTerminalIntent(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrFenced
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	entry, err := readMutation(ctx, r.readStream, r.config.Scope, MutationTerminalIntent, subjectKey)
	if err != nil {
		return LogEntry{}, err
	}
	intent, err := decodeTerminalIntent(entry.Payload)
	if err != nil || intent.Cell != r.config.Scope || intent.DatabaseID != databaseID ||
		intent.PartitionID != partitionID || intent.OperationID != entry.OperationID {
		return LogEntry{}, errors.New("terminal control log identity is invalid")
	}
	return entry, nil
}

func (r *Runtime) ReadPlacementIntent(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, MutationPlacementIntent, subjectKey)
}

func (r *Runtime) CommitMaterialReceipt(ctx context.Context, expectedEpoch uint64,

package authority

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json/v2"
	"errors"
	"fmt"
	"slices"
	"strings"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"

	"github.com/nats-io/nats.go/jetstream"
)

const maxManagedUpdateRecords = 4096
const maxManagedUpdateRequestBytes = 700 << 10

// CommitManagedUpdate appends one immutable operation phase under the
// database's terminal workload gate. Each phase has its own subject, so later
// phases and operations never replace the exact original signed Prepare
// receipt. expectedSequence is the current workload update sequence for
// Prepare, and the exact Prepare receipt sequence for a terminal canary phase.
// verify runs under the authority log's final stream-sequence CAS boundary.
func (r *Runtime) CommitManagedUpdate(
	ctx context.Context,
	epoch uint64,
	record ManagedUpdateRecord,
	expectedSequence uint64,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil || ctx == nil || ctx.Err() != nil {
		return 0, ErrNotLeader
	}
	if err := record.Validate(); err != nil {
		return 0, err
	}
	if record.Cell != r.config.Scope {
		return 0, errors.New("managed update cell differs from authority scope")
	}
	payload, err := json.Marshal(record, json.Deterministic(true))
	if err != nil {
		return 0, err
	}
	scope := WorkloadScope{DatabaseID: record.DatabaseID, PartitionID: record.PartitionID}
	release, err := r.beginWorkloadGate(ctx, scope)
	if err != nil {
		return 0, err
	}
	defer release()
	if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
		return 0, err
	}

	if prior, readErr := r.readManagedUpdatePhase(ctx, record.DatabaseID, record.PartitionID,
		record.OperationID, record.Phase); readErr == nil {
		if bytes.Equal(prior.Payload, payload) {
			return prior.Sequence, nil
		}
		return 0, ErrOperationConflict
	} else if !errors.Is(readErr, ErrNotFound) {
		return 0, readErr
	}
	if err := r.validateManagedUpdateTransition(ctx, record, expectedSequence); err != nil {
		return 0, err
	}
	subjectKey, err := managedUpdateSubjectKey(record.DatabaseID, record.PartitionID,
		record.OperationID, record.Phase)
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationManagedUpdate, subjectKey,
		record.OperationID, 0, payload, func(ctx context.Context) error {
			if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
				return err
			}
			if err := r.requireNoActiveBackup(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
				return err
			}
			if err := r.validateManagedUpdateTransition(ctx, record, expectedSequence); err != nil {
				return err
			}
			if verify != nil {
				return verify(ctx)
			}
			return nil
		})
}

// ReadManagedUpdate returns the latest immutable phase record for one
// database partition, regardless of which operation produced it.
func (r *Runtime) ReadManagedUpdate(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	if r == nil || r.readStream == nil {
		return LogEntry{}, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	entries, err := listManagedUpdateEntries(ctx, r.readStream, r.config.Scope, databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if len(entries) == 0 {
		return LogEntry{}, ErrNotFound
	}
	return entries[len(entries)-1], nil
}

// ReadManagedUpdateOperation returns the exact phase history for one
// operation. It reads the operation's phase subjects directly, so later
// operation records cannot erase the original Prepare receipt.
func (r *Runtime) ReadManagedUpdateOperation(
	ctx context.Context,
	databaseID, partitionID, operationID string,
) ([]LogEntry, error) {
	if r == nil || r.readStream == nil {
		return nil, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readManagedUpdateOperation(ctx, r.readStream, r.config.Scope,
		databaseID, partitionID, operationID)
}

// ListManagedUpdates returns every retained phase receipt for one workload in
// authority sequence order. Invalid or unreadable history is an error.
func (r *Runtime) ListManagedUpdates(ctx context.Context, databaseID, partitionID string) ([]LogEntry, error) {
	if r == nil || r.readStream == nil {
		return nil, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return listManagedUpdateEntries(ctx, r.readStream, r.config.Scope, databaseID, partitionID)
}

func (r *Runtime) validateManagedUpdateTransition(
	ctx context.Context,
	record ManagedUpdateRecord,
	expectedSequence uint64,
) error {
	latest, err := r.ReadManagedUpdate(ctx, record.DatabaseID, record.PartitionID)
	if record.Phase == ManagedUpdatePrepared {
		if errors.Is(err, ErrNotFound) {
			if expectedSequence != 0 {
				return ErrConflict
			}
			return nil
		}
		if err != nil {
			return err
		}
		if latest.Sequence != expectedSequence {
			return ErrConflict
		}
		// A rolling release or a held-seat rollback is a new operation after the
		// previous operation's terminal outcome. Placement verifies each seat's
		// durable predecessor; an unfinished operation blocks any successor.
		if latest.Kind != MutationManagedUpdate {
			return ErrInvalidTransition
		}
		switch ManagedUpdatePhase(latest.SubjectKey[strings.LastIndexByte(latest.SubjectKey, '.')+1:]) {
		case ManagedUpdateCanaryServing, ManagedUpdateHeld:
			return nil
		default:
			return ErrInvalidTransition
		}
	}
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return ErrInvalidTransition
		}
		return err
	}
	prepared, err := r.readManagedUpdatePhase(ctx, record.DatabaseID, record.PartitionID,
		record.OperationID, ManagedUpdatePrepared)
	if err != nil {
		return ErrInvalidTransition
	}
	preparedRecord, err := decodeManagedUpdateRecord(prepared, r.config.Scope,
		record.DatabaseID, record.PartitionID, record.OperationID, ManagedUpdatePrepared)
	if err != nil || !sameManagedUpdateIdentity(preparedRecord, record) ||
		prepared.Sequence != expectedSequence || latest.Sequence != expectedSequence ||
		latest.OperationID != record.OperationID || latest.Kind != MutationManagedUpdate {
		return ErrInvalidTransition
	}
	return nil
}

func (record ManagedUpdateRecord) Validate() error {
	if record.SchemaVersion != 1 || !natsToken.MatchString(record.Cell) ||
		!entityid.Valid(record.DatabaseID) || !entityid.Valid(record.PartitionID) ||
		!entityid.Valid(record.OperationID) ||
		record.Phase != ManagedUpdatePrepared && record.Phase != ManagedUpdateCanaryServing &&
			record.Phase != ManagedUpdateHeld ||
		len(record.SignedRequest) == 0 || len(record.SignedRequest) > maxManagedUpdateRequestBytes ||
		!validTerminalDigest(record.SignedRequestSHA256) ||
		!validTerminalDigest(record.PlacementPayloadDigest) || record.PlacementGeneration == 0 ||
		record.PlacementSequence == 0 || !entityid.Valid(record.CanarySeatID) ||
		record.CanaryDesiredGeneration == 0 || !validTerminalDigest(record.OldArtifactDigest) ||
		!validTerminalDigest(record.CandidateArtifactDigest) ||
		record.CandidateArtifactDigest == record.OldArtifactDigest ||
		!validTerminalDigest(record.CandidateManifestDigest) ||
		!validTerminalDigest(record.CandidateSourceDigest) ||
		!validTerminalDigest(record.DurabilityProfileSHA256) {
		return errors.New("managed update record has incomplete identity or phase")
	}
	digest := sha256.Sum256(record.SignedRequest)
	if hex.EncodeToString(digest[:]) != record.SignedRequestSHA256 {
		return errors.New("managed update request digest differs from its exact signed bytes")
	}
	if record.Phase == ManagedUpdatePrepared {
		if record.Outcome != "" {
			return errors.New("prepared managed update cannot carry an outcome")
		}
	} else if record.Outcome == "" || len(record.Outcome) > 256 ||
		strings.ContainsAny(record.Outcome, "\r\n\x00") {
		return errors.New("terminal managed update phase requires a bounded outcome")
	}
	return nil
}

func sameManagedUpdateIdentity(left, right ManagedUpdateRecord) bool {
	return left.SchemaVersion == right.SchemaVersion && left.Cell == right.Cell &&
		left.DatabaseID == right.DatabaseID && left.PartitionID == right.PartitionID &&
		left.OperationID == right.OperationID &&
		bytes.Equal(left.SignedRequest, right.SignedRequest) &&
		left.SignedRequestSHA256 == right.SignedRequestSHA256 &&
		left.PlacementGeneration == right.PlacementGeneration &&
		left.PlacementPayloadDigest == right.PlacementPayloadDigest &&
		left.PlacementSequence == right.PlacementSequence && left.CanarySeatID == right.CanarySeatID &&
		left.CanaryDesiredGeneration == right.CanaryDesiredGeneration &&
		left.OldArtifactDigest == right.OldArtifactDigest &&
		left.CandidateArtifactDigest == right.CandidateArtifactDigest &&
		left.CandidateManifestDigest == right.CandidateManifestDigest &&
		left.CandidateSourceDigest == right.CandidateSourceDigest &&
		left.DurabilityProfileSHA256 == right.DurabilityProfileSHA256
}

// SameIdentity reports whether two phase records retain the exact signed
// managed-update identity while allowing their phase and outcome to differ.
func (record ManagedUpdateRecord) SameIdentity(other ManagedUpdateRecord) bool {
	return sameManagedUpdateIdentity(record, other)
}

func managedUpdateSubjectKey(databaseID, partitionID, operationID string, phase ManagedUpdatePhase) (string, error) {
	if !entityid.Valid(databaseID) || !entityid.Valid(partitionID) ||
		!entityid.Valid(operationID) ||
		phase != ManagedUpdatePrepared && phase != ManagedUpdateCanaryServing && phase != ManagedUpdateHeld {
		return "", errors.New("managed update subject identity is invalid")
	}
	return strings.Join([]string{databaseID, partitionID, operationID, string(phase)}, "."), nil
}

func (r *Runtime) readManagedUpdatePhase(
	ctx context.Context,
	databaseID, partitionID, operationID string,
	phase ManagedUpdatePhase,
) (LogEntry, error) {
	if r == nil || r.readStream == nil {
		return LogEntry{}, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readManagedUpdatePhase(ctx, r.readStream, r.config.Scope,
		databaseID, partitionID, operationID, phase)
}

func readManagedUpdatePhase(
	ctx context.Context,
	stream jetstream.Stream,
	scope, databaseID, partitionID, operationID string,
	phase ManagedUpdatePhase,
) (LogEntry, error) {
	subjectKey, err := managedUpdateSubjectKey(databaseID, partitionID, operationID, phase)
	if err != nil {
		return LogEntry{}, err
	}
	return readManagedUpdateSubject(ctx, stream, scope, subjectKey, operationID, phase)
}

func readManagedUpdateSubject(
	ctx context.Context,
	stream jetstream.Stream,
	scope, subjectKey, operationID string,
	phase ManagedUpdatePhase,
) (LogEntry, error) {
	entry, err := stream.GetLastMsgForSubject(ctx, mutationSubject(scope, MutationManagedUpdate, subjectKey))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != MutationManagedUpdate ||
		record.SubjectKey != subjectKey {
		return LogEntry{}, errors.New("managed update control log identity is invalid")
	}
	result := LogEntry{Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload)}
	if _, err := decodeManagedUpdateRecord(result, scope, "", "", operationID, phase); err != nil {
		return LogEntry{}, err
	}
	return result, nil
}

func readManagedUpdateOperation(
	ctx context.Context,
	stream jetstream.Stream,
	scope, databaseID, partitionID, operationID string,
) ([]LogEntry, error) {
	entries := make([]LogEntry, 0, 3)
	for _, phase := range []ManagedUpdatePhase{ManagedUpdatePrepared, ManagedUpdateCanaryServing, ManagedUpdateHeld} {
		entry, err := readManagedUpdatePhase(ctx, stream, scope, databaseID, partitionID, operationID, phase)
		if errors.Is(err, ErrNotFound) {
			continue
		}
		if err != nil {
			return nil, err
		}
		entries = append(entries, entry)
	}
	if len(entries) == 0 {
		return nil, ErrNotFound
	}
	slices.SortFunc(entries, compareLogEntrySequence)
	firstPhase := managedUpdatePhaseFromSubject(entries[0].SubjectKey)
	if firstPhase != ManagedUpdatePrepared || len(entries) > 2 {
		return nil, errors.New("managed update history has an invalid phase sequence")
	}
	var identity ManagedUpdateRecord
	for index, entry := range entries {
		phase := managedUpdatePhaseFromSubject(entry.SubjectKey)
		record, err := decodeManagedUpdateRecord(entry, scope, databaseID, partitionID, operationID, phase)
		if err != nil {
			return nil, err
		}
		if index == 0 {
			identity = record
		} else if phase == ManagedUpdatePrepared || !sameManagedUpdateIdentity(identity, record) {
			return nil, errors.New("managed update phase history changed immutable signed request identity")
		}
	}
	return entries, nil
}

func listManagedUpdateEntries(
	ctx context.Context,
	stream jetstream.Stream,
	scope, databaseID, partitionID string,
) ([]LogEntry, error) {
	if _, err := placementIntentSubjectKey(databaseID, partitionID); err != nil {
		return nil, err
	}
	prefix := fmt.Sprintf("%s.%s.placement.managed-update.%s.%s.",
		controlSubjectRoot, scope, databaseID, partitionID)
	info, err := stream.Info(ctx, jetstream.WithSubjectFilter(prefix+">"))
	if err != nil {
		return nil, err
	}
	if err := verifyControlStreamConfig(info.Config, info.Config.Replicas); err != nil {
		return nil, err
	}
	if len(info.State.Subjects) > maxManagedUpdateRecords*3 {
		return nil, ErrListTooLarge
	}
	entries := make([]LogEntry, 0, len(info.State.Subjects))
	operations := make(map[string]struct{})
	for subject := range info.State.Subjects {
		key, ok := strings.CutPrefix(subject, prefix)
		if !ok {
			return nil, errors.New("managed update subject is outside its workload prefix")
		}
		parts := strings.Split(key, ".")
		if len(parts) != 2 || !entityid.Valid(parts[0]) {
			return nil, errors.New("managed update subject has an invalid operation identity")
		}
		phase := ManagedUpdatePhase(parts[1])
		if phase != ManagedUpdatePrepared && phase != ManagedUpdateCanaryServing && phase != ManagedUpdateHeld {
			return nil, errors.New("managed update subject has an invalid phase")
		}
		key = strings.Join([]string{databaseID, partitionID, parts[0], parts[1]}, ".")
		entry, err := readManagedUpdateSubject(ctx, stream, scope, key, parts[0], phase)
		if err != nil {
			return nil, err
		}
		if _, err := decodeManagedUpdateRecord(entry, scope, databaseID, partitionID, parts[0], phase); err != nil {
			return nil, err
		}
		entries = append(entries, entry)
		operations[parts[0]] = struct{}{}
	}
	for operationID := range operations {
		if _, err := readManagedUpdateOperation(ctx, stream, scope, databaseID, partitionID, operationID); err != nil {
			return nil, err
		}
	}
	slices.SortFunc(entries, compareLogEntrySequence)
	return entries, nil
}

func decodeManagedUpdateRecord(
	entry LogEntry,
	scope, databaseID, partitionID, operationID string,
	phase ManagedUpdatePhase,
) (ManagedUpdateRecord, error) {
	var record ManagedUpdateRecord
	if entry.Kind != MutationManagedUpdate || entry.Sequence == 0 || entry.Epoch == 0 ||
		entry.OperationID != operationID || entry.Payload == nil {
		return record, errors.New("managed update log entry identity is invalid")
	}
	if err := json.Unmarshal(entry.Payload, &record, json.RejectUnknownMembers(true)); err != nil {
		return record, err
	}
	canonical, err := json.Marshal(record, json.Deterministic(true))
	if err != nil || !bytes.Equal(entry.Payload, canonical) || record.Validate() != nil ||
		record.Cell != scope || databaseID != "" && record.DatabaseID != databaseID ||
		partitionID != "" && record.PartitionID != partitionID ||
		record.OperationID != operationID || record.Phase != phase {
		return record, errors.New("managed update log payload is noncanonical or differs from its subject")
	}
	wantKey, err := managedUpdateSubjectKey(record.DatabaseID, record.PartitionID, record.OperationID, record.Phase)
	if err != nil || entry.SubjectKey != wantKey {
		return record, errors.New("managed update log subject differs from its signed request identity")
	}
	return record, nil
}

func managedUpdatePhaseFromSubject(subjectKey string) ManagedUpdatePhase {
	_, phase, ok := strings.CutLast(subjectKey, ".")
	if !ok {
		return ""
	}
	return ManagedUpdatePhase(phase)
}

func compareLogEntrySequence(left, right LogEntry) int {
	if left.Sequence < right.Sequence {
		return -1
	}
	if left.Sequence > right.Sequence {
		return 1
	}
	return 0
}

package authority

import (
	"context"
	"errors"
	"sync/atomic"
	"time"
)

type verificationGuardKey struct{}

type verificationGuard struct {
	runtime       *Runtime
	epoch         uint64
	owner         string
	leaseSequence uint64
	watermark     uint64
	subject       string
	operation     string
	expires       time.Time
	active        atomic.Bool
}

// verify already holds r.mu and has selected the global CAS watermark. A nested
// Guard must check the actual lease without renewing it or locking r.mu again.
func (r *Runtime) verify(ctx context.Context, epoch, leaseSequence, watermark uint64,
	subject, operation string, expires time.Time, check func(context.Context) error,
) error {
	guard := &verificationGuard{runtime: r, epoch: epoch, owner: r.ownerID, leaseSequence: leaseSequence,
		watermark: watermark, subject: subject, operation: operation, expires: expires}
	ctx, cancel := context.WithDeadline(ctx, expires)
	guard.active.Store(true)
	defer func() {
		guard.active.Store(false)
		cancel()
	}()
	return check(context.WithValue(ctx, verificationGuardKey{}, guard))
}

func (r *Runtime) guardVerification(ctx context.Context, epoch uint64, guard *verificationGuard) error {
	if guard.runtime != r || guard.epoch != epoch || guard.owner != r.ownerID || guard.subject == "" || guard.operation == "" ||
		!guard.active.Load() || !time.Now().Before(guard.expires) {
		return ErrFenced
	}
	if err := r.checkClock(); err != nil {
		return ErrClockUnhealthy
	}
	current := r.Current()
	if !current.CanMutate() || current.Epoch != epoch || current.Scope != r.config.Scope ||
		current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return ErrFenced
	}
	info, err := r.stream.Info(ctx)
	if err != nil {
		return err
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		return err
	}
	if info.State.LastSeq != guard.watermark {
		return ErrConflict
	}
	entry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
	if err != nil {
		return err
	}
	if entry.Sequence != guard.leaseSequence {
		return ErrConflict
	}
	lease, err := decodeLease(entry.Data)
	if err != nil {
		return errors.Join(ErrLeaseCorrupt, err)
	}
	if !guard.active.Load() || lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID ||
		lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != epoch ||
		lease.Released || !entry.Time.Add(time.Duration(lease.LeaseDuration)).Equal(guard.expires) || !time.Now().Before(guard.expires) {
		return ErrFenced
	}
	return ctx.Err()
}

func (r *Runtime) ReadBackupOperation(ctx context.Context, databaseID, partitionID string) (BackupOperationRecord, uint64, error) {
	key, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	entry, err := r.ReadHostMutation(ctx, MutationBackupOperation, key)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	record, err := decodeBackupRecord(entry.Payload, databaseID, partitionID)
	return record, entry.Sequence, err
}

func (r *Runtime) requireNoActiveBackup(ctx context.Context, databaseID, partitionID string) error {
	record, _, err := r.ReadBackupOperation(ctx, databaseID, partitionID)
	if errors.Is(err, ErrNotFound) {
		return nil
	}
	if err != nil {
		return err
	}
	if record.State != "aborted" && record.State != "complete" {
		return ErrFenced
	}
	return nil
}

func (manifest RuntimeManifest) Validate() error {

	if !knownRegion(manifest.Region) || !entityid.Valid(manifest.SeatID) ||
		!validLowerSHA256Digest(manifest.ArtifactDigest) || !validLowerSHA256Digest(manifest.SourceDigest) ||
		!filepath.IsAbs(manifest.ManagedRuntimeRoot) || filepath.Clean(manifest.ManagedRuntimeRoot) != manifest.ManagedRuntimeRoot ||
		manifest.ManagedRuntimeRoot == "/" || len(manifest.ManagedRuntimeRoot) > 54 ||
		!validFilesystemUUID(manifest.FileSystemUUID) ||
		manifest.FileSystemType != "ext4" && manifest.FileSystemType != "xfs" ||
		!validLowerSHA256Digest(manifest.TrustedKeySHA256) ||
		!validLowerSHA256Digest(manifest.ServerCertificateSHA256) ||
		!validLowerSHA256Digest(manifest.ServerPrivateKeySHA256) ||
		!validLowerSHA256Digest(manifest.ClientCARootsSHA256) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationListenAddress) {
		return fmt.Errorf("%w: incomplete runtime manifest", ErrInvalidIntent)
	}
	peer := manifest.ReplicationPeerMemberID != "" || manifest.ReplicationPeerAddress != "" || manifest.ReplicationServerCASHA256 != ""
	if peer && (!entityid.Valid(manifest.ReplicationPeerMemberID) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationPeerAddress) ||
		!validLowerSHA256Digest(manifest.ReplicationServerCASHA256)) {
		return fmt.Errorf("%w: incomplete runtime peer triple", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.ClientManagedMaterialManifestSHA256) || !peer {
		return fmt.Errorf("%w: schema-5 managed HTTPS requires a pinned client material manifest and outbound peer", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.LiveS3ConfigSHA256) ||
		!validLowerSHA256Digest(manifest.LiveS3TargetSHA256) || manifest.LiveS3Credential.Validate() != nil {
		return fmt.Errorf("%w: managed ObjectDurable target or credential pin is incomplete", ErrInvalidIntent)
	}
	if manifest.BackupManifestSHA256 != "" {
		if !validLowerSHA256Digest(manifest.BackupManifestSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3ConfigSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3TargetSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3CredentialSHA256) ||
			!validLowerSHA256Digest(manifest.BackupDataKeySHA256) ||
			manifest.BackupS3TargetSHA256 == manifest.LiveS3TargetSHA256 ||
			manifest.BackupOwner && (manifest.BackupS3Credential.Validate() != nil ||
				manifest.BackupDataKey.Validate() != nil ||
				manifest.BackupS3Credential.SecretOCID == manifest.LiveS3Credential.SecretOCID ||
				manifest.BackupS3Credential.SecretOCID == manifest.BackupDataKey.SecretOCID) ||
			!manifest.BackupOwner && (manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
				manifest.BackupDataKey != (oci.SecretVersionReference{})) {
			return fmt.Errorf("%w: managed backup material pins are incomplete", ErrInvalidIntent)
		}
	} else if manifest.BackupS3ConfigSHA256 != "" || manifest.BackupS3TargetSHA256 != "" ||
		manifest.BackupS3CredentialSHA256 != "" || manifest.BackupDataKeySHA256 != "" ||
		manifest.BackupOwner || manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
		manifest.BackupDataKey != (oci.SecretVersionReference{}) {
		return fmt.Errorf("%w: partial managed backup material pins", ErrInvalidIntent)
	}
	if manifest.SQLSchemaBundleSHA256 != "" && !validLowerSHA256Digest(manifest.SQLSchemaBundleSHA256) {
		return fmt.Errorf("%w: invalid SQL schema bundle pin", ErrInvalidIntent)
	}
	return nil
}

func (manifest RuntimeManifest) Digest() (string, error) {

	if err := manifest.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(manifest)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

// ComputeTuple is the explicit Flex compute shape pinned by a signed profile.
// OCPUs and memory are whole provider units; fractional values are not accepted.
type ComputeTuple struct {
	Shape       string `json:"shape"`
	WholeOCPUs  uint32 `json:"whole_ocpus"`
	MemoryInGBs uint32 `json:"memory_in_gbs"`
}

// ManagedHostProfile pins one selected region's OCI compute tuple and guest
// memory contract. The byte values are supplied by the operator and are never
// inferred or defaulted by placement admission.
type ManagedHostProfile struct {
	Region                 oci.Region   `json:"region"`
	Compute                ComputeTuple `json:"compute"`
	ProcessMemoryBytes     uint64       `json:"process_memory_bytes"`
	MemoryHeadroomBytes    uint64       `json:"memory_headroom_bytes"`
	CgroupMemoryMaxBytes   uint64       `json:"cgroup_memory_max_bytes"`
	SystemReserveBytes     uint64       `json:"system_reserve_bytes"`
	AllocatableMemoryBytes uint64       `json:"allocatable_memory_bytes"`
}

// ProfileDigest returns the lower-case SHA-256 of deterministic JSON for the
// entire region profile, including its region, compute tuple and all byte
// limits. Placement generation is pinned separately by Intent.Generation.
func (profile ManagedHostProfile) ProfileDigest() (string, error) {
	if err := profile.Validate(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(profile)
	if err != nil {
		return "", fmt.Errorf("encode managed host profile: %w", err)
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

func (profile ManagedHostProfile) Validate() error {
	if !knownRegion(profile.Region) || !validComputeShape(profile.Compute.Shape) ||
		profile.Compute.WholeOCPUs == 0 || profile.Compute.MemoryInGBs == 0 {
		return fmt.Errorf("%w: managed profile region or compute tuple", ErrInvalidIntent)
	}
	values := [...]uint64{
		profile.ProcessMemoryBytes, profile.MemoryHeadroomBytes, profile.CgroupMemoryMaxBytes,
		profile.SystemReserveBytes, profile.AllocatableMemoryBytes,
	}
	for _, value := range values {
		if value == 0 || value > maxManagedMemoryByteValue || value%managedMemoryPageBytes != 0 {
			return fmt.Errorf("%w: memory limits must be positive, signed-range, page-aligned byte values", ErrInvalidIntent)
		}
	}
	minimumHeadroom := max(managedMemoryGiB, profile.ProcessMemoryBytes/4)
	// MemoryInGBs is uint32, so this exact multiplication stays below 2^62.
	// GiB is the conservative upper bound whether the SDK's GB means decimal
	// or binary units; the host still verifies actual guest capacity.
	nominalMemoryBytes := uint64(profile.Compute.MemoryInGBs) * managedMemoryGiB
	if profile.ProcessMemoryBytes < 4*managedMemoryGiB || profile.MemoryHeadroomBytes < minimumHeadroom ||
		profile.MemoryHeadroomBytes >= profile.ProcessMemoryBytes ||
		profile.ProcessMemoryBytes > profile.CgroupMemoryMaxBytes ||
		profile.CgroupMemoryMaxBytes > profile.AllocatableMemoryBytes ||
		profile.SystemReserveBytes > maxManagedMemoryByteValue-profile.AllocatableMemoryBytes ||
		profile.AllocatableMemoryBytes > nominalMemoryBytes ||
		profile.SystemReserveBytes > nominalMemoryBytes-profile.AllocatableMemoryBytes {
		return fmt.Errorf("%w: managed process, headroom, cgroup, allocatable memory and reserve bounds", ErrInvalidIntent)
	}
	return nil
}

func (intent Intent) Validate() error {
	if intent.SchemaVersion != IntentSchemaVersion ||
		!entityid.Valid(intent.DatabaseID) ||
		!entityid.Valid(intent.PartitionID) || intent.Generation == 0 ||
		len(intent.ActiveRegions) < 1 || len(intent.ActiveRegions) > len(regionsInOrder) {
		return fmt.Errorf("%w: schema, identity, generation or region count", ErrInvalidIntent)
	}
	for index, region := range intent.ActiveRegions {
		if !knownRegion(region) {
			return fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
		}
		if slices.Contains(intent.ActiveRegions[:index], region) {
			return fmt.Errorf("%w: repeated region %q", ErrInvalidIntent, region)
		}
	}
	if !canonicalRegions(intent.ActiveRegions) || len(intent.ManagedHostProfiles) != len(intent.ActiveRegions) {
		return fmt.Errorf("%w: managed profiles must exactly cover canonically ordered selected regions", ErrInvalidIntent)
	}
	for index, profile := range intent.ManagedHostProfiles {
		if profile.Region != intent.ActiveRegions[index] {
			return fmt.Errorf("%w: managed profiles are missing, foreign or out of canonical order", ErrInvalidIntent)
		}
		if err := profile.Validate(); err != nil {
			return err
		}
	}
	if err := intent.CanonicalRoster.Validate(intent.ActiveRegions); err != nil {
		return err
	}
	if len(intent.RuntimeManifests) != len(intent.CanonicalRoster.Rows) {
		return fmt.Errorf("%w: runtime manifests must cover every canonical roster seat", ErrInvalidIntent)
	}
	uuids := make(map[string]struct{}, len(intent.RuntimeManifests))
	for index, manifest := range intent.RuntimeManifests {
		row := intent.CanonicalRoster.Rows[index]
		if err := manifest.Validate(); err != nil {
			return err
		}
		if manifest.Region != row.Region || manifest.SeatID != row.SeatID ||
			manifest.TrustedKeySHA256 != intent.CanonicalRoster.Authority.TrustedKeySHA256 ||
			manifest.ReplicationPeerMemberID == row.MemberID {
			return fmt.Errorf("%w: runtime manifest does not match canonical roster seat", ErrInvalidIntent)
		}
		if manifest.ReplicationPeerMemberID != "" && !slices.ContainsFunc(intent.CanonicalRoster.Rows, func(peer CanonicalRosterRow) bool {
			return peer.MemberID == manifest.ReplicationPeerMemberID
		}) {
			return fmt.Errorf("%w: runtime peer is outside the signed roster", ErrInvalidIntent)
		}
		if _, exists := uuids[manifest.FileSystemUUID]; exists {
			return fmt.Errorf("%w: duplicate runtime filesystem UUID", ErrInvalidIntent)
		}
		uuids[manifest.FileSystemUUID] = struct{}{}
	}
	return nil
}

// ValidateForAdmission limits newly signed managed placements to schema 5.
// Only the current schema is accepted.
func (intent Intent) ValidateForAdmission() error {
	if intent.SchemaVersion != IntentSchemaVersion {
		return fmt.Errorf("%w: schema %d is historical and cannot authorize a new managed placement", ErrInvalidIntent, intent.SchemaVersion)
	}
	return intent.Validate()
}

func (roster CanonicalRoster) isZero() bool {
	return roster.ClusterID == "" && roster.TenantID == "" && roster.DatabaseID == "" &&
		roster.ShardID == 0 && roster.Authority == (AuthorityReference{}) && len(roster.Rows) == 0
}

func (roster CanonicalRoster) Validate(activeRegions []oci.Region) error {

	if !lowerHex(roster.ClusterID, 32) || allZeroHex(roster.ClusterID) ||
		!entityid.Valid(roster.TenantID) || !entityid.Valid(roster.DatabaseID) ||
		roster.ShardID == 0 || roster.Authority.Validate() != nil ||
		len(roster.Rows) != len(activeRegions)*2 {
		return fmt.Errorf("%w: canonical roster shared scope or row count", ErrInvalidIntent)
	}

	memberIDs := make(map[string]struct{}, len(roster.Rows))
	tlsLeafHashes := make(map[string]struct{}, len(roster.Rows))
	serverNames := make(map[string]struct{}, len(roster.Rows))
	failureDomains := make(map[oci.Region]string, len(activeRegions))
	for index, row := range roster.Rows {
		region := activeRegions[index/2]
		seatID := permanentMember(region)
		if index%2 == 1 {
			seatID = elasticMember(region)
		}
		if row.Region != region || row.SeatID != seatID || !validFailureDomain(row.FailureDomain) ||
			!entityid.Valid(row.MemberID) || !lowerHex(row.Incarnation, 32) || allZeroHex(row.Incarnation) ||
			!validLowerSHA256Digest(row.TLSLeafSHA256) || !validServerName(row.ServerName) {
			return fmt.Errorf("%w: invalid or noncanonical row %d in TerraBase member roster", ErrInvalidIntent, index)
		}
		if _, exists := memberIDs[row.MemberID]; exists {
			return fmt.Errorf("%w: repeated TerraBase member ID %q", ErrInvalidIntent, row.MemberID)
		}
		if _, exists := tlsLeafHashes[row.TLSLeafSHA256]; exists {
			return fmt.Errorf("%w: repeated TerraBase TLS leaf hash", ErrInvalidIntent)
		}
		if _, exists := serverNames[row.ServerName]; exists {
			return fmt.Errorf("%w: repeated TerraBase member server name %q", ErrInvalidIntent, row.ServerName)
		}
		if index%2 == 0 {
			failureDomains[region] = row.FailureDomain
		} else if failureDomains[region] == row.FailureDomain {
			return fmt.Errorf("%w: TerraBase members in region %s share a failure domain", ErrInvalidIntent, region)
		}
		memberIDs[row.MemberID] = struct{}{}
		tlsLeafHashes[row.TLSLeafSHA256] = struct{}{}
		serverNames[row.ServerName] = struct{}{}
	}
	return nil
}

func (authority AuthorityReference) Validate() error {
	if authority.Version != 2 || authority.Epoch == 0 ||
		!validLowerSHA256Digest(authority.ConfigurationID) || allZeroHex(authority.ConfigurationID) ||
		!validLowerSHA256Digest(authority.CertificateSHA256) || !validLowerSHA256Digest(authority.TrustedKeySHA256) {
		return fmt.Errorf("%w: invalid TerraBase authority reference", ErrInvalidIntent)
	}
	return nil
}

// CanonicalRosterDigest returns SHA-256 over deterministic canonical JSON for
// the roster. It does not verify signatures or the referenced certificate.
func (intent Intent) CanonicalRosterDigest() (string, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return "", err
	}
	encoded, err := protocol.EncodeJSON(intent.CanonicalRoster)
	if err != nil {
		return "", fmt.Errorf("encode canonical TerraBase roster: %w", err)
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}

